const chaptersData = {
    // ==================== 适用性与概述 ====================
        applicability: {
        title: "适用性与概述 - ORG Applicability",
        sections: [
            { subtitle: "适用性 (Applicability)", eng: "Section 1 addresses the organization and management system of an operator for the purpose of ensuring the safety and security of aircraft operations.\n\nIndividual ORG provisions or sub-specifications within an ORG provision that:\n• Do not begin with a conditional phrase are applicable to all operators unless determined otherwise by the Auditor.\n• Begin with a conditional phrase (\"If the Operator...\") are applicable if the operator meets the condition(s) stated in the phrase.\n\nMany ORG provisions are repeated in one or more other sections of the ISM (as indicated by the ► symbol). Refer to the IOSA Audit Handbook for information relevant to the proper internal auditing of repeated ORG ISARPs.\n\nORG 2.1.4 in this section is applicable only to an operator that is currently on the IOSA Registry and is being audited for the purpose of registration renewal.", zh: "第1部分旨在确保航空器运行的安全与安保，涉及运营人的组织和管理体系。\n\n不以条件短语开头的单个ORG条款或子规范适用于所有运营人（除非审计员另行判定）；以条件短语（\"如果运营人…\"）开头的条款，仅在运营人满足所述条件时适用。\n\n许多ORG条款在ISM的其他一个或多个部分中重复（如►符号所示）。关于重复ORG ISARPs正确内部审计的相关信息，请参阅IOSA审计手册。\n\n本部分中的ORG 2.1.4仅适用于当前已在IOSA登记册中、为换证注册而接受审计的运营人。" },
            { subtitle: "通用指导 (General Guidance)", eng: "Definitions of technical terms used in this ISM Section 1, as well as the meaning of abbreviations and acronyms are found in the IATA Reference Manual for Audit Programs (IRM).", zh: "ISM第1部分中使用的技术术语、缩略语和首字母缩略词的定义见IATA《审计项目参考手册》(IRM)。" }
        ]
    },
    general_guidance: {
        title: "通用指导 - General Guidance",
        sections: [
            { subtitle: "通用指导", eng: "Definitions of technical terms used in this ISM Section 1, as well as the meaning of abbreviations and acronyms are found in the IATA Reference Manual for Audit Programs (IRM).", zh: "ISM第1部分中使用的技术术语、缩略语和首字母缩略词的定义见IATA《审计项目参考手册》(IRM)。" }
        ]
    },
    // ==================== 第一部分：管理与控制 ====================
        mgmt_overview: {
        title: "1.1 管理系统概述 - Management System Overview",
        sections: [
            { subtitle: "ORG 1.1.1 管理系统", eng: "The Operator shall have a management system that has continuity throughout the organization and ensures control of operations and management of safety and security outcomes. [MA] (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed organizational management system structure.\n▪ Assessed status of conformity with all other ORG management system ISARPs.\n▪ Coordinated to verify status of conformity with management system ISARPs in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Operations, Operator, Organogram, Safety (Operational), Security (Aviation) and State.\nA management system is documented in controlled company media at both the corporate and operational levels. Manuals or controlled electronic media are acceptable means of documenting the management system.\nDocumentation provides a comprehensive description of the scope, structure and functionality of the management system and depicts lines of accountability throughout the organization, as well as authorities, duties, responsibilities and the interrelation of functions and activities within the system for ensuring safe and secure operations.\nAcceptable means of documentation include, but are not limited to, organograms (organization charts), job descriptions and other descriptive written material that define and clearly delineate the management system.\nDocumentation also reflects a functional continuity within the management system that ensures the entire organization works as a system and not as a group of independent or fragmented units (i.e., silo effect).\nAn effective management system is fully implemented and functional with a clear consistency and unity of purpose between corporate management and management in the operational areas.\nThe management system ensures compliance with all applicable standards and regulatory requirements. In addition to internal standards and regulations of the State, an operator may also be required to comply with authorities that have jurisdiction over operations that are conducted over the high seas or within a foreign country.\n\nAssessment Tool\nDesired Outcome: The organization and related systems, processes and resources are managed in an effective and efficient manner, enabling the organization to continuously improve its safety and security performance and overall effectiveness. The organization is managed as a single interconnected system with well managed interfaces.\nSuitability Considerations: Size, scope and complexity of all management systems and processes based on the complexity of the organization.\nC1 (Established): There are processes in place to identify improvements to the management system and the Operator implements identified improvements effectively.\nC2 (Established): Operator clearly identifies the organizational processes, including interfaces through a system description, to define the scope of the Safety Management System and Compliance/Quality Management System.\nC3 (Established): Financial resources are allocated sufficiently and appropriately to support and improve the performance of Safety Management System and Compliance/Quality Management System.\nC4 (Mature): There is an effective integration of Safety Management System and Compliance/Quality Management System.\nC5 (Mature): The Management System components and processes are effectively deployed and interlinked throughout the organization.\nC6 (Mature): The Operator's documentation is designed to go beyond conformity, with reasonable, appropriate level of details, and processes are written in a lean and easy to understand manner.\nC7 (Mature): There is an effective integration of all applicable management systems (e.g. ISO 9001, Quality Management System (QMS), Compliance Management System (CMS), Safety Management System (SMS), Security Management System (SeMS) etc.)\nC8 (Leading): The Management System, through a process-based approach, designs, manages, and improves processes to optimize the customer satisfaction and safety performance.\nC9 (Leading): The Operator's Compliance/Quality Management System goes beyond minimum conformity requirements and uses operational efficiency and/or process improvement methodologies such as lean management.", zh: "运营人应建立一个贯穿整个组织的管理系统，确保持续控制运行并管理安全与安保结果。[MA] (GM) ►\n\n审计员行动：\n▪ 识别/评估组织管理系统结构\n▪ 评估与其他ORG管理系统ISARPs的符合性状态\n▪ 协调验证所有运行领域管理系统ISARPs的符合性状态\n▪ 其他行动（请说明）\n\n指导材料：\n关于运行、运营人、组织架构图、安全（运行）、安保（航空）和国家等定义，请参阅IRM。\n管理系统记录在公司和运行层面的受控公司媒介中。手册或受控电子媒介是可接受的管理系统文件化方式。\n文件提供了管理系统范围、结构和功能的全面描述，并描述了整个组织的问责线，以及系统内确保安全可靠运行的权限、职责、责任以及职能和活动的相互关系。\n可接受的文件化方式包括但不限于：组织架构图、职位说明书和其他定义并清晰描述管理系统的描述性书面材料。\n文件还应反映管理系统内的职能连续性，确保整个组织作为一个系统工作，而不是作为独立或分散的单位（即孤岛效应）工作。\n一个有效的管理系统应完全实施并发挥作用，公司管理层和运行管理层之间具有清晰的一致性和目标统一性。\n管理系统确保符合所有适用标准和法规要求。除了国家的内部标准和法规外，运营人可能还需要遵守对公海或外国境内运行具有管辖权的当局的要求。\n\n评估工具\n预期结果：组织及相关系统、流程和资源以有效和高效的方式管理，使组织能够持续改进其安全和安保绩效及整体有效性。组织作为一个具有良好管理接口的单一互联系统进行管理。\n充分性考虑：基于组织复杂性的所有管理系统和流程的规模、范围和复杂性。\nC1（建立）：已建立识别管理系统改进的流程，运营人有效实施已识别的改进。\nC2（建立）：运营人通过系统描述明确识别组织流程，包括接口，以定义安全管理体系和合规/质量管理体系的范围。\nC3（建立）：财务资源得到充分和适当的分配，以支持和改进安全管理体系和合规/质量管理体系的绩效。\nC4（成熟）：安全管理体系和合规/质量管理体系有效整合。\nC5（成熟）：管理系统的组成部分和流程在整个组织中得到有效部署和互联。\nC6（成熟）：运营人的文件设计超越符合性要求，具有合理、适当的详细程度，流程以精简且易于理解的方式编写。\nC7（成熟）：所有适用的管理系统（例如ISO 9001、质量管理体系、合规管理体系、安全管理体系、安保管理体系等）有效整合。\nC8（领先）：管理系统通过基于流程的方法设计、管理和改进流程，以优化客户满意度和安全绩效。\nC9（领先）：运营人的合规/质量管理体系超越最低符合性要求，并运用运行效率和/或流程改进方法论，例如精益管理。" },
            { subtitle: "ORG 1.1.2 责任人", eng: "The Operator shall identify one senior management official as the accountable executive (AE) who is accountable for performance of the management system as specified in ORG 1.1.1 and:\n(i) Irrespective of other functions, is accountable on behalf of the Operator for the implementation and maintenance of the safety management system (SMS) throughout the organization;\n(ii) Has the authority to ensure the planning and allocation of resources necessary to manage safety and security risks to aircraft operations;\n(iii) Has overall accountability for ensuring operations are conducted in accordance with conditions and restrictions of the Air Operator Certificate (AOC), and in compliance with applicable regulations and standards of the Operator. [SMS] (GM)\n\nAuditor Actions:\n▪ Identified senior management official designated as the AE for the conduct of operations.\n▪ Examined management system structure and organizational lines of accountability.\n▪ Examined job description of designated AE (focus: accountability/responsibilities are as specified in the standard).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Accountability, Accountable Executive (AE), Air Operator Certificate (AOC), Authority, Aircraft Operations, Responsibility, Operations Manual (OM), Safety Management System (SMS), Safety Risk Management and Senior Management.\nThe requirement for an AE is an element of the Safety Policy and Objectives component of the SMS framework.\nThe designation of an AE means the accountability for operational quality, safety and security performance is placed at a level in the organization having the authority to take action to ensure the management system is effective. Therefore, the AE is typically the chief executive officer (CEO), although, depending on the type and structure of the organization, it could be a different senior official (e.g. chairperson/member of the board of directors, company owner).\nThe AE has the authority, which includes financial control, to make policy decisions, provide adequate human and physical resources, resolve operational quality, safety and security issues and, in general, ensure necessary system components are in place and functioning properly.\nIn terms of resources, the AE would have the overall responsibility for ensuring, not only adequate numbers of personnel, but also that positions within the SMS are filled by personnel in accordance with ORG 1.5.3. Additionally, the AE would be responsible for ensuring the SMS is provided with adequate facilities, workspace equipment and supporting services as specified in ORG 1.5.2.\nIn an SMS, the AE would typically have:\n• Ultimate responsibility and accountability for the safety of the entire operation together with the implementation and maintenance of the SMS;\n• Responsibility for ensuring the SMS is properly implemented in all areas of the organization and performing in accordance with specified requirements.\nThe AE also is responsible for ensuring the organization is in compliance with requirements of applicable authorities (i.e. regulations), as well as its own policies and procedures, which may exceed existing regulations or address areas that are not regulated (e.g. ground handling operations). An operator's policies and procedures are typically published in its Operations Manual (OM).\nTo ensure that the operator continues to meet applicable requirements, the AE might designate a manager with the responsibility for ensuring activities of the operator are monitored for compliance with the applicable regulatory requirements, as well as any additional requirements as established by the operator, and that these activities are being carried out properly under the supervision of the head of relevant functional areas.\nExpanded guidance may be found in the ICAO SMM, Document 9859.", zh: "运营人应指定一名高级管理人员作为责任人（AE），对ORG 1.1.1所述管理系统的绩效负责，并且：\n(i) 不论其他职能如何，代表运营人对整个组织实施和维护安全管理体系（SMS）负责；\n(ii) 有权确保规划和分配管理航空器运行安全与安保风险所需的资源；\n(iii) 对确保按照航空运营人证书（AOC）的条件和限制开展运行，并遵守适用法规和运营人标准承担总体责任。[SMS] (GM)\n\n审计员行动：\n▪ 识别被指定负责运行的高级管理人员作为AE\n▪ 检查管理系统结构和组织问责线\n▪ 检查指定AE的职位描述（重点：问责制/职责符合标准要求）\n▪ 访谈AE和/或指定管理代表\n▪ 其他行动（请说明）\n\n指导材料：\n关于问责制、责任人、航空运营人证书、当局、航空器运行、责任、运行手册、安全管理体系、安全风险管理和高级管理等定义，请参阅IRM。\n对AE的要求是SMS框架中安全政策和目标组成部分的一个要素。\n指定AE意味着运行质量、安全和安保绩效的问责制被置于组织中有权采取行动确保管理系统有效的层级。因此，AE通常为首席执行官（CEO），但根据组织的类型和结构，也可能是不同的高级官员（例如董事会主席/成员、公司所有者）。\nAE拥有包括财务控制在内的权力，可以制定政策决策、提供充足的人力和物力资源、解决运行质量、安全和安保问题，并总体上确保必要的系统组件到位并正常运行。\n在资源方面，AE将全面负责确保不仅有足够数量的人员，而且SMS内的职位由符合ORG 1.5.3要求的人员担任。此外，AE将负责确保SMS获得ORG 1.5.2中规定的充足设施、工作空间设备和支持服务。\n在SMS中，AE通常具有：\n• 对整体运行安全以及SMS实施和维护的最终责任和问责；\n• 确保SMS在组织所有区域得到正确实施并按照要求运行的职责。\nAE还负责确保组织符合适用当局的要求（即法规），以及其自身的政策和程序，这些政策和程序可能超出现有法规或解决未受监管的领域（例如地面操作运行）。运营人的政策和程序通常发布在其运行手册（OM）中。\n为了确保持续符合适用要求，AE可以指定一名经理，负责监督运营人的活动是否符合适用法规要求以及运营人制定的任何额外要求，并确保这些活动在相关职能领域负责人的监督下正确进行。\n扩展指导可参见ICAO SMM，文件9859。" },
            { subtitle: "ORG 1.1.3 岗位负责人", eng: "If required by the State of the Operator (hereinafter, the State), the Operator shall have post holders within the management system that are acceptable to the Authority and have the responsibility for ensuring, in their respective defined operational areas:\n(i) The management of safety and security risks to aircraft operations;\n(ii) Operations are conducted in accordance with conditions and restrictions of the AOC, and in compliance with applicable regulations and standards of the Operator. (GM) ►\n\nAuditor Actions:\n▪ Identified post holders accountable for the conduct of operations.\n▪ Examined management system structure and organizational lines of accountability.\n▪ Examined job descriptions of all post holders throughout the organization (focus: accountability/responsibilities are as specified in the standard).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Post Holder.\nManagers in such positions might be referred to as post holders, directors or another title as specified by each State.", zh: "如运营人所在国家（以下简称\"国家\"）有要求，运营人应在管理系统中设立局方接受的岗位负责人，负责在其各自定义的运行领域确保：\n(i) 管理航空器运行的安全与安保风险；\n(ii) 按照AOC的条件和限制开展运行，并遵守适用法规和运营人标准。(GM) ►\n\n审计员行动：\n▪ 识别对运行负责的岗位负责人\n▪ 检查管理系统结构和组织问责线\n▪ 检查整个组织所有岗位负责人的职位描述（重点：问责制/职责符合标准要求）\n▪ 访谈AE和/或指定管理代表\n▪ 其他行动（请说明）\n\n指导材料：\n岗位负责人的定义请参阅IRM。\n此类职位的经理可能被称为岗位负责人、主任或各国指定的其他头衔。" },
            { subtitle: "ORG 1.1.4 SMS经理", eng: "The Operator shall designate a manager who is responsible for the implementation, maintenance and day-to-day administration of the SMS throughout the organization on behalf of the AE and senior management. [SMS] (GM)\n\nAuditor Actions:\n▪ Identified designated manager for day-to-day administration and oversight of the SMS.\n▪ Examined SMS organizational structure.\n▪ Examined job description of SMS manager (focus: assigned responsibility for organizational implementation of SMS).\n▪ Interviewed SMS manager and/or designated representative.\n▪ Other Actions (Specify)\n\nGuidance:\nThe requirement for a manager that focuses on the administration and oversight of the SMS on behalf of the AE is an element of the Safety Policy and Objectives component of the SMS framework.\nThe individual assigned responsibility for organizational implementation of an SMS is ideally a management official that reports to the AE. Also, depending on the size, structure and scope of an operator's organization, as well as the complexity of its operations, such individual may be assigned functions in addition to those associated with the SMS manager position provided those functions do not result in a conflict of interest.\nThe title assigned to the designated manager will vary for each organization. Regardless of title, the manager is the designated organizational focal point for the day-to-day development, administration and maintenance of the SMS (i.e. functions as the SMS champion). It is important that such manager has the necessary degree of authority when coordinating and addressing safety matters throughout the organization.\nWhereas the designated manager has responsibility for day-to-day oversight of the SMS, overall accountability for organizational safety rests with the AE. Likewise, post holders (refer to ORG 1.1.3) or operational managers always retain the responsibility (and thus are accountable) for ensuring safety in their respective areas of operations.\nNote: Depending on the size of an operator's organization and the complexity of its operations, the responsibilities for implementation and maintenance of the SMS (i.e. fulfillment of the SMS manager role) may be assigned to one or more persons.\nExpanded guidance may be found in the ICAO SMM, Document 9859.", zh: "运营人应指定一名经理，代表责任人和高级管理层负责在整个组织内实施、维护和日常管理SMS。[SMS] (GM)\n\n审计员行动：\n▪ 识别被指定负责SMS日常管理和监督的经理\n▪ 检查SMS组织结构\n▪ 检查SMS经理的职位描述（重点：被分配负责组织SMS实施的责任）\n▪ 访谈SMS经理和/或指定代表\n▪ 其他行动（请说明）\n\n指导材料：\n指定一名经理专注于代表AE管理和监督SMS的要求是SMS框架中安全政策和目标组成部分的一个要素。\n被分配负责组织SMS实施的人员最好是向AE报告的管理官员。同时，根据运营人组织的规模、结构和范围以及其运行的复杂性，该人员除了与SMS经理职位相关的职能外，还可能被分配其他职能，前提是这些职能不会导致利益冲突。\n指定经理的头衔因组织而异。无论头衔如何，该经理是指定的组织联络点，负责SMS的日常制定、管理和维护（即充当SMS倡导者）。重要的是，该经理在协调和处理整个组织的安全事务时具有必要的权威。\n虽然指定经理负责SMS的日常监督，但组织安全的总体问责仍由AE承担。同样，岗位负责人（见ORG 1.1.3）或运行经理始终保留确保各自运行领域安全的责任（从而承担问责）。\n注：根据运营人组织的规模和运行的复杂性，SMS实施和维护的职责（即履行SMS经理角色）可以分配给一个或多个人。\n扩展指导可参见ICAO SMM，文件9859。" },
            { subtitle: "ORG 1.1.5–1.1.9", eng: "(Intentionally open)", zh: "（有意留空）" },
            { subtitle: "ORG 1.1.10 SMS整合", eng: "The Operator shall have an SMS that is implemented and integrated throughout the organization to ensure management of the safety risks associated with aircraft operations. [SMS] (GM)\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all standards (not recommended practices) that are identified by the [SMS] symbol.\n\nAuditor Actions:\n▪ Identified/Assessed safety management system (SMS) structure.\n▪ Interviewed AE and/or designated management representative(s).\n▪ Assessed status of conformity with all ORG SMS standards.\n▪ Coordinated to verify status of conformity with SMS standards in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of IOSA Operator, and State Safety Program (SSP).\nIOSA specifications for an operator's SMS are derived from the SMS Framework, which is published in Annex 19 to the Convention on International Civil Aviation (ICAO Annex 19). The SMS Framework specifies the four major components and 12 elements that make up the basic structure of an SMS.\nWhere applicable, an SMS is designed and implemented in accordance with the State Safety Program (SSP). The manner in which the elements of SMS are implemented typically reflects the size and complexity of the operator's organization.\nIn general, an SMS is designed and implemented to:\n• Identify safety hazards in operations;\n• Ensure remedial action is implemented to control safety risks;\n• Provide for ongoing monitoring and assessment of safety performance;\n• Make continual improvement to the level of safety in operations.\nThe specific requirements for each operator's SMS will normally be found in the regulations associated with the SSP. In addition, states typically publish guidance designed to assist operators in the implementation of SMS.\nA description of an operator's SMS is contained in documentation as specified in ORG 2.5.4.\nExpanded guidance may be found in the ICAO Safety Management Manual (ICAO SMM), Document 9859.", zh: "运营人应建立SMS，并在整个组织内实施和整合，以确保管理与航空器运行相关的安全风险。[SMS] (GM)\n\n注：仅当运营人符合所有标有[SMS]符号的标准（非推荐实践）时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估安全管理体系（SMS）结构\n▪ 访谈AE和/或指定管理代表\n▪ 评估与所有ORG SMS标准的符合性状态\n▪ 协调验证所有运行领域SMS标准的符合性状态\n▪ 其他行动（请说明）\n\n指导材料：\nIOSA运营人和国家安全计划（SSP）的定义请参阅IRM。\nIOSA对运营人SMS的规范源自《国际民用航空公约》附件19（ICAO附件19）中发布的SMS框架。SMS框架规定了构成SMS基本结构的四个主要组成部分和12个要素。\n在适用的情况下，SMS根据国家安全计划（SSP）设计和实施。SMS要素的实施方式通常反映了运营人组织的规模和复杂性。\n通常，SMS的设计和实施是为了：\n• 识别运行中的安全危险；\n• 确保实施补救措施以控制安全风险；\n• 提供对安全绩效的持续监控和评估；\n• 持续改进运行中的安全水平。\n每个运营人SMS的具体要求通常可以在与SSP相关的法规中找到。此外，各国通常会发布旨在帮助运营人实施SMS的指导材料。\n运营人SMS的描述包含在ORG 2.5.4规定的文件中。\n扩展指导可参见ICAO安全管理手册（ICAO SMM），文件9859。" }
        ]
    },
           mgmt_commitment: {
        title: "1.2 管理承诺 - Management Commitment",
        sections: [
            { subtitle: "ORG 1.2.1 安全政策", eng: "The Operator shall have a corporate safety policy that reflects the organizational commitment to safety, including the promotion of a positive safety culture. Such policy shall be communicated throughout the organization and include the following:\n(i) A statement about the provision of the necessary resources for the implementation of the safety policy;\n(ii) A commitment to the continual improvement of the organization and the management system;\n(iii) A commitment to a periodic review of the policy to ensure its continued relevance to the organization. [SMS] [MA] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed corporate safety policy (focus: organizational commitment to safety/provision of necessary resources).\n▪ Interviewed AE, SMS manager and/or designated management representative.\n▪ Examined examples of corporate communication: (focus: safety policy communicated throughout organization).\n▪ Coordinated to verify communication of safety policy in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Quality Management System (QMS).\nThe requirement for an operator to have a defined safety policy is an element of the Safety Policy and Objectives component of the SMS framework.\nThe policy of an operator reflects the commitment of senior management to ensuring continual measurement and evaluation as well as the implementation of changes that improve the management system and the culture. Ideas for improvement may come from internal and external sources. Therefore, the organization would be constantly monitoring all sources and willing to make changes as necessary to keep the management system refreshed and strongly focused on improving operational quality, safety and security performance.\nThe safety policy typically also reflects the commitment of senior management to ensure:\n• Compliance with applicable regulations and standards of the Operator;\n• The management of safety and security risks to aircraft operations;\n• The promotion of safety and security awareness;\n• Continual improvement of operational performance;\n• Regular review of safety performance indicators by senior management;\n• Regular analysis of malfunctions or undesirable operational results;\n• Follow-up of corrective actions and their effectiveness in improving operational performance.\nAn SMS, as well as a Quality Management System (QMS) and Security Management System (SeMS), are integrated components of an operator's overall management system and would typically be subjected to protocols for continual improvement in accordance with the operator's policy.\nThe corporate safety policy may be documented in the OM or other controlled document. To enhance effectiveness, the policy is communicated and made visible throughout the organization through the dissemination of communiqués, posters, banners and other types of media in a form and language that can be easily understood. To ensure continuing relevance, the corporate policy is typically reviewed for possible update a minimum of every two years.\nConsistent with the structure and complexity of the operator's organization, the corporate safety policy may be issued as a stand-alone policy or combined with the safety reporting policy specified in ORG 1.2.2.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: A common understanding of values and priorities, creating and promoting awareness and buy-in by the employees and a demonstration of senior management commitment to safety, provision of appropriate resources, and the functioning of the SMS.\nSuitability Considerations: • Organizational and operational complexity. • Scope of the policy. • Means of disseminating the policy.\nC1 (Established): The Accountable Executive is familiar with the content of the safety policy.\nC2 (Established): The safety policy is visible/accessible throughout the organization and employees are aware of where the policy is located.\nC3 (Established): The safety policy is regularly promoted and communicated to personnel through various effective channels and/or methods.\nC4 (Established): The safety policy is adapted to the organization's size, complexity and operational environment.\nC5 (Mature): The safety policy is developed, reviewed, and improved by Accountable Executive and Senior Management.\nC6 (Mature): Senior Management are promoting their commitment to the safety policy through active and visible participation in the safety management activities.\nC7 (Mature): Operational personnel across the organisation are familiar with the safety policy and can describe their obligations in respect of the policy.\nC8 (Leading): Accountable Executive regularly, visibly endorses and promotes the safety policy.\nC9 (Leading): Senior Management's and Operational Managers' approach to managing safety demonstrates a commitment to constantly promoting a positive safety culture.\nC10 (Leading): Operational personnel are fully aware and embraces the policy as it forms part of the Operator's values/priorities.", zh: "运营人应制定公司安全政策，体现组织对安全的承诺，包括促进积极的安全文化。该政策应在整个组织内传达，并包括以下内容：\n(i) 关于为实施安全政策提供必要资源的声明；\n(ii) 对组织和管理系统持续改进的承诺；\n(iii) 对定期评审政策以确保其与组织持续相关的承诺。[SMS] [MA] (GM)\n\n审计员行动：\n▪ 识别/评估公司安全政策（重点：组织对安全的承诺/提供必要资源）\n▪ 访谈AE、SMS经理和/或指定管理代表\n▪ 检查公司沟通示例（重点：安全政策在整个组织内传达）\n▪ 协调验证所有运行领域安全政策的沟通情况\n▪ 其他行动（请说明）\n\n指导材料：\n质量管理体系（QMS）的定义请参阅IRM。\n要求运营人制定明确的安全政策是SMS框架中安全政策和目标组成部分的一个要素。\n运营人的政策反映了高级管理层确保持续衡量和评估以及实施改进管理系统和文化变革的承诺。改进的想法可能来自内部和外部来源。因此，组织应持续监控所有来源，并愿意根据需要进行变革，以保持管理系统更新并专注于改进运行质量、安全和安保绩效。\n安全政策通常还反映高级管理层的以下承诺：\n• 遵守适用法规和运营人标准；\n• 管理航空器运行的安全和安保风险；\n• 促进安全和安保意识；\n• 持续改进运行绩效；\n• 高级管理层定期评审安全绩效指标；\n• 定期分析故障或不良运行结果；\n• 跟踪纠正措施及其在改进运行绩效方面的有效性。\nSMS以及质量管理体系（QMS）和安保管理体系（SeMS）是运营人整体管理体系的组成部分，通常会根据运营人的政策接受持续改进的协议。\n公司安全政策可以记录在OM或其他受控文件中。为了提高有效性，政策通过传播公报、海报、横幅和其他类型的媒体，以易于理解的形式和语言在整个组织内传达并可见。为了确保持续相关性，公司政策通常至少每两年评审一次可能的更新。\n与运营人组织的结构和复杂性相一致，公司安全政策可以作为独立政策发布，也可以与ORG 1.2.2中规定的安全报告政策合并。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：对价值观和优先事项的共同理解，创造和促进员工的意识和认同，展示高级管理层对安全的承诺、提供适当资源以及SMS的运作。\n充分性考虑：• 组织和运行复杂性。• 政策范围。• 传播政策的手段。\nC1（建立）：责任人熟悉安全政策的内容。\nC2（建立）：安全政策在整个组织中可见/可访问，员工知道政策的位置。\nC3（建立）：安全政策通过各种有效渠道和/或方法定期向人员宣传和沟通。\nC4（建立）：安全政策适应组织的规模、复杂性和运行环境。\nC5（成熟）：安全政策由责任人和高级管理层制定、审查和改进。\nC6（成熟）：高级管理层通过积极和可见地参与安全管理活动来宣传他们对安全政策的承诺。\nC7（成熟）：整个组织的运行人员熟悉安全政策并能够描述他们在政策方面的义务。\nC8（领先）：责任人定期、显著地认可和宣传安全政策。\nC9（领先）：高级管理层和运行经理管理安全的方法表明他们致力于不断促进积极的安全文化。\nC10（领先）：运行人员完全了解并接受该政策，因为它是运营人价值观/优先事项的一部分。" },
            { subtitle: "ORG 1.2.2 安全报告政策", eng: "The Operator shall have a corporate safety reporting policy that encourages personnel to report hazards to aircraft operations and, in addition, defines the Operator's policy regarding disciplinary action, to include:\n(i) Types of operational behaviors that are unacceptable;\n(ii) Conditions under which disciplinary action would not apply. [SMS] [MA] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed corporate safety reporting policy (focus: personnel urged to report operational hazards; definition of disciplinary policy/potential disciplinary actions).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Coordinated to verify implementation of safety reporting in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Just Culture.\nThe requirement for an operator to have a safety reporting policy is an element of the Safety Policy and Objectives component of the SMS framework.\nSafety reporting is a key aspect of SMS hazard identification in the management of risk.\nSuch a policy is typically documented in operations manuals or other controlled documents.\nConsistent with the structure and complexity of the operator's organization, the safety reporting policy may be issued as a stand-alone policy or combined with the safety policy that is specified in ORG 1.2.1.\nA safety reporting policy encourages and perhaps even provides incentive for individuals to report hazards and operational deficiencies to management. It also assures personnel that their candid input is highly desired and vital to safe and secure operations.\nIt is important that the operator provides appropriate protections to encourage personnel to report what they see or experience. For example, enforcement action may be waived for reports of errors or, under certain circumstances, even rule breaking. It should be clearly stated that reported information will be used solely to support the enhancement of safety. The intent is to promote an effective reporting culture and proactive identification of potential safety deficiencies.\nAn effective reporting culture exists when personnel have confidence that their reports are used to improve operational safety by learning from mistakes and system flaws, and thus improve the safety of operations. To that end, an operator's safety reporting policy would typically incorporate the principles of Just Culture.\nThe safety reporting policy is typically reviewed periodically to ensure continuing relevance to the organization.\nRefer to ORG 3.1.2 and 3.1.3, both of which address operational safety reporting.\n\nAssessment Tool\nDesired Outcome: The operator has an effective and healthy hazard reporting process through a transparent policy on acceptable and unacceptable behaviours/actions.\nSuitability Considerations: • Organizational and operational complexity. • Scope of the policy. • Means of disseminating the policy.\nC1 (Established): The safety reporting policy incorporates the principles of just culture. It provides appropriate protections to ensure personnel report what they identify or experience, and reports are appropriately de-identified.\nC2 (Established): Senior Management is familiar with the contents of the safety reporting policy and endorses it.\nC3 (Established): The safety reporting policy is regularly communicated to personnel through various effective communication channels and/or methods.\nC4 (Established): The safety reporting policy is adapted for the organization's size, complexity and operational environment.\nC5 (Mature): The safety reporting policy is regularly reviewed to ensure relevance and improvement.\nC6 (Mature): All personnel are trained at regular intervals on the safety reporting policy and just culture.\nC7 (Mature): Operational personnel trust the organization's just culture and its fair and consistent application.\nC8 (Mature): Key safety and operational personnel, and where appropriate, staff representative bodies (e.g. employee forums, trade unions) are consulted in the development of acceptable and unacceptable behaviours.\nC9 (Mature): Within the organisation, the line between acceptable and unacceptable behaviours are clearly established/defined and known by the operational personnel.\nC10 (Leading): Senior management are promoting and showing their commitment to the corporate safety reporting policy through active and visible participation and endorsement in the safety management system.\nC11 (Leading): The safety reporting policy provides for and achieves safety reporting by at least a wide range of outsourced service providers.\nC12 (Leading): Accountable Executive regularly and visibly promotes the safety reporting policy.\nC13 (Leading): Operational personnel are fully aware/embraces the safety reporting policy and actively reports safety hazards, deficiencies and concerns.", zh: "运营人应制定公司安全报告政策，鼓励人员报告航空器运行的危险，并定义运营人关于纪律处分的政策，包括：\n(i) 不可接受的运行行为类型；\n(ii) 不适用纪律处分的情形。[SMS] [MA] (GM)\n\n审计员行动：\n▪ 识别/评估公司安全报告政策（重点：敦促人员报告运行危险；定义纪律政策/可能的纪律处分）\n▪ 访谈AE和/或指定管理代表\n▪ 协调验证所有运行领域安全报告的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n公正文化的定义请参阅IRM。\n要求运营人制定安全报告政策是SMS框架中安全政策和目标组成部分的一个要素。\n安全报告是风险管理中SMS危险识别的关键方面。\n此类政策通常记录在运行手册或其他受控文件中。\n与运营人组织的结构和复杂性相一致，安全报告政策可以作为独立政策发布，也可以与ORG 1.2.1中规定的安全政策合并。\n安全报告政策鼓励甚至可能激励个人向管理层报告危险和运行缺陷。它还向人员保证，他们的坦诚意见是非常需要且对安全可靠的运行至关重要。\n重要的是，运营人提供适当的保护以鼓励人员报告他们所看到或经历的事情。例如，对于错误的报告，甚至在某些情况下对于违反规则的行为，可以免除执法行动。应明确声明，报告的信息将仅用于支持安全改进。其目的是促进有效的报告文化和对潜在安全缺陷的主动识别。\n当人员确信他们的报告被用于通过从错误和系统缺陷中学习来改进运行安全，从而提高运行安全性时，就存在有效的报告文化。为此，运营人的安全报告政策通常会纳入公正文化的原则。\n安全报告政策通常定期评审以确保与组织的持续相关性。\n另见ORG 3.1.2和3.1.3，两者都涉及运行安全报告。\n\n评估工具\n预期结果：运营人通过对可接受和不可接受行为/行动的透明政策，拥有有效和健康的危险报告流程。\n充分性考虑：• 组织和运行复杂性。• 政策范围。• 传播政策的手段。\nC1（建立）：安全报告政策纳入了公正文化的原则。它提供适当的保护以确保人员报告他们识别或经历的内容，并且报告被适当地去标识化。\nC2（建立）：高级管理层熟悉安全报告政策的内容并认可它。\nC3（建立）：安全报告政策通过各种有效沟通渠道和/或方法定期向人员传达。\nC4（建立）：安全报告政策适应组织的规模、复杂性和运行环境。\nC5（成熟）：安全报告政策被定期审查以确保相关性和改进。\nC6（成熟）：所有人员定期接受关于安全报告政策和公正文化的培训。\nC7（成熟）：运行人员信任组织的公正文化及其公平一致的应用。\nC8（成熟）：关键安全和运行人员，以及适当时员工代表机构（例如员工论坛、工会），在制定可接受和不可接受行为时被征求意见。\nC9（成熟）：在组织内，可接受和不可接受行为之间的界限被明确建立/定义并为运行人员所知。\nC10（领先）：高级管理层通过积极和可见地参与和认可安全管理体系来宣传和展示他们对公司安全报告政策的承诺。\nC11（领先）：安全报告政策规定并实现了至少广泛的外包服务提供商的安全报告。\nC12（领先）：责任人定期、显著地宣传安全报告政策。\nC13（领先）：运行人员完全了解/接受安全报告政策，并积极报告安全危险、缺陷和关切。" },
            { subtitle: "ORG 1.2.3 合规政策", eng: "The Operator shall have a policy that informs operational personnel throughout the organization of their responsibility to comply with the applicable laws, regulations and procedures in all locations where operations are conducted.\n\nAuditor Actions:\n▪ Identified/Assessed corporate compliance policy (focus: requirement for organizational compliance with applicable laws/regulations/procedures by operational personnel).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Coordinated to verify implementation of compliance policy in all operational areas.\n▪ Other Actions (Specify)", zh: "运营人应制定一项政策，告知整个组织的运行人员在所有运行地点遵守适用法律、法规和程序的责任。\n\n审计员行动：\n▪ 识别/评估公司合规政策（重点：要求运行人员遵守适用法律/法规/程序）\n▪ 访谈AE和/或指定管理代表\n▪ 协调验证所有运行领域合规政策的实施情况\n▪ 其他行动（请说明）" }
        ]
    },
         roles_resp: {
        title: "1.3 角色与职责 - Roles and Responsibilities",
        sections: [
            { subtitle: "ORG 1.3.1 安全问责、权限与职责", eng: "The Operator shall ensure the management system defines the safety accountability, authorities and responsibilities of management and non-management personnel throughout the organization, and specifies:\n(i) The levels of management with the authority to make decisions regarding risk tolerability with respect to the safety and/or security of aircraft operations;\n(ii) Responsibilities for ensuring operations are conducted in accordance with applicable regulations and standards of the Operator;\n(iii) Lines of safety accountability throughout the organization, including direct accountability for safety and/or security on the part of senior management. [SMS] [MA] (GM) ►\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed defined safety accountability/authorities/responsibilities for management/non-management personnel (focus: definitions apply to personnel throughout the organization).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Coordinated to verify defined accountability/authorities/responsibilities in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of IOSA Audit Handbook (IAH) and Risk Tolerability.\nThe definition of authorities and responsibilities of management and non-management personnel is an element of the Safety Policy and Objectives component of the SMS framework.\nIn the context of the management system, the following typically apply:\n• Accountability is the obligation to accept ultimate responsibility and be answerable for decisions and policies, and for the performance of applicable functions, duties, tasks or actions. Accountability may not be delegated.\n• Authority is the delegated power or right to command or direct activities, and to make decisions.\n• Responsibility is the obligation to execute or perform assigned functions, duties, tasks and/or actions. Responsibility may be accompanied by an appropriate level of delegated authority.\nIn the context of an SMS, the assignment of responsibility to individual personnel means such personnel are ultimately accountable for safety performance, whether at the overall SMS level (accountable executive) or at specific product and/or process levels (other applicable members of management).\nAn effective management system ensures that responsibilities, and thus accountability, for safety and security are allocated to relevant management and non-management personnel that perform safety- or security-related functions, or that have a defined role in either the SMS or the SeMS.\nResponsibilities and accountability are typically defined in the functional job description for such personnel and are designed to flow from corporate senior management into all operational areas of the organization.\nResponsibilities and accountability are normally described and communicated in a manner that ensures a clear understanding throughout the organization. Organization charts, or organograms, are typically used to depict the functional reporting system of an organization, and thus are an acceptable means for defining the flow (or \"lines\" as depicted on an organogram) of responsibilities and accountability within the management system.\nManagement positions critical to operational safety or security may require enhanced job descriptions or terms of reference that reflect specialized requirements inherent in certain key positions. Such specialized requirements would include any delegation of authority exercised by personnel on behalf of an authority (e.g. designated or authorized flight examiner).\nCompliance with regulatory requirements, as well as internal policies and procedures, is an essential element of a safe and secure operational environment. The responsibility for ensuring compliance with both regulatory and internal requirements is specified and assigned within the management system. Job descriptions, terms of reference and operating manuals are examples of appropriate locations for documenting management system responsibilities.\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: Everyone within the organization is aware of, and understands the accountabilities, authorities and responsibilities assigned within the management system, and is aware of the consequences of decisions made.\nSuitability Considerations: • Granularity of roles and responsibilities based on the size and complexity of the organization. • Method to communicate and update the responsibilities.\nC1 (Established): Senior management is fully aware of the SMS accountabilities, authorities and responsibilities.\nC2 (Established): Senior management is aware of the organisation's safety performance and its most significant hazards/risks.\nC3 (Established): Employees have access to and are familiar with their own safety accountabilities, authorities and responsibilities.\nC4 (Established): Safety accountabilities, authorities and responsibilities are clear, concise and easy to understand by operational personnel.\nC5 (Mature): Safety accountabilities, authorities, and responsibilities are defined in a consistent and integrated manner to flow from senior management into all operational personnel.\nC6 (Mature): Safety accountabilities, authorities, and responsibilities are reviewed periodically and after any significant organisational/operational change.\nC7 (Mature): The Accountable Executive is fully aware of his/her own and the Senior Management's safety accountability, authority and responsibilities.\nC8 (Mature): The safety manager is subjected to continuous training and qualification related to safety management system such as additional training, conferences, workshops.\nC9 (Leading): The Accountable Executive is committed to the continuous evolution of the safety culture within the organization through the IATA Safety Leadership Charter.\nC10 (Leading): Any management and non-management personnel that performs safety related functions has one or more individual goal(s)/objective(s) related to its safety related accountabilities, authorities or responsibilities.\nC11 (Leading): The Accountable Executive actively engages in the SMS and its continuous improvement.\nC12 (Leading): Operational Managers have safety related objectives in alignment with corporate safety objectives and/or associated safety performance indicators.", zh: "运营人应确保管理系统定义整个组织内管理和非管理人员的安全问责制、权限和职责，并规定：\n(i) 有权就航空器运行安全和/或安保风险可接受性做出决策的管理层级；\n(ii) 确保按照适用法规和运营人标准开展运行的责任；\n(iii) 整个组织内的安全问责线，包括高级管理层对安全和/或安保的直接问责。[SMS] [MA] (GM) ►\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估为管理/非管理人员定义的安全问责/权限/职责（重点：定义适用于整个组织的人员）\n▪ 访谈AE和/或指定管理代表\n▪ 协调验证所有运行领域中定义的问责/权限/职责\n▪ 其他行动（请说明）\n\n指导材料：\nIOSA审计手册（IAH）和风险可接受性的定义请参阅IRM。\n定义管理和非管理人员的权限和职责是SMS框架中安全政策和目标组成部分的一个要素。\n在管理系统的背景下，通常适用以下内容：\n• 问责制是接受最终责任并对其决策和政策，以及适用职能、职责、任务或行动的绩效负责的义务。问责制不可委派。\n• 权限是指挥或指导活动以及做出决策的被委派的权力或权利。\n• 责任是执行或履行分配职能、职责、任务和/或行动的义务。责任可能伴随着适当级别的委派权限。\n在SMS的背景下，将责任分配给个别人员意味着这些人员最终对安全绩效负责，无论是在整体SMS层面（责任人）还是在特定产品和/或流程层面（其他适用的管理层成员）。\n有效的管理系统确保将安全和安保的责任，从而问责制，分配给执行安全或安保相关职能或在SMS或SeMS中具有明确角色的相关管理和非管理人员。\n责任和问责制通常在此类人员的职能职位描述中定义，并设计为从公司高级管理层流向组织的所有运行领域。\n责任和问责制通常以确保整个组织清晰理解的方式进行描述和沟通。组织架构图通常用于描述组织的职能报告系统，因此是定义管理系统中责任和问责制流向（或组织架构图上描述的\"线\"）的可接受方式。\n对运行安全或安保至关重要的管理职位可能需要增强的职位描述或职责范围，以反映某些关键职位固有的专业要求。此类专业要求将包括人员代表当局行使的任何权限委派（例如指定或授权的飞行检查员）。\n遵守法规要求以及内部政策和程序是安全可靠运行环境的基本要素。确保遵守法规和内部要求的责任在管理系统内明确和分配。职位描述、职责范围和运行手册是记录管理系统职责的适当位置的示例。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：组织内的每个人都了解并理解管理系统中分配的问责制、权限和职责，并了解所做决策的后果。\n充分性考虑：• 基于组织规模和复杂性的角色和职责的粒度。• 沟通和更新职责的方法。\nC1（建立）：高级管理层完全了解SMS的问责制、权限和职责。\nC2（建立）：高级管理层了解组织的安全绩效及其最重要的危险/风险。\nC3（建立）：员工可以访问并熟悉自己的安全问责制、权限和职责。\nC4（建立）：安全问责制、权限和职责清晰、简洁且易于运行人员理解。\nC5（成熟）：安全问责制、权限和职责以一致和综合的方式定义，从高级管理层流向所有运行人员。\nC6（成熟）：安全问责制、权限和职责定期审查，并在任何重大组织/运行变更后进行审查。\nC7（成熟）：责任人完全了解自己及高级管理层的安全问责制、权限和职责。\nC8（成熟）：安全经理接受与安全管理体系相关的持续培训和资格认证，例如额外培训、会议、研讨会。\nC9（领先）：责任人通过IATA安全领导力宪章致力于组织内安全文化的持续发展。\nC10（领先）：任何执行安全相关职能的管理和非管理人员都有与其安全相关问责制、权限或职责相关的一个或多个个人目标/目的。\nC11（领先）：责任人积极参与SMS及其持续改进。\nC12（领先）：运行经理拥有与公司安全目标和/或相关安全绩效指标相一致的安全相关目标。" },
            { subtitle: "ORG 1.3.2 职责委派", eng: "The Operator shall have a process or procedure for the delegation of duties within the management system that ensures managerial continuity is maintained when operational managers including, if applicable, post holders are unable to carry out work duties. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed processes for management system delegation of duties (focus: processes maintain managerial continuity during periods when corporate/operational managers are unable to perform work duties).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Coordinated to verify processes for management system delegation of duties in all operational areas.\n▪ Examined example(s) of delegation of duties when managers have been unable to perform work duties.\n▪ Other Actions (Specify)\n\nGuidance:\nThe intent of this provision is for an operator to have a process or procedure that ensures a specific person (or perhaps more than one person) is identified to assume the duties of any operational manager that is or is expected to be, unable to accomplish assigned work duties. An operator may have nominated deputies in place or a process for ensuring the appointment of a temporary replacement.\nFor the purpose of this provision, the use of telecommuting technology and/or being on call and continually contactable are acceptable means for operational managers to remain available and capable of carrying out assigned work duties.\nA notification of such delegation of duties may be communicated throughout the management system using email or other suitable communication medium.", zh: "运营人应制定管理系统内职责委派的流程或程序，确保当运行经理（包括岗位负责人，如适用）无法履行工作职责时，管理连续性得以维持。(GM) ►\n\n审计员行动：\n▪ 识别/评估管理系统职责委派流程（重点：流程在公司/运行经理无法履行工作职责期间维持管理连续性）\n▪ 访谈AE和/或指定管理代表\n▪ 协调验证所有运行领域管理系统职责委派流程\n▪ 检查经理无法履行工作职责时的职责委派示例\n▪ 其他行动（请说明）\n\n指导材料：\n本条款的意图是让运营人有一个流程或程序，确保指定一个特定的人（或可能不止一个人）来承担任何正在或预期无法完成分配工作职责的运行经理的职责。运营人可以指定副职或建立确保临时替换人任命的流程。\n就本条款而言，使用远程办公技术和/或待命并保持可联系状态是运行经理保持可用并能够执行分配工作职责的可接受方式。\n此类职责委派的通知可以通过电子邮件或其他适当的沟通媒介在整个管理系统中传达。" },
            { subtitle: "ORG 1.3.3 外部联络", eng: "The Operator shall ensure a delegation of authority and assignment of responsibility within the management system for liaison with regulatory authorities, original equipment manufacturers and other operationally relevant external entities. (GM) ►\n\nAuditor Actions:\n▪ Identified corporate management individuals with authority for liaison with regulators/other external entities.\n▪ Interviewed AE and/or designated management representative(s).\n▪ Interviewed selected manager(s) with authority for liaison with regulators/other external entities.\n▪ Coordinated to identify managers with authority for liaison with external entities in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nTo ensure the communication and coordination with external entities is consistent and appropriate, liaison with operationally relevant external entities is normally controlled through the delegation of authority and assignment of responsibility to specifically named management personnel. Such authorities and responsibilities would normally be included in the job descriptions of the applicable managers.", zh: "运营人应确保在管理系统内授权和分配与监管当局、原始设备制造商及其他运行相关外部实体联络的职责。(GM) ►\n\n审计员行动：\n▪ 识别有权与监管机构/其他外部实体联络的公司管理人员\n▪ 访谈AE和/或指定管理代表\n▪ 访谈选定的有权与监管机构/其他外部实体联络的经理\n▪ 协调识别所有运行领域中有权与外部实体联络的经理\n▪ 其他行动（请说明）\n\n指导材料：\n为了确保与外部实体的沟通和协调一致且适当，与运行相关外部实体的联络通常通过将权限和责任委派给具体指定的管理人员来进行控制。这些权限和责任通常包含在适用经理的职位描述中。" }
        ]
    },
    
        safety_performance: {
        title: "1.4 安全绩效 - Safety Performance",
        sections: [
            { subtitle: "ORG 1.4.1 安全目标", eng: "The Operator shall have a process to define safety objectives. Such safety objectives shall:\n(i) Reflect the Operator's commitment to maintain or continuously improve the overall effectiveness of the SMS;\n(ii) Be communicated throughout the organization;\n(iii) Be periodically reviewed to ensure they remain relevant and appropriate to the Operator. [SMS] [MA] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed organizational program for setting safety objectives.\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected safety objectives currently valid.\n▪ Examined selected records/documents that identify tracking of safety objectives.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Safety Assurance and Safety Objective.\nDefining safety objectives is an element of the Safety Policy and Objectives component of the SMS framework.\nSafety objectives provide direction to the operator's safety management activities and would therefore be consistent with the safety policy that sets out the organization's high-level safety commitment.\nA safety objective is a high-level statement that typically expresses a desired safety outcome that is to be achieved over a defined period of time (e.g. one year).\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: The organization's safety performance and overall achievement of the safety policy can be objectively measured to enable improvements where needed.\nSuitability Considerations: • Number of objectives based on size and complexity of the organization. • Definition of objectives based on past and current safety performance. • Visibility of objectives within the organization.\nC1 (Established): Each safety objective is assigned to one or more individual and the relevant objective is aligned with job descriptions and/or objectives of the responsible personnel.\nC2 (Established): Employees are aware of and understand the safety objectives that apply to them.\nC3 (Established): Safety objectives are related to and encompass all operational areas.\nC4 (Established): Safety objectives include a mix of both qualitative and quantitative elements.\nC5 (Mature): The Accountable Executive is familiar with the safety objectives and their achievement.\nC6 (Mature): The Operator has detailed action plans for the achievement of the safety objectives.\nC7 (Mature): The safety objectives are in alignment with organization's safety priorities and address its most significant safety hazards/risks.\nC8 (Mature): The safety objectives are developed, reviewed, and improved by the Senior Management to include direct involvement of the Accountable Executive.\nC9 (Mature): Achievement of the safety objectives is monitored by senior management and effective actions are taken to ensure they are being met.\nC10 (Leading): Safety objectives are aligned with the State Safety Program (SSP) and/or, where applicable, State Plan for Aviation Safety (SPAS).\nC11 (Leading): Safety objectives are clearly linked to and address all relevant aspects of the Safety Policy.\nC12 (Leading): Senior Management and the Accountable Executive regularly and visibly promote the safety objectives.\nC13 (Leading): Safety objectives lead towards a continuous improvement in the safety performance.\nC14 (Leading): Employees are aware how they can contribute towards the achievement of the Safety Objectives.\nC15 (Leading): Each safety objective's achievement is effectively monitored by one or more Safety performance indicators (SPIs).", zh: "运营人应制定定义安全目标的流程。此类安全目标应：\n(i) 反映运营人维持或持续改进SMS整体有效性的承诺；\n(ii) 在整个组织内传达；\n(iii) 定期评审以确保其与运营人保持相关和适当。[SMS] [MA] (GM)\n\n审计员行动：\n▪ 识别/评估组织制定安全目标的方案\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查选定的当前有效的安全目标\n▪ 检查选定的识别安全目标跟踪的记录/文件\n▪ 其他行动（请说明）\n\n指导材料：\n安全保证和安全目标的定义请参阅IRM。\n定义安全目标是SMS框架中安全政策和目标组成部分的一个要素。\n安全目标为运营人的安全管理活动提供方向，因此应与规定组织高层安全承诺的安全政策保持一致。\n安全目标是一个高层次声明，通常表达了在特定时间段内（例如一年）要达到的期望安全结果。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：组织的安全绩效和安全政策的总体实现情况可以被客观衡量，以便在需要时进行改进。\n充分性考虑：• 基于组织规模和复杂性的目标数量。• 基于过去和当前安全绩效的目标定义。• 目标在组织内的可见性。\nC1（建立）：每个安全目标分配给一个或多个个人，相关目标与负责人员的职位描述和/或目标相一致。\nC2（建立）：员工了解并理解适用于他们的安全目标。\nC3（建立）：安全目标涉及并涵盖所有运行领域。\nC4（建立）：安全目标包括定性和定量要素的组合。\nC5（成熟）：责任人熟悉安全目标及其实现情况。\nC6（成熟）：运营人有实现安全目标的详细行动计划。\nC7（成熟）：安全目标与组织的安全优先事项相一致，并解决其最重要的安全危险/风险。\nC8（成熟）：安全目标由高级管理层制定、审查和改进，包括责任人的直接参与。\nC9（成熟）：高级管理层监控安全目标的实现情况，并采取有效措施确保目标得以实现。\nC10（领先）：安全目标与国家安全计划（SSP）和/或（如适用）国家安全航空计划（SPAS）相一致。\nC11（领先）：安全目标与安全政策的所有相关方面明确联系并加以解决。\nC12（领先）：高级管理层和责任人定期、显著地宣传安全目标。\nC13（领先）：安全目标引领安全绩效的持续改进。\nC14（领先）：员工知道他们如何为实现安全目标做出贡献。\nC15（领先）：每个安全目标的实现情况由一个或多个安全绩效指标（SPI）有效监控。" },
            { subtitle: "ORG 1.4.2 安全绩效指标", eng: "The Operator shall have processes for setting safety performance indicators (SPIs) and, as applicable, safety performance targets (SPTs) as means to monitor its safety performance, the achievement of its safety objectives and to validate the effectiveness of safety risk controls. [SMS] [MA] (GM) ►\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed organizational program for setting SPIs and SPTs (focus: program defines/requires development/application of SPIs; measures used to track/monitor operational safety performance/validate safety risk controls).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected SPIs and SPTs (focus: SPIs/SPTs are aligned with safety objectives and are being used to monitor operational performance).\n▪ Examined selected records/documents that identify tracking of SPIs and SPTs (focus: tracking used to assess/monitor operational safety performance, assess/validate risk control effectiveness).\n▪ Coordinated to verify implementation of SPIs and SPTs in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Safety Performance Indicator (SPI) and Safety Performance Target (SPT).\nSetting SPIs in support of the operator's safety objectives is an element of the Safety Assurance component of the SMS framework.\nSPIs and SPTs are used by an operator to track and compare its operational performance against the achievement of its safety objectives and to focus attention on the performance of the organization in managing operational risks and maintaining compliance with relevant regulatory requirements.\nSPTs define short-term and medium-term safety performance management desired achievements. They act as 'milestones' that provide confidence that the organization is on track to achieving its safety objectives and provide a measurable way of verifying the effectiveness of safety performance management activities. The setting of SPTs is normally accomplished after considering what is realistically achievable and, where historical trend data are available, the recent performance of the particular SPI.\nIt is not always necessary or appropriate to set or define SPTs as there could be some SPIs that are better monitored for trends rather than against a targeted number. Safety reporting is an example of when having a target could either discourage people not to report (if the target is not to exceed a number) or to report trivial matters to meet a target (if the target is to reach a certain number).\nIn addressing operational performance, meaningful indicators might focus on lower level (i.e. lower consequence) occurrences or conditions that are considered by the operator to be precursors to more serious events. SPIs may be specific to a certain area of operations or may be broad and apply to the entire system.\nIn addressing compliance, meaningful indicators, as a minimum, would focus on compliance with significant regulatory requirements (as determined by the operator) in all operational areas.\nSPIs may be set in almost any operations or maintenance area and are usually expressed as a reduction in the rate or number of specifically identified occurrences or conditions.\nSome possible examples of operational occurrences or conditions, listed by operational discipline, that could be monitored using SPIs include:\n• Flight operations (e.g. takeoff and landing tail strikes, unsatisfactory line or training evaluations, unstabilized approaches, runway incursions/excursions);\n• Operational control (e.g. flight diversions due to fuel);\n• Engineering and maintenance (in-flight engine shutdowns, aircraft component/equipment failures, diversions due to maintenance errors, damage caused by maintenance);\n• Cabin operations (inadvertent slide deployments);\n• Ground handling (aircraft damages due to vehicles or equipment);\n• Cargo operations (dangerous goods spills);\n• Operational security (unauthorized interference or access events).\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: The organization's safety performance and overall achievement of the safety policy can be objectively measured to enable improvements where needed.\nSuitability Considerations: • Number of performance indicators based on size and complexity of the organization. • Visibility of the SPIs and SPTs within the organization. • Scope of SPIs, means to measure them and to collect.\nC1 (Established): The defined SPIs are appropriate to the organization's activities, safety priorities, safety hazards/risks, and safety risk controls.\nC2 (Established): Where the SPIs indicate that a safety risk control is ineffective, appropriate action is taken.\nC3 (Established): SPIs are defined as per the following criteria: reliable data, specific, measurable, and relevant.\nC4 (Established): SPIs are reviewed and regularly updated to ensure they remain relevant.\nC5 (Mature): Safety triggers/alert levels are established to initiate an evaluation, decision, adjustment or remedial action related to the SPI performance.\nC6 (Mature): The Operator is regularly and effectively monitoring identified risks and the effectiveness of risk controls & mitigations.\nC7 (Mature): During development of SPIs, the Operator considers related information that the Authority and/or Industry have published. (e.g. SPIs are published within a State Safety Plan or State Safety Programme).\nC8 (Mature): Processes related to the setting SPIs are periodically reviewed for relevance and necessary actions are taken.\nC9 (Mature): If SPIs are deviating from the safety triggers/alert levels, effective remedial actions are implemented to correct adverse trends.\nC10 (Leading): SPIs are used to monitor the safety performance related to significant/major external interfaces such as service providers, ATCs and airport operator and/or authorities.\nC11 (Leading): The Operator participates in industry SPI sharing/benchmarking initiatives.\nC12 (Leading): Senior management is directly involved in the processes for setting and monitoring SPIs.", zh: "运营人应制定设定安全绩效指标（SPI）和（如适用）安全绩效目标（SPT）的流程，作为监控其安全绩效、实现安全目标以及验证安全风险控制有效性的手段。[SMS] [MA] (GM) ►\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估组织设定SPI和SPT的方案（重点：方案定义/要求制定/应用SPI；用于跟踪/监控运行安全绩效/验证安全风险控制的措施）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查选定的SPI和SPT（重点：SPI/SPT与安全目标一致并被用于监控运行绩效）\n▪ 检查选定的识别SPI和SPT跟踪的记录/文件（重点：跟踪用于评估/监控运行安全绩效、评估/验证风险控制有效性）\n▪ 协调验证所有运行领域SPI和SPT的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n安全绩效指标（SPI）和安全绩效目标（SPT）的定义请参阅IRM。\n设定支持运营人安全目标的SPI是SMS框架中安全保证组成部分的一个要素。\n运营人使用SPI和SPT来跟踪其运行绩效并将其与安全目标的实现情况进行比较，并关注组织在管理运行风险和保持符合相关法规要求方面的绩效。\nSPT定义了短期和中期安全绩效管理的期望成就。它们作为\"里程碑\"，提供组织在实现其安全目标方面进展顺利的信心，并提供一种可衡量的方式来验证安全绩效管理活动的有效性。SPT的设定通常是在考虑了实际可实现的目标后完成的，并且在有历史趋势数据的情况下，考虑特定SPI的近期绩效。\n设定或定义SPT并不总是必要或适当的，因为有些SPI更适合监控趋势而不是针对目标数量。安全报告就是一个例子，设定目标可能会阻碍人们报告（如果目标是不要超过某个数量），或者为了达到目标而报告琐碎的事情（如果目标是达到某个数量）。\n在运行绩效方面，有意义的指标可能侧重于较低级别（即较低后果）的事件或条件，这些事件或条件被运营人视为更严重事件的前兆。SPI可能特定于某个运行领域，也可能是广泛的并适用于整个系统。\n在合规方面，有意义的指标至少应侧重于所有运行领域中对重要法规要求（由运营人确定）的符合性。\nSPI几乎可以在任何运行或维修领域设定，通常表示为特定识别事件或条件的发生率或数量的减少。\n按运行学科列出的可使用SPI监控的运行事件或条件的一些可能示例包括：\n• 飞行运行（例如起飞和着陆擦尾、不满意的航线或训练评估、不稳定的进近、跑道入侵/偏出）；\n• 运行控制（例如因燃油导致的航班备降）；\n• 工程和维修（空中发动机停车、飞机部件/设备故障、因维修错误导致的备降、维修造成的损坏）；\n• 客舱运行（滑梯意外放出）；\n• 地面操作（车辆或设备导致的飞机损坏）；\n• 货运运行（危险品泄漏）；\n• 运行安保（未经授权的干扰或进入事件）。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：组织的安全绩效和安全政策的总体实现情况可以被客观衡量，以便在需要时进行改进。\n充分性考虑：• 基于组织规模和复杂性的绩效指标数量。• SPI和SPT在组织内的可见性。• SPI的范围、衡量和收集的手段。\nC1（建立）：定义的SPI适合组织的活动、安全优先事项、安全危险/风险和安全风险控制。\nC2（建立）：当SPI表明安全风险控制无效时，采取适当行动。\nC3（建立）：SPI根据以下标准定义：可靠数据、具体、可衡量、相关。\nC4（建立）：SPI被审查并定期更新以保持相关性。\nC5（成熟）：建立安全触发/警报级别，以启动与SPI绩效相关的评估、决策、调整或补救行动。\nC6（成熟）：运营人定期有效监控已识别的风险以及风险控制和缓解措施的有效性。\nC7（成熟）：在制定SPI时，运营人考虑当局和/或行业发布的相关信息（例如SPI在国家安全计划或国家安全方案中发布）。\nC8（成熟）：与制定SPI相关的流程定期审查相关性，并采取必要行动。\nC9（成熟）：如果SPI偏离安全触发/警报级别，则实施有效的补救行动以纠正不利趋势。\nC10（领先）：SPI用于监控与重大/主要外部接口（如服务提供商、ATC、机场运营商和/或当局）相关的安全绩效。\nC11（领先）：运营人参与行业SPI共享/基准测试计划。\nC12（领先）：高级管理层直接参与制定和监控SPI的流程。" }
        ]
    },
       resource_mgmt: {
        title: "1.5 资源管理 - Resource Management",
        sections: [
            { subtitle: "ORG 1.5.1 规划流程", eng: "The Operator shall ensure the management system includes planning processes for operations which:\n(i) Define desired operational safety and security objectives;\n(ii) Address operational resource allocation requirements;\n(iii) Take into account requirements originating from applicable external sources, including regulatory authorities and original equipment manufacturers. (GM)\n\nNote: The definition of desired safety objectives as specified in item (i) shall take into account and be consistent with the Operator's safety policy.\n\nAuditor Actions:\n▪ Identified/Assessed planning processes for operations (focus: planning includes defining operational safety/security goals/objectives, allocates necessary resources).\n▪ Interviewed responsible management representative(s).\n▪ Examined selected planning records/documents (focus: planning addresses internal/external operational safety/security objectives/requirements).\n▪ Coordinated to verify planning processes take into account all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nManagement system planning processes are necessary to ensure sufficient resources are in place to meet internal operational safety and security requirements, as well as to meet requirements from external sources, such as regulatory authorities and equipment manufacturers. Resource requirements would typically be determined through risk assessment, management review or other management processes.\nPlanning processes typically result in the generation of goals, objectives or other types of performance measures that would represent the operational safety and security outcomes an operator plans for and desires to achieve.\nDefined safety objectives reflect the service provider's commitment to maintain or continuously improve the overall effectiveness of its SMS, and typically form the basis for the setting of SPIs (see ORG 1.4.1 and 1.4.2).\nPlanning processes may be part of, or associated with, the budgetary process, which typically take place prior to the start of a calendar or fiscal year and involve decisions that result in a plan for capital and operating expenditures to support operations.\nExpanded guidance regarding the setting of safety objectives may be found in the ICAO SMM, Document 9859.", zh: "运营人应确保管理系统包括运行规划流程，该流程应：\n(i) 定义期望的运行安全和安保目标；\n(ii) 处理运行资源分配要求；\n(iii) 考虑来自适用外部来源（包括监管当局和原始设备制造商）的要求。(GM)\n\n注：第(i)项中规定的期望安全目标的定义应考虑并与运营人的安全政策保持一致。\n\n审计员行动：\n▪ 识别/评估运行规划流程（重点：规划包括定义运行安全/安保目标/目的，分配必要资源）\n▪ 访谈负责的管理代表\n▪ 检查选定的规划记录/文件（重点：规划处理内部/外部运行安全/安保目标/要求）\n▪ 协调验证规划流程考虑了所有运行领域\n▪ 其他行动（请说明）\n\n指导材料：\n管理系统规划流程对于确保有足够的资源来满足内部运行安全和安保要求以及来自外部来源（如监管当局和设备制造商）的要求是必要的。资源要求通常通过风险评估、管理评审或其他管理流程确定。\n规划流程通常会产生目标、目的或其他类型的绩效衡量标准，代表运营人计划并期望实现的运行安全和安保结果。\n定义的安全目标反映了服务提供者维持或持续改进其SMS整体有效性的承诺，并且通常构成制定SPI的基础（见ORG 1.4.1和1.4.2）。\n规划流程可能是预算流程的一部分或与之相关，预算流程通常在日历或财政年度开始之前进行，涉及做出支持运行的资本和运营支出计划决策。\n关于制定安全目标的扩展指导可参见ICAO SMM，文件9859。" },
            { subtitle: "ORG 1.5.2 设施与设备", eng: "The Operator shall ensure existence of the facilities, workspace, equipment and supporting services, as well as work environment, necessary to satisfy operational safety and security requirements. (GM) ►\n\nNote: Conformity with this ORG provision and repeats in other ISM sections does not require specifications to be documented by the Operator.\n\nAuditor Actions:\n▪ Observed/Assessed physical resources/services (focus: adequacy to meet operational needs).\n▪ Interviewed AE or designated management representative(s).\n▪ Coordinated to verify adequacy of physical resources/services in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nThe management system would identify, typically through policy, risk assessment, management review or other means, the infrastructure and resource requirements that would be necessary to deliver safe and secure operations, to include operations and maintenance support facilities, services and equipment appropriate for the area, such as:\n• Buildings, workspaces and associated utilities;\n• Facilities for people in the organization;\n• Support equipment, including tools, hardware and software;\n• Support services, including transportation and communication.\nA suitable work environment satisfies human and physical factors and considers:\n• Safety rules and guidance, including the use of protective equipment;\n• Workplace location(s);\n• Workplace temperature, humidity, light, air flow;\n• Cleanliness, noise or pollution.\nImplementation of this provision (i.e. adequacy of physical resources, work environment) is typically assessed through observations made by auditors during the course of the on-site audit.", zh: "运营人应确保存在满足运行安全和安保要求所需的设施、工作空间、设备和支持服务以及工作环境。(GM) ►\n\n注：本ORG条款及其在其他ISM部分中的重复条款不要求运营人将规范文件化。\n\n审计员行动：\n▪ 观察/评估物理资源/服务（重点：是否足够满足运行需求）\n▪ 访谈AE或指定管理代表\n▪ 协调验证所有运行领域物理资源/服务的充分性\n▪ 其他行动（请说明）\n\n指导材料：\n管理系统将通过政策、风险评估、管理评审或其他方式识别交付安全可靠运行所需的基础设施和资源要求，包括适合该区域的运行和维修支持设施、服务及设备，例如：\n• 建筑物、工作空间和相关公用设施；\n• 组织人员的设施；\n• 支持设备，包括工具、硬件和软件；\n• 支持服务，包括运输和通信。\n合适的工作环境应满足人和物理因素，并考虑：\n• 安全规则和指导，包括防护设备的使用；\n• 工作场所位置；\n• 工作场所温度、湿度、光照、气流；\n• 清洁度、噪音或污染。\n本条款的实施（即物理资源、工作环境的充分性）通常通过审计员在现场审计期间的观察进行评估。" },
            { subtitle: "ORG 1.5.3 人员选拔", eng: "The Operator shall have a selection process for management and non-management positions within the organization that require the performance of functions relevant to the safety or security of aircraft operations. Such process shall ensure candidates are selected on the basis of knowledge, skills, training and experience appropriate for the position. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed standards/processes for hiring/selection of management/non-management personnel (focus: safety/security positions relevant to aircraft operations are filled by personnel with qualifications appropriate for position).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Interviewed selected personnel that perform safety/security functions relevant to aircraft operations.\n▪ Coordinated to verify implementation of personnel selection standards/processes in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nPrerequisite criteria for each position, which would typically be developed by the operator, and against which candidates would be evaluated, ensure personnel are appropriately qualified for management system positions and operational roles in areas of the organization critical to safe and secure operations.", zh: "运营人应制定组织中需要执行与航空器运行安全或安保相关职能的管理和非管理职位的选拔流程。该流程应确保根据适合该职位的知识、技能、培训和经验选拔候选人。(GM) ►\n\n审计员行动：\n▪ 识别/评估招聘/选拔管理/非管理人员的标准/流程（重点：与航空器运行相关的安全/安保职位由具有适当资格的人员担任）\n▪ 访谈AE和/或指定管理代表\n▪ 访谈选定的执行与航空器运行相关的安全/安保职能的人员\n▪ 协调验证所有运行领域人员选拔标准/流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n每个职位的先决条件通常由运营人制定，并根据这些条件评估候选人，确保人员具有适当资格担任对安全可靠运行至关重要的组织领域中的管理系统职位和运行角色。" },
            { subtitle: "ORG 1.5.4 能力保持", eng: "The Operator shall ensure personnel who perform functions relevant to the safety or security of aircraft operations are required to maintain competence on the basis of continued education and training and, if applicable for a specified position, continue to satisfy any mandatory technical competency requirements. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed standards/processes for maintaining competency of personnel in functions relevant to safety/security of aircraft operations (focus: standards specify continuing education/training, meeting technical requirements).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Coordinated to verify application of competency standards.\n▪ Other Actions (Specify)\n\nGuidance:\nPositions or functions within an airline organization considered 'operationally critical' are those that have the potential to affect operational safety or security. This definition includes management positions and any positions or functions that may affect the airworthiness of aircraft.\nTypically, training programs are implemented to ensure personnel throughout the organization are qualified and competent to perform individual duties.\nSome management positions within airline operations may require an individual to maintain a technical competency as a requirement for being assigned to the position. For example, it may be specified that certain management positions within Flight Operations may only be filled by individuals who are qualified flight crew members. Similar situations could exist within Cabin Operations, Engineering and Maintenance or other operational disciplines.\nIn such cases, the job description specifies the requirement for maintaining technical competency, and adequate opportunity is provided to fulfill the requirement.", zh: "运营人应确保执行与航空器运行安全或安保相关职能的人员需要通过继续教育和培训保持能力，并且（如适用于特定职位）继续满足任何强制性技术能力要求。(GM)\n\n审计员行动：\n▪ 识别/评估保持人员在航空器运行安全/安保相关职能方面能力的标准/流程（重点：标准规定继续教育/培训，满足技术要求）\n▪ 访谈AE和/或指定管理代表\n▪ 协调验证能力标准的应用\n▪ 其他行动（请说明）\n\n指导材料：\n航空公司组织中被视为\"运行关键\"的职位或职能是那些可能影响运行安全或安保的职位或职能。这个定义包括管理职位和任何可能影响飞机适航性的职位或职能。\n通常，实施培训计划是为了确保整个组织的人员有资格且有能力履行各自的职责。\n航空公司运行中的某些管理职位可能要求个人保持技术能力作为被分配该职位的条件。例如，可能规定飞行运行中的某些管理职位只能由有资格的飞行机组成员担任。客舱运行、工程和维修或其他运行学科中也可能存在类似情况。\n在这种情况下，职位描述规定了保持技术能力的要求，并提供适当的机会来满足该要求。" },
            { subtitle: "ORG 1.5.5 精神活性物质政策", eng: "The Operator shall have a policy that addresses the use of psychoactive substances by personnel that perform operational functions and, as a minimum:\n(i) Prohibits the exercise of duties while under the influence of psychoactive substances;\n(ii) Prohibits the problematic use of psychoactive substances;\n(iii) Requires that all personnel who are identified as engaging in problematic use of psychoactive substances are removed from operational functions;\n(iv) Conforms to the requirements of the Authority, if applicable. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed policy that addresses use of psychoactive substances by operational personnel.\n▪ Interviewed responsible manager(s).\n▪ Interviewed operational personnel (focus: familiarity with psychoactive substance policy).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Biochemical Testing, Psychoactive Substance and Problematic Use of Substances.\nPersonnel that perform operational safety and security functions as specified in this provision refers to persons in all operational disciplines who perform a function that, if performed improperly, could endanger the safety of aircraft operations. This includes operational personnel in all areas (flight crew, cabin crew, flight dispatch personnel (FOO/FOA), maintenance, ground handling, cargo, security).\nOperators subject to laws or regulations of the State that preclude the publication of a psychoactive substance prohibition policy as specified in this provision may demonstrate an equivalent method of ensuring that personnel engaging in problematic use of psychoactive substance abuse do not exercise their duties and are removed from safety-critical functions.\nRe-instatement to safety-critical duties could be possible after cessation of the problematic use and upon determination that continued performance of such duties is unlikely to jeopardize safety.\nSome of the specifications of this provision related to flight and cabin crews may be addressed through implementation of a scheduling policy in accordance with FLT 3.4.2 and CAB 3.1.7.\nExamples of other subjects that might be addressed in a comprehensive and proactive policy include:\n• Education regarding the use of psychoactive substances;\n• Identification, treatment and rehabilitation;\n• Employment consequences of problematic use of psychoactive substances;\n• Biochemical testing;\n• Requirements of ICAO and the Authority.\nAdditional guidance may be found in the ICAO Manual on Prevention of Problematic use of Substances in the Aviation Workplace (Doc 9654-AN/945).", zh: "运营人应制定关于执行运行职能人员使用精神活性物质的政策，至少包括：\n(i) 禁止在精神活性物质影响下履行职责；\n(ii) 禁止有问题的精神活性物质使用；\n(iii) 要求所有被确定有精神活性物质问题使用的人员从运行职能中撤出；\n(iv) 如适用，符合局方要求。(GM)\n\n审计员行动：\n▪ 识别/评估关于运行人员使用精神活性物质的政策\n▪ 访谈负责经理\n▪ 访谈运行人员（重点：熟悉精神活性物质政策）\n▪ 其他行动（请说明）\n\n指导材料：\n生化检测、精神活性物质和物质问题使用的定义请参阅IRM。\n本条款中规定的执行运行安全和安保职能的人员是指所有运行学科中执行某项职能的人员，如果该职能执行不当可能危及航空器运行安全。这包括所有领域的运行人员（飞行机组、客舱机组、飞行签派人员、维修、地面操作、货运、安保）。\n受国家法律或法规约束而无法发布本条款规定的精神活性物质禁令政策的运营人，可以证明采用等效方法确保有精神活性物质问题使用的人员不履行职责并从安全关键职能中撤出。\n在停止问题使用后，并确定继续履行此类安全关键职能不太可能危及安全后，可以恢复履行安全关键职责。\n本条款中与飞行机组和客舱机组相关的一些规范可以通过根据FLT 3.4.2和CAB 3.1.7实施排班政策来满足。\n全面且主动的政策可能涉及的其他主题示例包括：\n• 关于精神活性物质使用的教育；\n• 识别、治疗和康复；\n• 有问题的精神活性物质使用的就业后果；\n• 生化检测；\n• ICAO和当局的要求。\n更多指导可参见ICAO《航空工作场所预防物质问题使用手册》（Doc 9654-AN/945）。" },
            { subtitle: "ORG 1.5.6 身体与医疗健康", eng: "The Operator should have a policy that requires personnel who perform operational functions critical to the safety of aircraft operations to be physically and medically fit for duty. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed policy that requires personnel in operational functions critical to the safety of aircraft operations to be physically/medically fit for duty (focus: methods used to determine physical/medical fitness).\n▪ Interviewed AE or designated management representative(s).\n▪ Coordinated to verify policy is implemented in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Operational Function (Aircraft Operations).", zh: "运营人应制定政策，要求执行对航空器运行安全关键的操作职能的人员在身体和医疗上适合履行职责。(GM)（推荐实践）\n\n审计员行动：\n▪ 识别/评估要求执行航空器运行安全关键操作职能的人员在身体/医疗上适合履行职责的政策（重点：用于确定身体/医疗健康的方法）\n▪ 访谈AE或指定管理代表\n▪ 协调验证政策在所有运行领域得到实施\n▪ 其他行动（请说明）\n\n指导材料：\n运行职能（航空器运行）的定义请参阅IRM。" },
            { subtitle: "ORG 1.5.7 职前检测", eng: "The Operator should have a procedure to ensure screening or testing for psychoactive substances is performed on prospective operational personnel, unless such screening or testing is performed or prohibited by the State.\n\nAuditor Actions:\n▪ Identified/Assessed procedure used for screening/testing operational personnel for psychoactive substances.\n▪ Interviewed the responsible manager(s) in operational areas.\n▪ Examined selected records of screening/testing for psychoactive substances.\n▪ Other Actions (Specify)", zh: "运营人应制定程序，确保对未来的运行人员进行精神活性物质筛查或检测，除非此类筛查或检测由国家执行或禁止。（推荐实践）\n\n审计员行动：\n▪ 识别/评估用于筛查/检测运行人员精神活性物质的程序\n▪ 访谈运行领域的负责经理\n▪ 检查选定的精神活性物质筛查/检测记录\n▪ 其他行动（请说明）" }
        ]
    },
       outsourcing_mgmt: {
        title: "1.6 外委管理 - Outsourcing Management",
        sections: [
            { subtitle: "ORG 1.6.1 服务商选拔", eng: "If the Operator has external service providers conduct outsourced operational functions, the Operator shall ensure a service provider selection process is in place that ensures:\n(i) Relevant safety and security selection criteria are established;\n(ii) Service providers are evaluated against such criteria prior to selection. [MA] (GM) ►\n\nNote: This provision would not apply in cases where there is only a single provider, or the selection is not directly controlled by the Operator.\n\nAuditor Actions:\n▪ Identified/Assessed selection process for external service providers.\n▪ Interviewed manager and/or designated management representative(s).\n▪ Examined selected records/documents that demonstrate application of the selection process.\n▪ Coordinated to verify implementation of selection process in all operational areas.\n▪ Other Actions (specify)\n\nGuidance:\nThe intent of this provision is for an operator to define relevant safety and security criteria for use in the evaluation and potential selection of service providers. This is the first step in the management of external service providers and would take place prior to the operator signing an agreement with a provider. The process need be applied only once leading up to the selection of an individual service provider. The specified evaluation would typically be done as part of a tendering process once one or more potential service providers have been identified for consideration and are being vetted.\nThe provision specifies relevant safety and security selection criteria, but an operator would always have the discretion to include additional selection criteria that might not be directly related to the safety or security of the services to be provided.\nThe selection process would normally be applied when there is a need for a new service provider, such as when opening a new destination or outsourcing a service that has previously been performed using internal resources. It might also be applied when the term of an existing service provider contract is about to expire and one or more replacement providers are being considered for a new agreement.\nThe focus of the selection process is on the contracted services with a provider over an extended time period as specified in an agreement. It is possible that there could be the need for an ad-hoc selection process should an existing provider be unable to deliver contracted services due to unplanned or unexpected circumstances (e.g. unable to deliver the contracted services due to loss of accreditation, financial problems, labor disruption). In such case, an alternative process might be required because there is a lack of time to carry out the full process as specified.\nAlso, the specified selection process might have limited value, or would not be applicable, at a location where there is only one service provider available (e.g. station monopoly, government/authority-provided services). Further, it would not apply if an operator has no control over external service providers (e.g. when wet leasing aircraft from another operator, or if the authority designates specific providers). In such situations, the operator would need to apply sound risk management to determine whether its safety and security requirements will be satisfied by the only available service provider should it choose to continue conducting operations at the location.\n\nAssessment Tool\nDesired Outcome: The selection process for external service providers supports safety and security standards and objectives. Service providers are selected in consideration of the operator's SMS.\nSuitability Considerations: • Selection process based on size and complexity of the organization\nC1 (Established): Personnel involved in the service provider selection process have been instructed and/or trained for the process.\nC2 (Established): There is a simplified process for selection of ad-hoc (temporary) providers.\nC3 (Established): Criteria identified for the service provider selection, are clearly described and understood by the personnel responsible for the decision making.\nC4 (Mature): Safety Management System of the major service providers are assessed thoroughly.\nC5 (Mature): The majority of selected service providers that conduct ground handling operations for the Operator adopt recognized industry practices, such as the IATA Ground Operations Manual (IGOM) as a baseline for their operational procedures.\nC6 (Mature): A detailed risk assessment is performed in cases where only one service provider is available and necessary mitigating actions are implemented.\nC7 (Mature): The service provider selection process is conducted using a risk-based approach which adjusts the selection method when required.\nC8 (Leading): Safety and security selection criteria align with the organization's most significant safety risks.\nC9 (Leading): The service provider selection process involves relevant operational personnel and/or subject matter experts in developing and assessing appropriate safety and security criteria.\nC10 (Leading): The selection of major service providers is based on indices and criteria which are analyzed through operational experts by considering external and internal factors of the Operator.\nC11 (Leading): The Operator uses industry recognized programs such as ISAGO, IFQP and DAQCP etc. as the basis for service provider selection.\nC12 (Leading): Safety and security criteria identified for the service provider selection refers to Safety Objectives and/or Safety Performance Indicators (SPIs).", zh: "如果运营人有外部服务提供商执行外委运行职能，运营人应确保建立服务提供商选择流程，确保：\n(i) 建立相关的安全和安保选择标准；\n(ii) 在选择前根据此类标准评估服务提供商。[MA] (GM) ►\n\n注：如果只有一个提供商，或者选择不由运营人直接控制，则本条款不适用。\n\n审计员行动：\n▪ 识别/评估外部服务提供商的选择流程\n▪ 访谈经理和/或指定管理代表\n▪ 检查选定的证明选择流程应用的记录/文件\n▪ 协调验证所有运行领域选择流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n本条款的意图是让运营人定义相关的安全和安保标准，用于评估和可能的服务提供商选择。这是管理外部服务提供商的第一步，将在运营人与提供商签署协议之前进行。在选择单个服务提供商之前，该流程只需应用一次。一旦确定了一个或多个潜在服务提供商进行考虑和审查，指定的评估通常作为招标过程的一部分进行。\n该条款规定了相关的安全和安保选择标准，但运营人始终可以自行决定包括可能与所提供服务的安全或安保无直接关系的额外选择标准。\n选择流程通常在需要新的服务提供商时应用，例如开通新目的地或将先前使用内部资源执行的服务外委时。也可能在现有服务提供商合同即将到期，并且正在考虑一个或多个替代提供商签订新协议时应用。\n选择流程的重点是在协议规定的时间段内与提供商的合同服务。如果现有提供商因计划外或意外情况（例如因失去认证、财务问题、劳工中断而无法交付合同服务）而无法交付合同服务，则可能需要临时选择流程。在这种情况下，由于没有时间执行规定的完整流程，可能需要替代流程。\n此外，在只有一个服务提供商可用的地点（例如站点垄断、政府/当局提供的服务），指定的选择流程可能价值有限或不适用。此外，如果运营人无法控制外部服务提供商（例如从另一运营人湿租飞机，或当局指定特定提供商），则本条款不适用。在这种情况下，运营人需要运用健全的风险管理来确定，如果选择继续在该地点开展运行，唯一可用的服务提供商是否能满足其安全和安保要求。\n\n评估工具\n预期结果：外部服务提供商的选择流程支持安全和安保标准与目标。选择服务提供商时考虑运营人的SMS。\n充分性考虑：• 基于组织规模和复杂性的选择流程\nC1（建立）：参与服务提供商选择流程的人员已接受该流程的指导/培训。\nC2（建立）：有简化流程用于选择临时提供商。\nC3（建立）：为服务提供商选择确定的标准被清晰描述并被负责决策的人员理解。\nC4（成熟）：对主要服务提供商的安全管理体系进行彻底评估。\nC5（成熟）：为运营人进行地面操作的大多数选定服务提供商采用公认的行业实践，例如以IATA地面操作手册（IGOM）作为其操作程序的基准。\nC6（成熟）：在只有一个服务提供商可用的情况下进行详细风险评估，并实施必要的缓解措施。\nC7（成熟）：服务提供商选择流程采用基于风险的方法，在需要时调整选择方法。\nC8（领先）：安全和安保选择标准与组织最重要的安全风险相一致。\nC9（领先）：服务提供商选择流程涉及相关运行人员和/或主题专家制定和评估适当的安全和安保标准。\nC10（领先）：主要服务提供商的选择基于指数和标准，通过运行专家考虑运营人的外部和内部因素进行分析。\nC11（领先）：运营人使用行业认可的项目（如ISAGO、IFQP和DAQCP等）作为服务提供商选择的基础。\nC12（领先）：为服务提供商选择确定的安全和安保标准参考安全目标和/或安全绩效指标（SPI）。" },
            { subtitle: "ORG 1.6.2 合同要求", eng: "The Operator shall have processes to ensure a contract or agreement is executed with external service providers that conduct outsourced operational functions for the Operator. Such contract or agreement shall identify specific documented requirements that can be monitored by the Operator to ensure the safety and/or security of operations are being fulfilled by the service provider. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed processes for contract/agreement production/execution with external service providers that conduct outsourced operations, maintenance security functions.\n▪ Interviewed responsible manager(s).\n▪ Examined selected outsourcing contracts/agreements (focus: inclusion of or reference to specific requirements applicable to service providers).\n▪ Coordinated to verify implementation of service provider contract/agreement processes in applicable operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Outsourcing and Service Level Agreement (SLA).\nAn operator would always retain full responsibility for ensuring an outsourced operational function is performed properly by an external provider, even if such provider is the parent organization or an affiliate of the operator.\nA contract or agreement is necessary to ensure details of the operational functions to be performed by the external service provider are formally documented. The contract or agreement not only sets forth commercial terms, but also specific safety and/or security requirements pertaining to the services the provider is expected to perform. These requirements typically form the basis for the monitoring of the service provider by the operator.\nExamples of specific documented requirements could include the following:\n• Processes or procedures from the operator's own documentation system (e.g. operational manuals, working instructions) that can be included in the contract by reference.\n• Infrastructure, resource or certification requirements (e.g. number of personnel, certification standards for equipment, support equipment standards).\n• SPIs that specify a maximum number of occurrences or deviations), which could be based on the operator's own SPIs in accordance with ORG 1.4.2.\nThe structure of contracts or agreements will vary with individual operators and, depending on such structure, defined specific requirements may or may not be contained in any of the contractual documents. When the specific requirements are not contained in the contract, they may be defined (in technical terms) in a controlled document that is part of the operator's documentation system, and then conveyed to the provider (perhaps periodically) in a manner that ensures understanding. Such controlled documents are typically identified in the contract by reference.\nNote: For the purpose of this provision, the contract or agreement as specified above may comprise multiple parts, including the basic document that sets forth legal and commercial terms and, as applicable, other associated documents that state terms or conditions of service (e.g. appendices, addenda, service level agreement).", zh: "运营人应制定流程，确保与为运营人执行外委运行职能的外部服务提供商签订合同或协议。此类合同或协议应明确可被运营人监控的具体文件化要求，以确保服务提供商履行运行的安全和/或安保。(GM) ►\n\n审计员行动：\n▪ 识别/评估与执行外委运行、维修安保职能的外部服务提供商签订/执行合同/协议的流程\n▪ 访谈负责经理\n▪ 检查选定的外委合同/协议（重点：包含或引用适用于服务提供商的具体要求）\n▪ 协调验证适用运行领域服务提供商合同/协议流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n外委和服务水平协议（SLA）的定义请参阅IRM。\n运营人始终对外部提供商是否正确执行外委运行职能承担全部责任，即使该提供商是运营人的母公司或关联公司。\n合同或协议对于确保外部服务提供商将要执行的运行职能细节得到正式记录是必要的。合同或协议不仅规定了商业条款，还规定了与提供商预期执行的服务相关的具体安全和/或安保要求。这些要求通常构成运营人监控服务提供商的基础。\n具体文件化要求的示例可能包括：\n• 运营人自己文件系统中的流程或程序（例如运行手册、工作指令），可通过引用包含在合同中。\n• 基础设施、资源或认证要求（例如人员数量、设备认证标准、支持设备标准）。\n• 规定最大事件发生率或数量的SPI，这些SPI可能基于运营人根据ORG 1.4.2制定的自有SPI。\n合同或协议的结构因运营人而异，根据此类结构，定义的具体要求可能包含也可能不包含在任何合同文件中。当具体要求不包含在合同中时，它们可以在作为运营人文件系统一部分的受控文件中（以技术术语）定义，然后以确保理解的方式（可能定期）传达给提供商。此类受控文件通常在合同中通过引用进行标识。\n注：就本条款而言，上述合同或协议可包括多个部分，包括规定法律和商业条款的基本文件，以及在适用情况下说明服务条款或条件的其他相关文件（例如附录、增编、服务水平协议）。" }
        ]
    },
        emergency_response: {
        title: "1.7 应急响应 - Emergency Response",
        sections: [
            { subtitle: "ORG 1.7.1 公司应急响应计划", eng: "The Operator shall have a corporate emergency response plan (ERP) for the central management and coordination of all activities necessary to respond to a major aircraft accident or other type of adverse event that results in fatalities, serious injuries, considerable damage and/or a significant disruption of aircraft operations. [SMS] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed corporate emergency response plan (ERP) (focus: plan suitable for organizational response to major aircraft accident/other adverse event).\n▪ Interviewed designated ERP manager.\n▪ Coordinated to verify implementation of ERP in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Emergency Response Plan (ERP) and Public Health Emergency.\nEmergency response planning is an element of the Safety Policy and Objectives component of the SMS framework.\nAn emergency (or crisis) response plan is based upon an assessment of risk appropriate to the size and type of operations, and includes consideration of a major aircraft accident and other potential, aircraft and/or non-aircraft events that would require a full corporate emergency response.\nIn some states, emergency or crisis response is assumed by a governmental authority rather than by the operator. In such case, an emergency response plan focuses on and addresses interaction with and/or participation in the governmental response to an emergency or crisis.\nAs a best practice, an operator might consider defining in its ERP an appropriately coordinated response to a public health emergency.\nAn effective ERP includes industry best practices and ensure community expectations are addressed. Additionally, an ERP:\n• Specifies general conditions for implementation;\n• Provides a framework for an orderly implementation;\n• Ensures proper coordination with external entities at all potential locations (refer to ORG 1.7.4);\n• Addresses all potential aspects of an event, including casualties;\n• Ensures regulatory requirements associated with specific events are satisfied;\n• Provides a scenario for the transition back to normal operations;\n• Ensures regular practice exercises as a means to achieve continual improvement (refer to ORG 1.7.8 and ORG 1.7.9).\nIATA provides a guide for use by operators in addressing a public health emergency. Such document, titled Emergency Response Plan and Action Checklist, may be found at http://www.iata.org/whatwedo/safety/health/Pages/diseases.aspx.", zh: "运营人应制定公司应急响应计划（ERP），用于集中管理和协调应对重大航空器事故或导致死亡、重伤、重大损坏和/或航空器运行严重中断的其他类型不利事件所需的所有活动。[SMS] (GM)\n\n审计员行动：\n▪ 识别/评估公司应急响应计划（ERP）（重点：计划适合组织应对重大航空器事故/其他不利事件）\n▪ 访谈指定的ERP经理\n▪ 协调验证所有运行领域ERP的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n应急响应计划（ERP）和公共卫生紧急事件的定义请参阅IRM。\n应急响应规划是SMS框架中安全政策和目标组成部分的一个要素。\n应急（或危机）响应计划基于适合运行规模和类型的风险评估，并包括对重大航空器事故以及其他需要全面公司应急响应的潜在航空器和/或非航空器事件的考虑。\n在某些国家，应急或危机响应由政府当局而非运营人承担。在这种情况下，应急响应计划侧重于处理与政府对紧急情况或危机的响应进行互动和/或参与。\n作为最佳实践，运营人可考虑在其ERP中定义适当协调的公共卫生紧急事件响应。\n有效的ERP包括行业最佳实践并确保解决社区期望。此外，ERP：\n• 规定实施的一般条件；\n• 提供有序实施的框架；\n• 确保与所有潜在地点的外部实体进行适当协调（见ORG 1.7.4）；\n• 处理事件的所有潜在方面，包括伤亡；\n• 确保满足与特定事件相关的法规要求；\n• 提供恢复正常运行的方案；\n• 确保定期演练作为实现持续改进的手段（见ORG 1.7.8和ORG 1.7.9）。\nIATA为运营人提供了处理公共卫生紧急事件的指南。该文件题为《应急响应计划和行动检查单》，可在http://www.iata.org/whatwedo/safety/health/Pages/diseases.aspx找到。" },
            { subtitle: "ORG 1.7.2 ERP经理", eng: "The Operator shall have a designated manager with appropriate qualifications and authority to manage and be responsible for the development, implementation and maintenance of the corporate ERP. (GM)\n\nAuditor Actions:\n▪ Identified designated corporate ERP manager.\n▪ Examined job description of ERP manager (focus: background/duties/responsibilities).\n▪ Interviewed corporate ERP manager.\n▪ Other Actions (Specify)\n\nGuidance:\nThe exact title of the manager designated as responsible for the corporate ERP may vary depending on the organization.\nIn order to manage a corporate ERP, an individual's qualifications would typically include training and background experience that ensures the requisite knowledge in emergency response principles. Such experience and knowledge is necessary, even though various ERP functions are typically delegated to designated personnel throughout the management system.", zh: "运营人应指定一名具有适当资格和权限的经理，负责管理公司ERP的制定、实施和维护。(GM)\n\n审计员行动：\n▪ 识别指定的公司ERP经理\n▪ 检查ERP经理的职位描述（重点：背景/职责/责任）\n▪ 访谈公司ERP经理\n▪ 其他行动（请说明）\n\n指导材料：\n被指定负责公司ERP的经理的确切头衔可能因组织而异。\n为了管理公司ERP，个人的资格通常包括培训和背景经验，确保具备应急响应原则方面的必要知识。即使各种ERP职能通常委派给整个管理系统中指定的人员，这种经验和知识也是必要的。" },
            { subtitle: "ORG 1.7.3 部门与站点ERP协调", eng: "If the Operator has individual departmental or station emergency response plans within the organization, the Operator shall ensure such individual plans are coordinated with the overall corporate emergency response plan under the ERP manager. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed process(es) for coordinating departmental/station ERPs.\n▪ Interviewed designated corporate ERP manager.\n▪ Examined ERP for selected stations (focus: station ERP is coordinated with corporate ERP).\n▪ Other Actions (Specify)\n\nGuidance:\nCertain operational departments might have individual ERPs, especially where departments are located remotely (e.g. maintenance or cargo). Likewise, station ERPs might be individually tailored to meet varying requirements at each station. Therefore, coordination is always required to ensure each individual ERP within an operator's organization contains or addresses the applicable common elements of the corporate ERP.", zh: "如果运营人在组织内设有单独的部门或站点应急响应计划，运营人应确保此类单独计划在ERP经理的指导下与整体公司应急响应计划协调一致。(GM)\n\n审计员行动：\n▪ 识别/评估协调部门/站点ERP的流程\n▪ 访谈指定的公司ERP经理\n▪ 检查选定站点的ERP（重点：站点ERP与公司ERP协调一致）\n▪ 其他行动（请说明）\n\n指导材料：\n某些运行部门可能有单独的ERP，特别是当部门位于偏远地点时（例如维修或货运）。同样，站点ERP可能单独定制以满足每个站点的不同要求。因此，始终需要协调，以确保运营人组织内的每个单独ERP包含或处理公司ERP的适用共同要素。" },
            { subtitle: "ORG 1.7.4 外部协调", eng: "The Operator shall ensure the ERP as specified in ORG 1.7.1 includes provisions for the appropriate coordination with the emergency response plans of other applicable organizations relevant to the particular event or crisis. [SMS] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed ERP transition processes (focus: plan includes transition from normal-emergency/and emergency-normal operations; coordination with relevant external organizations).\n▪ Interviewed designated corporate ERP manager.\n▪ Other Actions (Specify)\n\nGuidance:\nCoordination of emergency response planning is an element of the Safety Policy and Objectives component of the SMS framework.\nAn ERP typically defines:\n• Coordination procedures for action by key personnel;\n• External entities that will interact with the organization during emergency situations;\n• ERPs of external entities that will require coordination;\n• Method(s) of establishing coordination with external ERPs.\nExpanded guidance may be found in the ICAO SMM, Document 9859.", zh: "运营人应确保ORG 1.7.1中规定的ERP包含与特定事件或危机相关的其他适用组织的应急响应计划进行适当协调的规定。[SMS] (GM)\n\n审计员行动：\n▪ 识别/评估ERP过渡流程（重点：计划包括从正常到紧急/紧急到正常运行的过渡；与相关外部组织的协调）\n▪ 访谈指定的公司ERP经理\n▪ 其他行动（请说明）\n\n指导材料：\n应急响应规划的协调是SMS框架中安全政策和目标组成部分的一个要素。\nERP通常定义：\n• 关键人员行动的协调程序；\n• 在紧急情况下将与本组织互动的外部实体；\n• 需要协调的外部实体的ERP；\n• 与外部ERP建立协调的方法。\n扩展指导可参见ICAO SMM，文件9859。" },
            { subtitle: "ORG 1.7.5 执行程序与职责", eng: "The Operator shall have published procedures and assigned responsibilities to ensure a coordinated execution of the corporate ERP. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed procedures/responsibilities for execution of corporate ERP.\n▪ Interviewed designated corporate ERP manager.\n▪ Coordinated to verify procedures/assigned responsibilities for ERP execution in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nPersonnel are typically assigned with specific responsibilities throughout the organization for the implementation of procedures associated with the ERP. Such responsibilities and procedures might include:\n• Assemblage of required personnel;\n• Travel arrangements, as required;\n• Provision of facilities, equipment and other resources;\n• Humanitarian and other assistance to individuals involved in the event, as required;\n• Management of continuing normal operations;\n• Control of areas impacted by the event, as applicable;\n• Liaison with relevant authorities and other external entities.\nThe following areas would normally be considered in developing plans for liaison with external entities associated with any event:\n• Fire;\n• Police;\n• Ambulance;\n• Coast guard and other rescue agencies;\n• Hospitals and other medical facilities;\n• Medical specialists;\n• Civil aviation or defense agencies;\n• Poison control centers;\n• Chemical or radiation specialists;\n• Environmental agencies;\n• Insurance companies.\nAdditionally, contact and arrangements are typically made with certain operational business partners, including code share and wet lease operators.", zh: "运营人应发布程序并分配职责，以确保公司ERP的协调执行。(GM)\n\n审计员行动：\n▪ 识别/评估执行公司ERP的程序/职责\n▪ 访谈指定的公司ERP经理\n▪ 协调验证所有运行领域ERP执行的程序/分配职责\n▪ 其他行动（请说明）\n\n指导材料：\n通常在整个组织中分配人员具体职责，以实施与ERP相关的程序。此类职责和程序可能包括：\n• 所需人员的召集；\n• 所需的旅行安排；\n• 提供设施、设备和其他资源；\n• 根据需要向事件涉及的个人提供人道主义和其他援助；\n• 管理持续的正常运行；\n• 酌情控制受事件影响的区域；\n• 与相关当局和其他外部实体联络。\n在制定与任何事件相关的外部实体联络计划时，通常会考虑以下领域：\n• 消防；\n• 警察；\n• 救护车；\n• 海岸警卫队和其他救援机构；\n• 医院和其他医疗设施；\n• 医学专家；\n• 民航或国防机构；\n• 毒物控制中心；\n• 化学或辐射专家；\n• 环境机构；\n• 保险公司。\n此外，通常还与某些运行业务合作伙伴（包括代码共享和湿租运营人）进行联系和安排。" },
            { subtitle: "ORG 1.7.6 旅客名单", eng: "The Operator shall have a process in the ERP to provide an accurate manifest to the appropriate authorities in the event of an aircraft accident. Such manifest shall list crew members, passengers and cargo, to include dangerous goods.\n\nAuditor Actions:\n▪ Identified/Assessed ERP process for providing accurate manifest to authorities in the event of aircraft accident.\n▪ Interviewed designated corporate ERP manager.\n▪ Identified specific person/function with assigned responsibility for providing accurate manifest to authorities in the event of aircraft accident.\n▪ Other Actions (Specify)", zh: "运营人应在ERP中制定流程，以便在航空器事故发生时向适当当局提供准确的舱单。该舱单应列明机组成员、乘客和货物，包括危险品。\n\n审计员行动：\n▪ 识别/评估ERP中在航空器事故时向当局提供准确舱单的流程\n▪ 访谈指定的公司ERP经理\n▪ 识别在航空器事故时负责向当局提供准确舱单的特定人员/职能\n▪ 其他行动（请说明）" },
            { subtitle: "ORG 1.7.7 ERP人员培训", eng: "The Operator should ensure all personnel with responsibilities under the ERP are appropriately trained and qualified to execute applicable procedures. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed training/qualification program for ERP personnel.\n▪ Interviewed designated corporate ERP manager.\n▪ Examined training curriculum for ERP personnel (focus: training subjects appropriate for role in ERP).\n▪ Examined selected training/qualification records of ERP personnel (focus: completion of ERP training).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Family Assistance.\nTraining for personnel with responsibilities under the ERP could be conducted externally or in-house by an operator's own qualified staff, and would typically include drills, desktop exercises, and/or simulations. Attendees typically include both management and operational personnel from the headquarters and, as applicable to the operator's structure, station locations.\nIdeally, specific and/or personalized training would also be conducted for key senior managers (e.g. CEO).\nTraining programs are generally tailored for personnel based on the role performed under the ERP.\nTypically, persons involved in family assistance and crisis communications, as well as members of the corporate emergency response group or committee (as applicable), would be required to complete ERP training.\nThe curriculum for ERP training normally includes general subjects associated with emergency response management, as well as role-specific subjects that address issues associated with:\n• Family assistance/special assistance;\n• Cultural sensitivity;\n• Telephone enquiry;\n• Team call-out and assembly;\n• Crash site discipline;\n• Effects retrieval.", zh: "运营人应确保ERP下负有责任的所有人员经过适当培训并具备执行适用程序的资格。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估ERP人员的培训/资格方案\n▪ 访谈指定的公司ERP经理\n▪ 检查ERP人员的培训课程（重点：培训主题适合其在ERP中的角色）\n▪ 检查选定的ERP人员培训/资格记录（重点：完成ERP培训）\n▪ 其他行动（请说明）\n\n指导材料：\n家庭援助的定义请参阅IRM。\n对ERP下负有责任的人员的培训可以由运营人自己的合格员工在外部或内部进行，通常包括演练、桌面推演和/或模拟。参与者通常包括来自总部的管理和运行人员，以及根据运营人结构适用的站点位置。\n理想情况下，还应为关键高级管理人员（例如CEO）进行特定和/或个性化培训。\n培训方案通常根据人员在ERP下执行的职能量身定制。\n通常，参与家庭援助和危机沟通的人员，以及公司应急响应小组或委员会的成员（如适用），需要完成ERP培训。\nERP培训的课程通常包括与应急响应管理相关的通用主题，以及处理以下相关问题的特定角色主题：\n• 家庭援助/特别援助；\n• 文化敏感性；\n• 电话查询；\n• 团队召集和集合；\n• 坠机现场纪律；\n• 物品回收。" },
            { subtitle: "ORG 1.7.8 定期演练", eng: "The Operator shall ensure the corporate ERP is rehearsed periodically to:\n(i) Familiarize personnel with responsibilities and procedures;\n(ii) Ensure ready functionality of all equipment and facilities;\n(iii) Expose deficiencies in the plan and its execution, and ensure such deficiencies are addressed. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed plan for corporate ERP rehearsal (focus: definition of rehearsal type/schedule; rehearsals include use of applicable personnel/facilities/equipment).\n▪ Interviewed designated corporate ERP manager.\n▪ Examined selected records of ERP rehearsals (focus: implementation/completion of ERP rehearsals).\n▪ Other Actions (Specify)\n\nGuidance:\nThe ERP typically has provisions that ensure all aspects of the ERP are rehearsed or practiced at regular intervals, and practice exercises include the involvement of all personnel that would be called upon during an actual emergency or crisis situation. In some locations, the extent of ERP rehearsals might be limited by the relevant authority. In such cases, a modified rehearsal that ensures overall ERP readiness in accordance with the specifications stated in this provision is acceptable.\nRehearsal of an ERP typically results in the discovery of, and thus an opportunity to correct, deficiencies in the plan. Such deficiencies could include outdated contact information (e.g. names, telephone numbers, email addresses) and/or plan execution discrepancies (e.g. organizational changes, personnel turnover).\nThe results of rehearsals or practice exercises are normally recorded and analyzed, and then used as the basis for continual improvement of the plan (refer to ORG 1.7.9).", zh: "运营人应确保公司ERP定期演练，以：\n(i) 使人员熟悉职责和程序；\n(ii) 确保所有设备和设施随时可用；\n(iii) 暴露计划及其执行中的缺陷，并确保此类缺陷得到解决。(GM)\n\n审计员行动：\n▪ 识别/评估公司ERP演练计划（重点：定义演练类型/时间表；演练包括使用适用人员/设施/设备）\n▪ 访谈指定的公司ERP经理\n▪ 检查选定的ERP演练记录（重点：ERP演练的实施/完成）\n▪ 其他行动（请说明）\n\n指导材料：\nERP通常有规定，确保ERP的所有方面定期演练或实践，演练包括在实际紧急或危机情况下将调用的所有人员的参与。在某些地点，ERP演练的范围可能受到相关当局的限制。在这种情况下，确保根据本条款规定确保ERP整体就绪状态的修改后的演练是可接受的。\nERP的演练通常会导致发现计划中的缺陷，从而有机会纠正这些缺陷。此类缺陷可能包括过时的联系信息（例如姓名、电话号码、电子邮件地址）和/或计划执行差异（例如组织变更、人员流动）。\n演练或实践练习的结果通常被记录和分析，然后用作持续改进计划的基础（见ORG 1.7.9）。" },
            { subtitle: "ORG 1.7.9 演练后讲评", eng: "The Operator should have a process for a detailed debriefing and critique whenever the ERP is executed, either as a rehearsal or in response to an actual event. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed process for debriefing/critique after execution of ERP (focus: debriefing/critique part of actual/rehearsed ERP implementation).\n▪ Interviewed designated corporate ERP manager.\n▪ Examined selected records of detailed debriefing/critique after rehearsal/actual ERP activation.\n▪ Other Actions (Specify)\n\nGuidance:\nSuch process ensures vital information is communicated to regulatory authorities, corporate management, operational personnel and the local community whenever the ERP is activated, whether for an actual event or for a rehearsal.\nIf recommendations for corrective action or other changes result from activation of the plan, there is typically a process for providing a de-briefing to relevant internal and external entities to ensure awareness and consideration of such recommendations.", zh: "运营人应制定流程，在ERP执行时（无论是作为演练还是响应实际事件）进行详细的汇报和评议。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估ERP执行后汇报/评议的流程（重点：实际/演练ERP实施中的汇报/评议部分）\n▪ 访谈指定的公司ERP经理\n▪ 检查选定的演练/实际ERP激活后详细汇报/评议的记录\n▪ 其他行动（请说明）\n\n指导材料：\n无论是对实际事件还是演练，每当ERP被激活时，此类流程确保将重要信息传达给监管当局、公司管理层、运行人员和当地社区。\n如果计划的激活导致纠正措施或其他变更的建议，通常有一个流程向相关内部和外部实体提供汇报，以确保对此类建议的认识和考虑。" },
            { subtitle: "ORG 1.7.10 应急管理中心", eng: "The Operator should have the ready availability of a facility for use as an emergency management center (EMC) with sufficient space, furnishings and equipment to successfully manage the execution of the corporate ERP.\n\nAuditor Actions:\n▪ Observed/Assessed emergency management center (focus: adequate space/furnishings/equipment to manage ERP and associated resources).\n▪ Interviewed designated corporate ERP manager.\n▪ Other Actions (Specify)", zh: "运营人应随时可用一个设施作为应急管理中心（EMC），具有足够的空间、家具和设备，以成功管理公司ERP的执行。（推荐实践）\n\n审计员行动：\n▪ 观察/评估应急管理中心（重点：足够的空间/家具/设备以管理ERP和相关资源）\n▪ 访谈指定的公司ERP经理\n▪ 其他行动（请说明）" },
            { subtitle: "ORG 1.7.11 对外沟通协调", eng: "The Operator should have procedures under the corporate ERP that ensure a central coordination and control of all communications with external entities. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed ERP procedures for central coordination/control of communications with external entities.\n▪ Interviewed designated corporate ERP manager.\n▪ Other Actions (Specify)\n\nGuidance:\nA vital aspect of an effective ERP is ensuring a controlled and consistent message to external entities, especially the news media. The ERP would typically include the designation of an individual or group as the central point of control for all external communication. Additionally, authorization and responsibilities would be assigned to certain personnel within the organization to act as the point(s) of contact for communication with specified external entities.", zh: "运营人应在公司ERP下制定程序，确保对所有与外部实体沟通的集中协调和控制。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估ERP中集中协调/控制与外部实体沟通的程序\n▪ 访谈指定的公司ERP经理\n▪ 其他行动（请说明）\n\n指导材料：\n有效ERP的一个重要方面是确保向外部实体（尤其是新闻媒体）传递可控且一致的信息。ERP通常包括指定个人或团体作为所有外部沟通的控制中心点。此外，将授权和责任分配给组织内的某些人员，作为与指定外部实体沟通的联系点。" },
            { subtitle: "ORG 1.7.12 应急资源", eng: "The Operator should have procedures and resources immediately available under the corporate ERP that provide for, in the event of an emergency:\n(i) The establishment of command posts (CPs) at line stations or remote locations;\n(ii) A telephone enquiry center capable of handling the potential volume of calls expected with emergency events;\n(iii) Dedicated equipment and material necessary for successful execution of the corporate ERP;\n(iv) The dispatch, on short notice, of humanitarian teams to appropriate location(s) to attend to individuals in need of assistance;\n(v) Assistance to passengers, crew and their families. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed resources available under corporate ERP (focus: local command posts; adequate communication capability; humanitarian personnel/teams; passenger/crew/family assistance).\n▪ Interviewed designated corporate ERP manager.\n▪ Observed examples of resources available in the event of ERP activation.\n▪ Other Actions (Specify)\n\nGuidance:\nIn addition to a centralized EMC as specified in ORG 1.7.10, one or more CPs (normally on standby mode) may be established at or near the crisis site. Other resources would typically include, as a minimum:\n• Adequate office furnishings and supplies;\n• Necessary communications equipment (e.g. computers, telephones, printers, facsimile);\n• Required reference documents (e.g. emergency response checklists and procedures, company manuals, airport emergency plans, telephone lists).\nAssistance to families typically requires dedicated policies and procedures, as well as the resources necessary to provide family notification and satisfy the critical aspects of logistical support (e.g. transportation, lodging, meals, security, communications, and incidental expenditures).\nRefer to the following documents for detailed guidance that addresses family assistance:\n• ICAO Doc 9859, Safety Management Manual (SMM).\n• ICAO Circular 285, Guidance on Assistance to Aircraft Accident Victims and Their Families.\n• ICAO Doc 9998, Policy on Assistance to Aircraft Accident Victims and their Families.", zh: "运营人应在公司ERP下制定程序并配备可立即使用的资源，在紧急情况下提供：\n(i) 在航线站点或偏远地点建立指挥所；\n(ii) 能够处理紧急事件预期电话量的电话查询中心；\n(iii) 成功执行公司ERP所需的专用设备和材料；\n(iv) 在短时间内派遣人道主义团队到适当地点照顾需要帮助的个人；\n(v) 对旅客、机组成员及其家属的援助。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估公司ERP下可用的资源（重点：本地指挥所；足够的通信能力；人道主义人员/团队；旅客/机组/家属援助）\n▪ 访谈指定的公司ERP经理\n▪ 观察ERP激活时可用的资源示例\n▪ 其他行动（请说明）\n\n指导材料：\n除了ORG 1.7.10中规定的集中式EMC外，还可以在危机现场或附近建立一个或多个CP（通常处于待命模式）。其他资源通常至少包括：\n• 足够的办公家具和用品；\n• 必要的通信设备（例如计算机、电话、打印机、传真机）；\n• 所需的参考文件（例如应急响应检查单和程序、公司手册、机场应急计划、电话列表）。\n家庭援助通常需要专门的政策和程序，以及提供家庭通知和满足后勤支持关键方面所需的资源（例如交通、住宿、餐饮、安保、通信和杂项支出）。\n有关家庭援助的详细指导，请参考以下文件：\n• ICAO Doc 9859，安全管理手册（SMM）\n• ICAO Circular 285，航空器事故受害者及其家属援助指南\n• ICAO Doc 9998，航空器事故受害者及其家属援助政策" }
        ]
    },
    // ==================== 第二部分：保证、监控与文件控制 ====================
        quality_assurance: {
        title: "2.1 质量保证 - Quality Assurance",
        sections: [
            { subtitle: "ORG 2.1.1 质量保证方案", eng: "The Operator shall have a quality assurance program that provides for the auditing of the management system of operations and maintenance functions to ensure the organization is:\n(i) Complying with applicable regulations and standards;\n(ii) Satisfying stated operational needs;\n(iii) Identifying areas requiring improvement;\n(iv) Identifying hazards to operations;\n(v) Assessing the effectiveness of safety risk controls. [SMS] [MA] (GM) ►\n\nNote: If the quality assurance audit function is performed by an external organization, the Operator, as the AOC holder, shall be responsible for ensuring the quality assurance program is in conformity with the specifications of this provision.\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed quality assurance program (focus: role/purpose within organization/SMS; definition of audit program scope/objectives; description of program elements/procedures for ongoing auditing of management system/operational areas).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Interviewed quality assurance program manager.\n▪ Interviewed selected operational managers (focus: interface with quality assurance program).\n▪ Examined selected audit reports (focus: audit scope/process/organizational interface).\n▪ Coordinated to verify implementation of quality assurance audit program in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Audit, Group Company and Quality Assurance.\nThe quality assurance program comprises two complementary functions: To monitor an operator's compliance with relevant regulations and standards, as well as to evaluate and continually improve operational safety performance. Such functions are elements of the Safety Assurance component of the SMS framework.\nIn some organizations the quality assurance program may have a different name (e.g. internal audit program, internal evaluation program).\nIn certain circumstances, an operator may have the quality assurance audit function performed by an external organization. This typically occurs when the operator is affiliated with one or more other organizations in a Group Company. However, an operator might also choose to simply outsource the quality assurance audit function to a qualified external service provider that is not part of or associated with a Group Company. In both cases, the operator, as the AOC holder, has the ultimate responsibility for ensuring the quality assurance program meets the needs of its organization in accordance with the specifications of this standard.\nA robust quality assurance program ensures a scope of auditing that encompasses all areas of the organization that impact operational quality in terms of safety and/or security. Operational functions include flight operations, operational control/flight dispatch, maintenance operations, cabin operations, ground handling and cargo operations.\nThis provision is designed to permit flexibility in the implementation of the quality assurance program. The structure and organization of the program within an operator's management system, whether centralized, non-centralized or a combination thereof, is at the discretion of the operator in accordance with its corporate culture and regulatory environment.\nAn effective audit program includes:\n• Audit initiation, including scope and objectives;\n• Planning and preparation, including audit plan and checklist development;\n• Observation and gathering of evidence to assess documentation and implementation;\n• Analysis, findings, actions;\n• Reporting and audit summary;\n• Follow-up and close out.\nTo ensure auditors gather sufficient evidence to produce realistic assessments during an audit, the program typically includes guidance that defines the various sampling techniques that are expected to be used by auditors in the evidence collection phase of the audit.\nThe audit process typically includes a means whereby the auditor and responsible personnel from the audited area have a comprehensive discussion and reach agreement on the findings and corresponding corrective actions. Clear procedures are established to resolve any disagreement between the auditor and audited area. All action items require follow-up to ensure closeout within an appropriate period of time.\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.\n\nAssessment Tool\nDesired Outcome: The Operator's management system is monitored and maintained in continuous compliance with all applicable standards and regulations. Relevant data for the management of operational risks is gathered and provided to relevant areas.\nSuitability Considerations: • Scope of the QA program relevant to type, size, and complexity of operations. • Tools and systems used, and their availability. • Complexity of processes and procedures based on operator's complexity. • Number and nature of non-compliances and hazards identified.\nC1 (Established): Audit results, associated corrective actions and trends are analyzed by the Operator and shared within the organization.\nC2 (Established): The interface between internal audits and the safety risk management processes is clearly described and implemented.\nC3 (Established): The manager responsible for quality assurance program reports directly to the Accountable Executive and there is a regular, effective update.\nC4 (Established): The manager responsible for quality assurance program has formal training or certification as a quality auditor, relevant operational & auditing experience and formal training in risk management & safety assurance.\nC5 (Mature): The Operator effectively identifies hazards through audits conducted under quality assurance program and/or safety audits.\nC6 (Mature): The quality assurance program effectively identifies areas requiring improvements that lead to actions taken for improvement.\nC7 (Mature): ISARPs and/or operational processes are prioritized using a risk-based audit planning approach and high priority areas are audited at a frequency appropriate to the risk determined by the Operator.\nC8 (Mature): The quality assurance program is managed through an effective and user-friendly software and/or database.\nC9 (Leading): The Operator applies IOSA risk-based auditing techniques internally such as risk-based scoping, hybrid auditing, risk-based thinking and process-based auditing.\nC10 (Leading): The Operator goes beyond compliance-based auditing and conducts process-based audits in order to identify room for improvements in all operational areas.\nC11 (Leading): The Accountable Executive and Senior Management regularly and visibly endorse and promote the quality assurance program.\nC12 (Leading): The Operator regularly conducts internal maturity assessments of its safety management system and/or any safety critical operational areas.\nC13 (Leading): All mitigation actions are assessed to validate if they are implemented and effective.\nC14 (Leading): There is a quality assurance activity to assess risk mitigations being effectively implemented by external organisations.", zh: "运营人应制定质量保证方案，对运行和维修职能的管理体系进行审计，以确保组织：\n(i) 遵守适用法规和标准；\n(ii) 满足规定的运行需求；\n(iii) 识别需要改进的领域；\n(iv) 识别运行中的危险；\n(v) 评估安全风险控制的有效性。[SMS] [MA] (GM) ►\n\n注：如果质量保证审计职能由外部组织执行，运营人作为AOC持有人，应负责确保质量保证方案符合本条款的规范。\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估质量保证方案（重点：在组织/SMS中的角色/目的；审计方案范围/目标的定义；方案要素/持续审计管理系统/运行领域程序的描述）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 访谈质量保证方案经理\n▪ 访谈选定的运行经理（重点：与质量保证方案的接口）\n▪ 检查选定的审计报告（重点：审计范围/流程/组织接口）\n▪ 协调验证所有运行领域质量保证审计方案的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n审计、集团公司和质量保证的定义请参阅IRM。\n质量保证方案包括两个互补的功能：监控运营人对相关法规和标准的符合性，以及评估和持续改进运行安全绩效。这些功能是SMS框架中安全保证组成部分的要素。\n在某些组织中，质量保证方案可能有不同的名称（例如内部审计方案、内部评估方案）。\n在某些情况下，运营人可能由外部组织执行质量保证审计职能。这通常发生在运营人是集团公司中一个或多个其他组织的关联公司时。然而，运营人也可能选择简单地将质量保证审计职能外包给不属于或关联集团公司的合格外部服务提供商。在这两种情况下，运营人作为AOC持有人，对确保质量保证方案根据本标准规范满足其组织的需求负有最终责任。\n健全的质量保证方案确保审计范围涵盖组织中影响安全和/或安保方面运行质量的所有领域。运行职能包括飞行运行、运行控制/飞行签派、维修运行、客舱运行、地面操作和货运运行。\n本条款旨在允许质量保证方案实施的灵活性。运营人管理系统中方案的结构和组织，无论是集中式、非集中式还是两者的结合，由运营人根据其公司文化和监管环境自行决定。\n有效的审计方案包括：\n• 审计启动，包括范围和目标；\n• 规划和准备，包括审计计划和检查单制定；\n• 观察和收集证据以评估文件化和实施情况；\n• 分析、发现、行动；\n• 报告和审计总结；\n• 跟踪和关闭。\n为确保审计员在审计期间收集足够证据以产生真实的评估，方案通常包括定义审计员在审计证据收集阶段应使用的各种抽样技术的指导。\n审计过程通常包括一种方式，审计员和被审计区域的负责人员进行全面讨论，并就发现项和相应的纠正措施达成一致。建立明确的程序来解决审计员和被审计区域之间的任何分歧。所有行动项目都需要跟踪，以确保在适当的时间内关闭。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。\n\n评估工具\n预期结果：运营人的管理系统被监控并持续符合所有适用标准和法规。收集用于管理运行风险的相关数据并提供给相关领域。\n充分性考虑：• 质量保证方案的范围与运行类型、规模和复杂性相关。• 使用的工具和系统及其可用性。• 基于运营人复杂性的流程和程序复杂性。• 识别的不符合项和危险的数量和性质。\nC1（建立）：运营人分析审计结果、相关纠正措施和趋势，并在组织内共享。\nC2（建立）：内部审计与安全风险管理流程之间的接口被清晰描述并实施。\nC3（建立）：负责质量保证方案的经理直接向责任人报告，并定期进行有效更新。\nC4（建立）：负责质量保证方案的经理具有质量审计员的正式培训或认证、相关的运行和审计经验以及风险管理和安全保证方面的正式培训。\nC5（成熟）：运营人通过质量保证方案下进行的审计和/或安全审计有效识别危险。\nC6（成熟）：质量保证方案有效识别需要改进的领域，从而导致采取改进行动。\nC7（成熟）：使用基于风险的审计策划方法对ISARPs和/或运行流程进行优先级排序，高优先级区域以运营人确定的风险相适应的频率进行审计。\nC8（成熟）：质量保证方案通过有效且用户友好的软件和/或数据库进行管理。\nC9（领先）：运营人在内部应用IOSA基于风险的审计技术，例如基于风险的范围界定、混合审计、基于风险的思维和基于流程的审计。\nC10（领先）：运营人超越基于合规的审计，进行基于流程的审计，以识别所有运行领域的改进空间。\nC11（领先）：责任人和高级管理层定期、显著地认可和推广质量保证方案。\nC12（领先）：运营人定期对其安全管理体系和/或任何安全关键运行领域进行内部成熟度评估。\nC13（领先）：评估所有缓解措施以验证它们是否已实施且有效。\nC14（领先）：有质量保证活动来评估外部组织实施的风险缓解措施是否有效。" },
            { subtitle: "ORG 2.1.2 质量保证经理", eng: "The Operator shall appoint a manager with appropriate qualifications, authority and independence that is responsible for:\n(i) The performance of the quality assurance program;\n(ii) Ensuring communication and coordination with operational managers in the management of operational risk;\n(iii) Dissemination of information to management and non-management operational personnel as appropriate to ensure an organizational awareness of relevant quality assurance issues and results. (GM)\n\nNote: If the Operator outsources operational functions to an external service provider, the use of the external service provider's quality assurance program manager for the purpose of conforming to the specifications of this provision shall be considered a conflict of interest, unless the Operator and the external service provider are both affiliates within the same Group Company.\n\nAuditor Actions:\n▪ Identified quality assurance program manager.\n▪ Examined job description of quality assurance program manager (focus: qualifications/duties/ responsibilities).\n▪ Interviewed quality assurance program manager.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Quality Assurance Manager.\nThe designated manager (or multiple managers if an operator does not have a centralized program) is appointed to oversee the implementation of the activities and processes associated with the quality assurance program.\nThe exact title of the manager(s) designated as responsible for the quality assurance program may vary depending on the organization.\nOperational managers have direct responsibility for the safety and security of operations, and therefore always have the authority to develop and implement corrective action as necessary to address audit findings in their respective areas of operations.\nThe manager of the quality assurance program is \"operationally independent\" in a manner that ensures objectivity is not subject to bias due to conflicting responsibilities.\nTo be effective, an individual designated as manager of the quality assurance program has appropriate qualifications for the position, which may include:\n• Formal training or certification as a quality auditor;\n• Relevant operational and auditing experience;\n• Formal training in risk management.\nQuality assurance audit activities may be centrally controlled or controlled within each relevant operational function as long as independence is maintained. Typically, the manager of the quality assurance program has direct lines of communication to senior management to ensure the efficient reporting of safety and security issues, and to ensure such issues are appropriately addressed.\nAn effective quality assurance program includes the dissemination of appropriate information for the purpose of maintaining an ongoing awareness of quality assurance results that might affect compliance, operational safety or security or identify opportunities for improvement. As an example, such information might include a summary of audit program results such as finding, causation, risk, error trends and opportunities for continuous improvement.\nThe method of dissemination is commensurate with the target audience and the size of the organization. Typical means could include periodic briefings or presentations, or the issuance of magazines, newsletters or bulletins in either an electronic or paper form.\nIn certain circumstances, an operator may have the quality assurance audit function performed by an external organization (see guidance for ORG 2.1.1). in such cases, the operator will still ensure its quality assurance program has a manager in accordance with the specifications of this standard.", zh: "运营人应任命一名具有适当资格、权限和独立性的经理，负责：\n(i) 质量保证方案的执行；\n(ii) 确保在运行风险管理中与运行经理的沟通和协调；\n(iii) 酌情向管理和非管理运行人员传播信息，以确保组织了解相关的质量保证问题和结果。(GM)\n\n注：如果运营人将运行职能外委给外部服务提供商，为了符合本条款规范而使用外部服务提供商的质量保证方案经理应被视为利益冲突，除非运营人和外部服务提供商是同一集团公司内的关联公司。\n\n审计员行动：\n▪ 识别质量保证方案经理\n▪ 检查质量保证方案经理的职位描述（重点：资格/职责/责任）\n▪ 访谈质量保证方案经理\n▪ 其他行动（请说明）\n\n指导材料：\n质量保证经理的定义请参阅IRM。\n指定经理（如果运营人没有集中式方案，则可能是多名经理）被任命监督与质量保证方案相关的活动和流程的实施。\n被指定负责质量保证方案的经理的确切头衔可能因组织而异。\n运行经理对运行的安全和安保负有直接责任，因此始终有权制定和实施必要的纠正措施，以解决各自运行领域中的审计发现项。\n质量保证方案的经理以\"运行独立\"的方式确保客观性不会因职责冲突而产生偏见。\n为了有效，被指定为质量保证方案经理的个人应具备适合该职位的资格，其中可能包括：\n• 正式的质量审计员培训或认证；\n• 相关的运行和审计经验；\n• 风险管理方面的正式培训。\n质量保证审计活动可以集中控制，也可以在保持独立性的前提下在每个相关运行职能内控制。通常，质量保证方案经理与高级管理层有直接的沟通渠道，以确保高效报告安全和安保问题，并确保此类问题得到适当解决。\n有效的质量保证方案包括传播适当信息，以保持对可能影响合规性、运行安全或安保或识别改进机会的质量保证结果的持续意识。例如，此类信息可能包括审计方案结果的摘要，如发现项、原因、风险、错误趋势和持续改进的机会。\n传播方式与目标受众和组织规模相称。典型方式可能包括定期简报或演示，或以电子或纸质形式发布杂志、通讯或公告。\n在某些情况下，运营人可能由外部组织执行质量保证审计职能（见ORG 2.1.1的指导）。在这种情况下，运营人仍将确保其质量保证方案有一名符合本标准规范的经理。" },
            { subtitle: "ORG 2.1.3", eng: "(Intentionally open)", zh: "（有意留空）" },
            { subtitle: "ORG 2.1.4 ISARPs审计", eng: "If the Operator is on the IOSA Registry, the Operator shall ensure the quality assurance program as specified in ORG 2.1.1 provides for the auditing of the IOSA Standards and Recommended Practices (ISARPs) a minimum of once during the IOSA registration period. For internal audits of the ISARPs, the Operator shall have processes that ensure:\n(i) The effective edition of the IOSA Standards Manual (ISM) is used;\n(ii) Auditor Actions are accomplished by auditors;\n(iii) Recording and retention of information associated with the internal audit of individual ISARPs as specified in Table 1.2. (GM)\n\nNote: If a new edition of the ISM becomes effective before the last 6 months of the Operator's IOSA registration period, the Operator shall take into account all changes that might require additional auditing (e.g. new or significantly revised ISARPs).\n\nAuditor Actions:\n▪ Identified/Assessed processes that ensure auditing of all ISARPs during the IOSA registration period.\n▪ Identified/Assessed internal audit processes/procedures (focus: use of effective ISM edition; auditors accomplish Auditor Actions).\n▪ Interviewed quality assurance program manager.\n▪ Interviewed selected internal auditors.\n▪ Examined selected records (database, procedural documents) of audits performed against ISARPs (focus: effective ISM edition used, all specified information-Confirmed implementation of AAs).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Auditor Actions, IOSA Operator, IOSA Registration Period and Registration Renewal Audit.\nThe currently effective edition of the ISM is used for auditing of the ISARPs during the first 18 months of the IOSA registration period. Use of an ISM edition that becomes effective in the final six (6) months of the operator's registration period is optional.\nThe accomplishment of Auditor Actions as specified in item (ii) is necessary to ensure internal auditors gather the necessary evidence to determine whether (or not) a standard or recommended practice is documented and implemented by the operator.\nTable 1.2, as specified in item (iii), includes a note that refers to procedural documents. An example of a procedural document is an audit checklist in which all specified audit information associated with the audit of the individual ISARPs is recorded.\nIATA continues to provide a template in the form of a spreadsheet to record all required information as specified in ORG 2.1.4 and Table 1.2.\nTo the extent possible, auditing of the ISARPs should be spread out over the full registration period rather than waiting to conduct all auditing just prior to the registration renewal audit.\nRefer to the IAH for information relevant to auditing of the ISARPs under the quality assurance program.", zh: "如果运营人在IOSA登记册上，运营人应确保ORG 2.1.1中规定的质量保证方案在IOSA注册期内至少对IOSA标准和推荐实践（ISARP）进行一次审计。对于ISARPs的内部审计，运营人应制定流程确保：\n(i) 使用有效版本的IOSA标准手册（ISM）；\n(ii) 审计员完成审计员行动；\n(iii) 按照表1.2的规定记录和保留与单个ISARPs内部审计相关的信息。(GM)\n\n注：如果在运营人IOSA注册期最后6个月之前有新版本ISM生效，运营人应考虑所有可能需要额外审计的变更（例如新的或重大修订的ISARPs）。\n\n审计员行动：\n▪ 识别/评估确保在IOSA注册期内审计所有ISARPs的流程\n▪ 识别/评估内部审计流程/程序（重点：使用有效ISM版本；审计员完成审计员行动）\n▪ 访谈质量保证方案经理\n▪ 访谈选定的内部审计员\n▪ 检查选定的针对ISARPs审计的记录（数据库、程序文件）（重点：使用有效ISM版本，包含所有指定信息，确认AA的实施）\n▪ 其他行动（请说明）\n\n指导材料：\n审计员行动、IOSA运营人、IOSA注册期和换证注册审计的定义请参阅IRM。\n在IOSA注册期的前18个月内，使用当前有效版本的ISM进行ISARPs审计。在运营人注册期最后六（6）个月内生效的ISM版本的使用是可选的。\n第(ii)项中规定的完成审计员行动对于确保内部审计员收集必要证据以确定标准或推荐实践是否由运营人文件化和实施是必要的。\n第(iii)项中规定的表1.2包含一个指向程序文件的注释。程序文件的一个示例是审计检查单，其中记录了与单个ISARPs审计相关的所有指定审计信息。\nIATA继续以电子表格形式提供模板，用于记录ORG 2.1.4和表1.2中规定的所有必需信息。\n尽可能将ISARPs的审计分散在整个注册期内，而不是等到换证注册审计之前才进行所有审计。\n关于质量保证方案下ISARPs审计的相关信息，请参阅IAH。" },
            { subtitle: "ORG 2.1.5 审计排程", eng: "The Operator shall have an audit planning process and sufficient resources to ensure audits are:\n(i) Scheduled at intervals to meet regulatory and management system requirements;\n(ii) Conducted within the scheduled interval. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed quality assurance audit planning process (focus: audits planned/scheduled/conducted in accordance with applicable internal/external requirements).\n▪ Identified/Assessed audit resources (focus: availability of sufficient (auditors/other resources to accomplish audit plan).\n▪ Interviewed quality assurance program manager.\n▪ Crosschecked audit plan with selected audit reports (focus: audits conducted in accordance with audit plan).\n▪ Coordinated to verify implementation of audit plan in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nThe planning process produces a schedule of the audit modules to be conducted within the planning period (e.g. calendar year) and reflect the status of each audit module, to include the applicable audit interval (e.g. 12, 24, 36 months), the date of the previous audit and the scheduled due date for the next audit.\nThe planning process would typically include provisions for re-scheduling or deferral of audits in accordance with the operator's program limitations.\nRefer to the IAH for information relevant to planning associated with auditing of the ISARPs.", zh: "运营人应制定审计策划流程并提供足够资源，以确保审计：\n(i) 按照满足法规和系统要求的间隔进行排程；\n(ii) 在规定的时间间隔内进行。(GM) ►\n\n审计员行动：\n▪ 识别/评估质量保证审计策划流程（重点：审计按照适用内部/外部要求进行策划/排程/实施）\n▪ 识别/评估审计资源（重点：是否有足够的（审计员/其他资源）来完成审计计划）\n▪ 访谈质量保证方案经理\n▪ 将审计计划与选定的审计报告进行交叉检查（重点：审计按照审计计划进行）\n▪ 协调验证所有运行领域审计计划的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n策划流程产生在策划期内（例如日历年）要进行的审计模块的时间表，并反映每个审计模块的状态，包括适用的审计间隔（例如12、24、36个月）、上次审计日期和下次审计的计划到期日。\n策划流程通常包括根据运营人方案限制重新排程或推迟审计的规定。\n关于与ISARPs审计相关的策划信息，请参阅IAH。" },
            { subtitle: "ORG 2.1.6 审计策划", eng: "The Operator shall ensure the audit planning process defines the scope of each audit, as appropriate for the area being audited, and also:\n(i) Includes audit objectives that address ongoing compliance with regulatory requirements, Operator standards and other applicable regulations, rules and standards;\n(ii) Considers relevant operational safety or security events that have occurred;\n(iii) Considers results from previous audits, including the effectiveness of corrective action that has been implemented. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed quality assurance audit planning process (focus: audits planned/scheduled/completed in order to meet applicable internal/external requirements).\n▪ Interviewed quality assurance program manager.\n▪ Examined selected audit plans (focus: audit scope/objectives defined; operational events/previous audits considered).\n▪ Crosschecked audit plan with selected audit reports (focus: audits conducted in accordance with audit plan).\n▪ Other Actions (Specify)\n\nGuidance:\nThe audit scope refers to the breadth of operational disciplines or operational areas covered by an audit and therefore will vary depending on the focus area for each audit (e.g. flight dispatch function, dangerous goods handling, ramp handling operations, line maintenance activities).\nAudit objectives define tangible achievements expected to result from an audit, normally expressed as a statement of intent (e.g. to determine compliance with regulatory requirements, to establish conformity with operator standards, to assess conformity with IOSA standards, to determine efficiency of operations).\nTo be effective, auditors prepare for an audit of a particular area of operations by:\n• Conducting research into any relevant incidents or irregularities that may have occurred;\n• Reviewing reports from previous audits.\nRefer to the IAH for information relevant to planning associated with auditing of the ISARPs.", zh: "运营人应确保审计策划流程定义每次审计的范围（适合被审计的领域），并且：\n(i) 包括处理持续遵守法规要求、运营人标准和其他适用法规、规则和标准的审计目标；\n(ii) 考虑已发生的相关运行安全或安保事件；\n(iii) 考虑以前审计的结果，包括已实施纠正措施的有效性。(GM)\n\n审计员行动：\n▪ 识别/评估质量保证审计策划流程（重点：审计按照适用内部/外部要求进行策划/排程/完成）\n▪ 访谈质量保证方案经理\n▪ 检查选定的审计计划（重点：定义了审计范围/目标；考虑了运行事件/以前的审计）\n▪ 将审计计划与选定的审计报告进行交叉检查（重点：审计按照审计计划进行）\n▪ 其他行动（请说明）\n\n指导材料：\n审计范围指审计涵盖的运行学科或运行领域的广度，因此根据每次审计的重点领域而有所不同（例如飞行签派职能、危险品处理、机坪操作、航线维修活动）。\n审计目标定义了审计预期产生的有形成果，通常以意图声明的方式表达（例如确定是否符合法规要求、确定是否符合运营人标准、评估是否符合IOSA标准、确定运行效率）。\n为了有效，审计员通过对特定运行领域进行审计准备：\n• 对可能发生的任何相关事件或不规范情况进行研究；\n• 审查以前审计的报告。\n关于与ISARPs审计相关的策划信息，请参阅IAH。" },
            { subtitle: "ORG 2.1.7 处理发现项", eng: "The Operator shall have a process for addressing findings that result from audits conducted under the quality assurance program, which ensures:\n(i) Identification of root cause(s);\n(ii) Development of corrective action as appropriate to address findings;\n(iii) Implementation of corrective action in appropriate operational area(s);\n(iv) Evaluation of corrective action to determine effectiveness. [MA] (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed process for addressing quality assurance audit findings.\n▪ Interviewed quality assurance program manager.\n▪ Examined selected audit reports/records (focus: identification of root cause, development/implementation of corrective action, follow-up to ensure effectiveness).\n▪ Coordinated to verify implementation of audit findings process in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nCertain audit findings might fall under the category of hazards to operations. In such cases, the hazard would be subject to the risk assessment and mitigation process in the development of corrective action.\nRefer to the IAH for information relevant to auditing under the quality assurance program.\n\nAssessment Tool\nDesired Outcome: Non-conformities resulting from audits are corrected in a timely manner and root causes for these non-conformities are appropriately addressed to avoid recurrence.\nSuitability Considerations: • Scope of the process relevant to type, size, and complexity of operations • Complexity of processes and procedures\nC1 (Established): Corrective actions have clear responsibility, deadlines and are effectively implemented within the prescribed timelines.\nC2 (Established): The corrective action process is tracked and managed using an effective and user-friendly software and/or database.\nC3 (Established): The Accountable Executive and Senior Management are aware of the status of significant findings and related corrective actions.\nC4 (Established): Findings raised by the Operator are not a verbatim copy of the standard. They are described in a clear and concise manner, to include declaration of the nonconformity, deviation from the requirements and reference to the audit evidence.\nC5 (Mature): Corrective action responsibility resides within operational departments and all actions are performed by operational managers and/or personnel with necessary expertise and operational experience.\nC6 (Mature): Corrective actions effectively address the root causes and/or contributing factors.\nC7 (Mature): Personnel performing root cause analysis are comprehensively trained in root cause analysis techniques.\nC8 (Mature): The applied root cause analysis techniques are commensurate to the complexity and the nature of the non-conformity.\nC9 (Mature): The Operator evaluates remarks, opportunities for improvement and/or recommendations made during internal and/or external audits to include the IOSA Audits and take actions on at least some of them.\nC10 (Leading): Recurring findings are identified and evaluated. Effective actions are implemented to prevent recurrence.\nC11 (Leading): Findings and corrective actions are systematically analyzed for cross-fleet and cross-discipline relevance.\nC12 (Leading): The Operator evaluates remarks, opportunities and/or recommendations raised during internal and/or external audits to include the IOSA Audits and takes actions on the majority of them.\nC13 (Leading): All identified root causes and/or contributing factors are identified as a potential hazard and, if applicable, are subject to the risk assessment and mitigation process in the development of corrective action(s).\nC14 (Leading): The Operator has a risk-based audit follow up process, to include risk-based root cause analysis, corrective/preventive action and verification of implementation.\nC15 (Leading): Majority of corrective and preventive actions implemented by the Operator focus and ensure process improvement.", zh: "运营人应制定处理质量保证方案下审计产生的发现项的流程，确保：\n(i) 识别根本原因；\n(ii) 制定适当的纠正措施以处理发现项；\n(iii) 在适当的运行领域实施纠正措施；\n(iv) 评估纠正措施以确定有效性。[MA] (GM) ►\n\n审计员行动：\n▪ 识别/评估处理质量保证审计发现项的流程\n▪ 访谈质量保证方案经理\n▪ 检查选定的审计报告/记录（重点：识别根本原因、制定/实施纠正措施、跟踪以确保有效性）\n▪ 协调验证所有运行领域审计发现项流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n某些审计发现项可能属于运行危险的类别。在这种情况下，危险将受到风险评估和缓解流程的约束，以制定纠正措施。\n关于质量保证方案下审计的相关信息，请参阅IAH。\n\n评估工具\n预期结果：审计产生的不符合项得到及时纠正，并适当处理这些不符合项的根本原因以避免再次发生。\n充分性考虑：• 流程范围与运行类型、规模和复杂性相关 • 流程和程序的复杂性\nC1（建立）：纠正措施有明确的责任人、截止日期，并在规定的时间表内有效实施。\nC2（建立）：使用有效且用户友好的软件和/或数据库跟踪和管理纠正措施流程。\nC3（建立）：责任人和高级管理层了解重大发现项和相关纠正措施的状态。\nC4（建立）：运营人提出的发现项不是标准的逐字复制。它们以清晰简洁的方式描述，包括不符合项的声明、与要求的偏差以及审计证据的引用。\nC5（成熟）：纠正措施的责任在运行部门内部，所有行动由运行经理和/或具有必要专业知识和运行经验的人员执行。\nC6（成熟）：纠正措施有效解决根本原因和/或促成因素。\nC7（成熟）：执行根本原因分析的人员接受了根本原因分析技术的全面培训。\nC8（成熟）：所应用的根本原因分析技术与不符合项的复杂性和性质相称。\nC9（成熟）：运营人评估内部和/或外部审计（包括IOSA审计）期间提出的意见、改进机会和/或建议，并至少对其中的一些采取行动。\nC10（领先）：识别和评估重复发现项。实施有效措施以防止再次发生。\nC11（领先）：系统分析发现项和纠正措施的跨机队和跨学科相关性。\nC12（领先）：运营人评估内部和/或外部审计（包括IOSA审计）期间提出的意见、机会和/或建议，并对其中的大多数采取行动。\nC13（领先）：所有已识别的根本原因和/或促成因素被识别为潜在危险，并在适用情况下在制定纠正措施时接受风险评估和缓解流程。\nC14（领先）：运营人拥有基于风险的审计跟踪流程，包括基于风险的根本原因分析、纠正/预防措施和实施验证。\nC15（领先）：运营人实施的大多数纠正和预防措施侧重于并确保流程改进。" },
            { subtitle: "ORG 2.1.8 审计员独立性", eng: "The Operator shall ensure the quality assurance program uses auditors that are impartial and functionally independent from the operational activities to be audited. (GM)\n\nNote: If the Operator outsources operational functions to an external service provider and uses auditing as the process to monitor the external service provider as specified in ORG 2.2.1 and 2.2.2, the use of the external service provider's auditors to perform such auditing shall be considered a conflict of interest, unless the Operator and the external service provider are both affiliates within the same Group Company.\n\nAuditor Actions:\n▪ Identified/Assessed quality assurance auditor administration program (focus: definition of impartial/functionally independent as applied to quality assurance program auditors; policies/procedures in place that ensure auditor impartiality/functional independence).\n▪ Interviewed quality assurance program manager (focus: application or policies/procedures that ensure auditor impartiality/functional independence).\n▪ Interviewed selected quality assurance auditors (focus: verification of functional independence during assigned audit activities).\n▪ Crosschecked selected audit reports (focus: auditors are functionally independent from the activities audited).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Group Company.\nA quality assurance program is independent in a manner that permits the scheduling and conduct of audits as deemed appropriate for the size and scope of operations. Functional independence ensures auditors are not put in a position where their objectivity may be subject to bias due to conflicting responsibilities.\nA code of conduct may be used to enhance the impartiality and independence of auditors. An effective auditor code of ethics would require auditors:\n• To act in a strictly trustworthy and unbiased manner in relation to both the organization to which they are employed, contracted or otherwise formally engaged and any other organization involved in an audit performed by them or by personnel under their direct control;\n• To disclose to their employer any relationship they may have with the organization to be audited before undertaking any audit function in respect of that organization;\n• Not to accept any gift, commission, discount or any other profit from the organization audited, from their representatives, or from any other interested person nor knowingly allow personnel for whom they are responsible to do so;\n• Not to disclose the findings, or any part of them, nor to disclose any other information gained in the course of the audit to any third party, unless authorized in writing by both the auditee and the audit organization, if applicable;\n• Not to act in any way prejudicial to the reputation or interest of the audit organization; and\n• In the event of any alleged breach of this code, to co-operate fully in any formal enquiry procedure.\nAn auditor may be considered functionally independent from the operational activities to be audited, when he/she is not responsible for the activity being audited (at the time of the audit). For example, a flight crew member may audit line flight operations from the flight deck jump seat as an independent observer (supernumerary) but may not do so when functioning as part of the operating crew (or functioning as an augmenting crew member).\nRefer to the IAH for information relevant to auditor qualification and independence.", zh: "运营人应确保质量保证方案使用的审计员公正且职能上独立于被审计的运行活动。(GM)\n\n注：如果运营人将运行职能外委给外部服务提供商，并使用审计作为监控外部服务提供商的流程（如ORG 2.2.1和2.2.2所述），使用外部服务提供商的审计员执行此类审计应被视为利益冲突，除非运营人和外部服务提供商是同一集团公司内的关联公司。\n\n审计员行动：\n▪ 识别/评估质量保证审计员管理方案（重点：适用于质量保证方案审计员的公正/职能独立的定义；确保审计员公正/职能独立的政策/程序）\n▪ 访谈质量保证方案经理（重点：确保审计员公正/职能独立的政策/程序的应用）\n▪ 访谈选定的质量保证审计员（重点：验证在分配审计活动期间的职能独立性）\n▪ 交叉检查选定的审计报告（重点：审计员职能上独立于被审计的活动）\n▪ 其他行动（请说明）\n\n指导材料：\n集团公司的定义请参阅IRM。\n质量保证方案以独立的方式允许根据运行的规模和范围认为合适的方式安排和进行审计。职能独立性确保审计员不会处于其客观性可能因职责冲突而产生偏见的位置。\n行为准则可用于增强审计员的公正性和独立性。有效的审计员道德准则要求审计员：\n• 以严格值得信赖和公正的方式对待他们受雇、签约或以其他方式正式参与的组织，以及任何其他参与他们或其直接控制下的人员进行的审计的组织；\n• 在就该组织承担任何审计职能之前，向其雇主披露他们可能与被审计组织有任何关系；\n• 不接受被审计组织、其代表或任何其他相关人士的任何礼物、佣金、折扣或任何其他利润，也不故意允许对其负责的人员这样做；\n• 不向任何第三方披露发现项或其任何部分，也不披露审计过程中获得的任何其他信息，除非获得被审计方和审计机构（如适用）的书面授权；\n• 不以任何方式损害审计机构的声誉或利益；以及\n• 如果发生任何涉嫌违反本准则的行为，在任何正式调查程序中充分合作。\n当审计员（在审计时）不对被审计的活动负责时，可被视为职能上独立于被审计的运行活动。例如，飞行机组成员可以作为独立观察员从驾驶舱折叠座椅审计航线飞行运行，但在作为运行机组成员的一部分（或作为增补机组成员）时则不能这样做。\n关于审计员资格和独立性的相关信息，请参阅IAH。" },
            { subtitle: "ORG 2.1.9 审计员培训与资格", eng: "The Operator shall have a training and qualification program that ensures auditors that conduct auditing under the quality assurance program as specified in ORG 2.1.1:\n(i) Have the knowledge, skills and work experience needed to effectively assess areas of the management system and operations that will be audited;\n(ii) Maintain an appropriate level of current audit experience;\n(iii) Complete initial and continuing auditor training that provides the knowledge and understanding necessary to effectively conduct audits against:\n(a) Applicable regulations and standards;\n(b) If the Operator is currently on the IOSA Registry, the ISARPs.\n(iv) Are evaluated on a periodic basis. [MA] (GM)\n\nNote: Sub-specification (iii) (b) is applicable only to auditors that may be assigned to conduct internal auditing against the ISARPs.\n\nAuditor Actions:\n▪ Identified/Assessed auditor training and qualification program.\n▪ Interviewed quality assurance program manager.\n▪ Examined selected individual auditor records (focus: completion of initial/continuing qualification/periodic evaluations, in accordance with program standards).\n▪ Interviewed selected quality assurance auditors (focus: verification of initial/continuing qualifications).\n▪ Crosschecked selected audit reports/records (focus: currency of auditors).\n▪ Other Actions (Specify)\n\nGuidance:\nThe intent of this provision is for the operator to have a program that ensures all auditors that conduct auditing under its quality assurance program, including internal auditor personnel (e.g. employees) or external auditor personnel (e.g. consultants), are trained, evaluated and qualified in accordance with the criteria specified in this standard.\nThe delivery of auditor training and evaluation under the operator's program may be accomplished by the operator or by an external party (or a combination of both) as long as all auditors that conduct auditing under the operator's quality assurance program are trained, evaluated and qualified in accordance with the criteria specified in this standard.\nInternationally recognized standards published in ISO 19011 provide a reliable guide for the training and/or certification of auditors used in the quality assurance program.\nWhile the frequency of recurrent trainings and evaluations are at the discretion of the operator, an ideal minimum frequency of both of these activities is considered to be 24 months, to ensure the overall reliability of the audits conducted under the quality assurance program.\nFor all auditors that conduct auditing of the management system, and of operations and maintenance functions for the operator under its quality assurance program as specified in ORG 2.1.1, training and qualification typically addresses the following subject areas:\n• Application of audit principles, procedures and techniques;\n• Planning and organizing work effectively;\n• Conducting the audit within the agreed timescale;\n• Prioritizing and focusing on matters of significance;\n• Collecting information (i.e. audit evidence) through effective interviewing, listening, observing and examination of documents, records and data;\n• Understanding the appropriateness and consequences of using sampling techniques for auditing;\n• Verifying the accuracy of collected information;\n• Confirming the sufficiency and appropriateness of audit evidence to support audit findings and conclusions;\n• Assessing those factors that can affect the reliability of the audit findings and conclusions;\n• Using work documents to record audit activities;\n• Preparing audit reports;\n• Maintaining the confidentiality and security of information;\n• Communicating effectively, either through personal linguistic skills or through an interpreter.\nFor those auditors assigned to conduct auditing against the ISARPs as specified in ORG 2.1.4, training and qualification typically addresses the following additional subject areas:\n• IOSA program overview;\n• IOSA documentation;\n• Understanding the role of the ICAO annexes as the primary source of specifications contained in the ISARPs;\n• Reading and understanding the ISARPs;\n• IOSA quality assurance requirements (ORG subsection 2.1);\n• Auditor Actions;\n• Mandatory observations;\n• Root cause analysis;\n• Auditing ORG and repeated ORG ISARPs;\n• Auditing SMS;\n• Auditing quality assurance;\n• Assessing outsourced operational functions.\nRefer to the IAH for information relevant to the training and qualification of auditors that assess conformity with the ISARPs.\n\nAssessment Tool\nDesired Outcome: Audits are conducted by appropriately qualified and proficient auditors resulting in reliable audit results.\nSuitability Considerations: • Scope of the auditor training based on the complexity of the QAP. • Auditor qualification and experience level based on the complexity of the QAP.\nC1 (Established): The initial and recurrent auditor training contents and materials are regularly reviewed and updated.\nC2 (Established): The initial and recurrent auditor trainings take into consideration the Operator's profile and operational environment.\nC3 (Established): Auditor competency is assessed on a periodic basis while an auditor is actively auditing. The assessment is based on described criteria related to the knowledge, soft and technical auditing skills.\nC4 (Established): Auditors are trained in auditing safety and security management systems, as applicable.\nC5 (Mature): All auditors complete a minimum of 5 days basic auditor initial training such as a basic Aviation Internal Auditor training course.\nC6 (Mature): All auditors assigned to conduct auditing against the ISARPs complete a minimum five-day training on auditing IOSA requirements, such as the IATA IOSA Airline Auditor Training or equivalent.\nC7 (Mature): Internal auditor trainings are conducted in an interactive manner with ample use of practical exercises, real-life scenarios and/or audit simulations.\nC8 (Mature): All auditor trainings are delivered by experienced instructors and/or instructors with recent audit experience and/or recognized institutions.\nC9 (Mature): Auditor competency is assessed at least annually while an auditor is actively auditing and the assessment is based on defined criteria related to the knowledge, soft and technical auditing skills.\nC10 (Leading): All auditors assigned to conduct auditing against the ISARPs meet IOSA Program Manual (IPM) auditor prerequisites, operational experience, certification & training and audit experience.\nC11 (Leading): The auditor training program is performance/evidence based, and relevant trainings are conducted at least annually.\nC12 (Leading): Latest auditing methodologies and lessons learned from previous audits are incorporated in internal auditor trainings.\nC13 (Leading): The Operator educates auditors not only through regular formal trainings, but also through participation in conferences and/or industry initiatives.\nC14 (Leading): Auditors are trained in understanding use of new technologies in operational areas such as artificial intelligence, data management, etc.", zh: "运营人应制定培训与资格方案，确保根据ORG 2.1.1在质量保证方案下进行审计的审计员：\n(i) 具备有效评估将被审计的管理系统和运行领域的知识、技能和工作经验；\n(ii) 保持适当水平的当前审计经验；\n(iii) 完成初始和持续审计员培训，获得有效进行以下方面审计所需的知识和理解：\n(a) 适用法规和标准；\n(b) 如果运营人目前在IOSA登记册上，则包括ISARPs。\n(iv) 定期接受评估。[MA] (GM)\n\n注：子规范(iii)(b)仅适用于可能被分配进行ISARPs内部审计的审计员。\n\n审计员行动：\n▪ 识别/评估审计员培训与资格方案\n▪ 访谈质量保证方案经理\n▪ 检查选定的个人审计员记录（重点：根据方案标准完成初始/持续资格/定期评估）\n▪ 访谈选定的质量保证审计员（重点：验证初始/持续资格）\n▪ 交叉检查选定的审计报告/记录（重点：审计员的时效性）\n▪ 其他行动（请说明）\n\n指导材料：\n本条款的意图是让运营人有一个方案，确保所有在其质量保证方案下进行审计的审计员，包括内部审计员人员（例如雇员）或外部审计员人员（例如顾问），都根据本标准规定的标准进行培训、评估和资格认证。\n运营人方案下的审计员培训和评估可以由运营人或由外部方（或两者的组合）完成，只要在运营人质量保证方案下进行审计的所有审计员都根据本标准规定的标准进行培训、评估和资格认证。\nISO 19011中发布的国际认可标准为质量保证方案中使用的审计员的培训和/或认证提供了可靠的指导。\n虽然复训和评估的频率由运营人自行决定，但这两项活动的理想最低频率被认为是24个月，以确保在质量保证方案下进行的审计的整体可靠性。\n对于根据ORG 2.1.1在运营人质量保证方案下对管理系统、运行和维修职能进行审计的所有审计员，培训和资格通常涉及以下主题领域：\n• 审计原则、程序和技术的应用；\n• 有效策划和组织工作；\n• 在商定的时间内进行审计；\n• 优先处理并专注于重要事项；\n• 通过有效访谈、倾听、观察和检查文件、记录和数据收集信息（即审计证据）；\n• 理解使用抽样技术进行审计的适当性和后果；\n• 验证收集信息的准确性；\n• 确认审计证据的充分性和适当性以支持审计发现和结论；\n• 评估可能影响审计发现和结论可靠性的因素；\n• 使用工作文件记录审计活动；\n• 准备审计报告；\n• 维护信息的机密性和安全性；\n• 通过个人语言技能或通过翻译有效沟通。\n对于根据ORG 2.1.4分配进行ISARPs审计的审计员，培训和资格通常涉及以下额外主题领域：\n• IOSA项目概述；\n• IOSA文件；\n• 理解ICAO附件作为ISARPs中规范主要来源的作用；\n• 阅读和理解ISARPs；\n• IOSA质量保证要求（ORG第2.1小节）；\n• 审计员行动；\n• 强制观察；\n• 根本原因分析；\n• 审计ORG和重复的ORG ISARPs；\n• 审计SMS；\n• 审计质量保证；\n• 评估外委运行职能。\n关于评估ISARPs符合性的审计员培训和资格的相关信息，请参阅IAH。\n\n评估工具\n预期结果：审计由具有适当资格和熟练程度的审计员进行，产生可靠的审计结果。\n充分性考虑：• 基于QAP复杂性的审计员培训范围。• 基于QAP复杂性的审计员资格和经验水平。\nC1（建立）：初始和复训审计员培训内容和材料定期审查和更新。\nC2（建立）：初始和复训审计员培训考虑运营人的概况和运行环境。\nC3（建立）：在审计员积极审计期间定期评估审计员能力。评估基于与知识、软技能和技术审计技能相关的描述标准。\nC4（建立）：审计员接受审计安全和安保管理体系的培训（如适用）。\nC5（成熟）：所有审计员完成至少5天的基本审计员初始培训，例如基础航空内部审计员培训课程。\nC6（成熟）：所有被分配进行ISARPs审计的审计员完成至少五天的审计IOSA要求培训，例如IATA IOSA航空公司审计员培训或同等培训。\nC7（成熟）：内部审计员培训以互动方式进行，大量使用实践练习、真实场景和/或审计模拟。\nC8（成熟）：所有审计员培训由经验丰富的讲师和/或具有近期审计经验和/或认可机构的讲师提供。\nC9（成熟）：在审计员积极审计期间至少每年评估一次审计员能力，评估基于与知识、软技能和技术审计技能相关的定义标准。\nC10（领先）：所有被分配进行ISARPs审计的审计员满足IOSA项目手册（IPM）审计员先决条件、运行经验、认证与培训以及审计经验。\nC11（领先）：审计员培训方案基于绩效/证据，相关培训至少每年进行一次。\nC12（领先）：最新的审计方法和从以前审计中吸取的经验教训纳入内部审计员培训。\nC13（领先）：运营人不仅通过定期正式培训教育审计员，还通过参与会议和/或行业倡议教育审计员。\nC14（领先）：审计员接受培训，理解运行领域中新技术的使用，例如人工智能、数据管理等。" }
        ]
    },

        external_monitoring: {
        title: "2.2 外部监控 - External Monitoring",
        sections: [
            { subtitle: "ORG 2.2.1 外委提供方的监控", eng: "The Operator shall have processes to monitor external service providers that conduct outsourced operational functions for the Operator to ensure requirements that affect the safety and/or security of operations are being fulfilled. [MA] (GM) ►\n\nNote: IOSA or ISAGO registration as the only means to monitor is acceptable provided the Operator obtains the latest of the applicable audit report(s) through official program channels and considers the content of such report(s).\n\nAuditor Actions:\n▪ Identified/Assessed processes for monitoring external service providers that conduct outsourced operational functions.\n▪ Interviewed responsible manager(s).\n▪ Examined selected records/reports resulting from monitoring of service providers (focus: monitoring process ensures provider is fulfilling applicable safety/security requirements).\n▪ Coordinated to verify implementation of service provider monitoring in applicable operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nAn operator has a responsibility to ensure outsourced operational functions are conducted in a manner that meets its own operational safety and security requirements. A monitoring process is necessary to satisfy that responsibility, and such process would be applicable to any external service provider that conducts outsourced operational functions, including the parent organization or a separate affiliate of the operator.\nIn some regulatory jurisdictions, there may be a regulatory control process that permits certain organizations to meet rigorous standards and become approved to conduct outsourced operations or maintenance for an operator. Such regulatory control process would be an acceptable means for meeting the specification of this provision if it can be demonstrated by the operator that the regulatory control process:\n• Includes ongoing monitoring of the approved service providers;\n• Such monitoring is sufficiently robust to ensure the approved service providers fulfill the operational requirements of the operator on a continuing basis.\nAchieving and maintaining IOSA and/or ISAGO registration is a way for an external service provider to demonstrate fulfillment of requirements that affect the safety and/or security of operations. Thus, an operator's process that requires such service providers to maintain IOSA and/or ISAGO registration would generally be acceptable as a method of monitoring.\nUsing the IOSA and/or ISAGO programs to satisfy the specifications in this provision would require that an operator has access, preferably unrestricted access, to all information and data provided by the respective registration programs. Such access would be subject to receiving the relevant authorizations for individual reports. This type of monitoring would include a regular review of the registry site(s) to identify any potential annotations or restrictions that might have been placed on an operator's or provider's registration.\nUsing IOSA and ISAGO as described would also require an operator to request relevant audit reports through proper and official program channels. For IOSA this would require requesting an IAR through IATA and for ISAGO it would require participation in the ISAGO program. A review of the information contained in the audit report(s) would ideally complement and/or supplement any additional monitoring measures an operator is applying to ensure the service provider is fulfilling all relevant requirements. For example, combining the information from the report(s) with a risk assessment would be one option to have acceptable assurance that all requirements are fulfilled.\nTo ensure effective monitoring, consideration is given to a range of internal and external methods for use in the oversight of external service providers. Methods might include auditing, systematic review and risk assessment of reported hazards and/or occurrences, monitoring of performance output (KPIs), reporting and governance processes; monitoring and analysis of targeted risk areas, as well as the establishment of an effective two-way communication link with the service provider.\nUnder certain circumstances, operational functions may be involuntarily removed from an operator and conducted by a governmental or quasi-governmental authority that is not under the control of the operator (e.g. passenger or baggage security screening at some airports). Under such circumstances, the operator would have a process to monitor output of the function being conducted by the authority to ascertain desired results are being achieved.\nIf an operator is part of a Group Company and has management and/or operational functions performed by an affiliate organization that is part of the same Group Company, an operator may demonstrate monitoring of the external organization by processes that ensure functions performed by the affiliate organization for the operator are:\n• Subjected to auditing under the quality assurance program of the affiliate organization;\n• Continually satisfying the needs of the operator.\n\nAssessment Tool\nDesired Outcome: All operational activities conducted by external service providers are performed based on the operator's standards and expectations, without the introduction of any unacceptable risks and any negative trends. Unacceptable performance is appropriately addressed.\nSuitability Considerations: • Scope of monitoring based on number of outsourced providers. • Tools and processes used in the monitoring. • Variety of monitoring methods.\nC1 (Established): External service provider monitoring results that include audit and inspections results and key performance indicator trends are analyzed by the Operator and shared within the organization.\nC2 (Established): Personnel involved in external service provider monitoring activities are appropriately trained and/or qualified for monitoring methods related to service provider monitoring.\nC3 (Established): Multiple monitoring methods are used depending on the size and complexity of operations conducted and/or service provided by external service providers.\nC4 (Mature): Monitoring methods used for external service providers are effectively implemented and Operator identifies findings, observations, mitigating actions and/or recommendations to include escalation system for sub-optimal performance.\nC5 (Mature): Operator organizes a risk-based approach to identify the methods and intervals to be used for monitoring external service providers.\nC6 (Mature): Key performance indicators (KPIs) identified for the external service provider performance monitoring are in alignment with Operator's safety objectives and/or Safety Performance Indicators (SPIs).\nC7 (Mature): External service provider monitoring is performed independently from the relevant operational area and operational managers.\nC8 (Mature): The Operator's monitoring process of external service providers includes the participation in one or more industry audit programs such as the ISAGO, IFQP or DAQCP Programs.\nC9 (Leading): External service provider safety and security performance are continuously monitored, and trends and results are analyzed at least on a yearly basis for at least two operational areas.\nC10 (Leading): External service providers are monitored through a performance-based monitoring system based on reliable key performance measures/indicators.\nC11 (Leading): The Operator's monitoring process of external service providers includes the participation in all following industry audit programs: ISAGO, IFQP and DAQCP Programs, as applicable.\nC12 (Leading): A risk assessment is performed in case of sub-optimal performance of a single external service provider (monopoly) and mitigating actions are applied as required.\nC13 (Leading): External service provider performance is measured continuously for all operational areas and results are analysed at least annually.\nC14 (Leading): All key performance indicators used for monitoring external service providers are SMART (Specific, measurable, achievable, relevant and timebound).", zh: "运营人应建立流程监控执行外委运行职能的外部服务提供商，以确保影响运行安全和/或安保的要求得到满足。[MA] (GM) ►\n\n注：仅将IOSA或ISAGO注册作为监控手段是可接受的，前提是运营人通过官方项目渠道获取适用审计报告的最新版本并考虑此类报告的内容。\n\n审计员行动：\n▪ 识别/评估监控执行外委运行职能的外部服务提供商的流程\n▪ 访谈负责经理\n▪ 检查选定的服务提供商监控产生的记录/报告（重点：监控流程确保提供商履行适用的安全/安保要求）\n▪ 协调验证适用运行领域服务提供商监控流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n运营人有责任确保外委运行职能以符合其自身运行安全和安保要求的方式进行。监控流程对于履行该责任是必要的，并且此类流程适用于执行外委运行职能的任何外部服务提供商，包括运营人的母公司或单独的关联公司。\n在某些监管管辖区，可能存在监管控制流程，允许某些组织满足严格标准并获得批准为运营人执行外委运行或维修。如果运营人能够证明监管控制流程满足以下条件，则此类监管控制流程将是满足本条款规范的可接受方式：\n• 包括对批准的服务提供商进行持续监控；\n• 此类监控足够稳健，以确保批准的服务提供商持续满足运营人的运行要求。\n获得并维持IOSA和/或ISAGO注册是外部服务提供商证明满足影响运行安全和/或安保要求的一种方式。因此，要求此类服务提供商维持IOSA和/或ISAGO注册的运营人流程通常可作为监控方法被接受。\n使用IOSA和/或ISAGO项目来满足本条款中的规范将要求运营人能够访问（最好是无限制访问）各自注册项目提供的所有信息和数据。此类访问将取决于收到单个报告的相关授权。这种类型的监控将包括定期审查注册网站，以识别可能已对运营人或提供商的注册施加的任何潜在注释或限制。\n如上所述使用IOSA和ISAGO还将要求运营人通过适当和官方的项目渠道请求相关审计报告。对于IOSA，这需要通过IATA请求IAR；对于ISAGO，这需要参与ISAGO项目。对审计报告中包含的信息进行审查将理想地补充和/或增补运营人为确保服务提供商满足所有相关要求而应用的任何额外监控措施。例如，将报告中的信息与风险评估相结合是获得所有要求都得到满足的可接受保证的一种选择。\n为确保有效监控，考虑使用一系列内部和外部方法来监督外部服务提供商。方法可能包括审计、对报告的危险和/或事件进行系统审查和风险评估、监控绩效输出（KPI）、报告和治理流程；监控和分析目标风险领域，以及与服务提供商建立有效的双向沟通链接。\n在某些情况下，运行职能可能非自愿地从运营人处移除，并由不受运营人控制的政府或准政府当局执行（例如某些机场的旅客或行李安保检查）。在这种情况下，运营人应有一个流程来监控当局执行的职能的输出，以确定是否达到预期结果。\n如果运营人是集团公司的一部分，并且管理和/或运行职能由属于同一集团公司的关联组织执行，运营人可以通过确保关联组织为运营人执行的职能满足以下条件的流程来证明对外部组织的监控：\n• 接受关联组织质量保证方案下的审计；\n• 持续满足运营人的需求。\n\n评估工具\n预期结果：外部服务提供商执行的所有运行活动均基于运营人的标准和期望进行，不会引入任何不可接受的风险和任何负面趋势。不可接受的绩效得到适当处理。\n充分性考虑：• 基于外包提供商数量的监控范围。• 监控中使用的工具和流程。• 监控方法的多样性。\nC1（建立）：运营人分析外部服务提供商监控结果（包括审计和检查结果以及关键绩效指标趋势），并在组织内共享。\nC2（建立）：参与外部服务提供商监控活动的人员已接受与服务提供商监控相关的监控方法的适当培训和/或资格认证。\nC3（建立）：根据外部服务提供商执行的运行的规模和复杂性以及/或提供的服务，使用多种监控方法。\nC4（成熟）：用于外部服务提供商的监控方法得到有效实施，运营人识别发现项、观察项、缓解措施和/或建议，包括针对次优绩效的升级系统。\nC5（成熟）：运营人组织基于风险的方法来识别用于监控外部服务提供商的方法和间隔。\nC6（成熟）：为外部服务提供商绩效监控确定的关键绩效指标（KPI）与运营人的安全目标和/或安全绩效指标（SPI）保持一致。\nC7（成熟）：外部服务提供商监控独立于相关运行领域和运行经理执行。\nC8（成熟）：运营人的外部服务提供商监控流程包括参与一个或多个行业审计计划，例如ISAGO、IFQP或DAQCP计划。\nC9（领先）：连续监控外部服务提供商的安全和安保绩效，并至少每年对至少两个运行领域的趋势和结果进行分析。\nC10（领先）：通过基于可靠关键绩效措施/指标的基于绩效的监控系统监控外部服务提供商。\nC11（领先）：运营人的外部服务提供商监控流程包括参与所有以下行业审计计划：ISAGO、IFQP和DAQCP计划（如适用）。\nC12（领先）：在单个外部服务提供商（垄断）绩效次优的情况下进行风险评估，并根据需要应用缓解措施。\nC13（领先）：连续测量所有运行领域的外部服务提供商绩效，并至少每年分析结果。\nC14（领先）：用于监控外部服务提供商的所有关键绩效指标都是SMART的（具体、可衡量、可实现、相关和有时限）。" },
            { subtitle: "ORG 2.2.2 审计作为监控手段", eng: "The Operator should include auditing as a process for the monitoring of external service providers in accordance with ORG 2.2.1. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed auditing processes used for monitoring external service providers that conduct outsourced operational functions.\n▪ Interviewed responsible manager(s).\n▪ Examined selected records/reports resulting from auditing of service providers (focus: audit process ensures provider is fulfilling applicable safety/security requirements).\n▪ Coordinated to verify implementation of service provider auditing in applicable operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nThe intent of this provision is for an operator to use, as deemed appropriate for the situation, auditing as one of the processes for satisfying the requirement for monitoring external service providers (as specified in ORG 2.2.1).\nBoth IOSA and ISAGO are audit programs, so, where applicable, the use of IOSA or ISAGO registration could be considered as an audit process for the purpose of monitoring external service providers.", zh: "运营人应将审计作为根据ORG 2.2.1监控外部服务提供商的一个流程。（推荐实践）(GM) ►\n\n审计员行动：\n▪ 识别/评估用于监控执行外委运行职能的外部服务提供商的审计流程\n▪ 访谈负责经理\n▪ 检查选定的服务提供商审计产生的记录/报告（重点：审计流程确保提供商履行适用的安全/安保要求）\n▪ 协调验证适用运行领域服务提供商审计流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n本条款的意图是让运营人根据情况酌情使用审计作为满足监控外部服务提供商要求（如ORG 2.2.1所述）的流程之一。\nIOSA和ISAGO都是审计项目，因此，在适用的情况下，使用IOSA或ISAGO注册可被视为监控外部服务提供商的审计流程。" },
            { subtitle: "ORG 2.2.3 商业航空协议下的其他运营人审计", eng: "The Operator shall have a process that provides for the auditing of other operator(s). Such process shall ensure the following with respect to the audit of other operator(s):\n(i) The audit is conducted against and requires conformity with applicable ICAO standards;\n(ii) An initial audit is conducted prior to the commencement of the above-specified passenger transport operation(s);\n(iii) A subsequent audit is conducted during every 24-month period following commencement of the above-specified passenger transport operation(s). (GM)\n\nNote: A commercial aviation agreement as specified in this standard includes the following:\n• ACMI Lease (wet lease) Agreement\n• Capacity Purchase Agreement (CPA)\n• Code Share Agreement\n• Damp Lease Agreement\n\nNote: The specifications of this standard shall be applicable to the Operator if it has transported its passengers on another operator under any of the specified commercial aviation agreements during the most recent IOSA registration period.\n\nNote: IOSA registration indicates an operator is in conformity with all applicable ICAO standards and thus is acceptable as the audit of another operator as specified in this provision provided the Operator obtains the latest applicable audit report(s) through official program channels and considers the content of such report(s).\n\nNote: ISSA registration is acceptable as the audit of another operator as specified in this provision, for operations involving aircraft below 5700 kg MTOW, provided the Operator obtains the latest applicable audit report(s) through official program channels and considers the content of such report(s).\n\nAuditor Actions:\n▪ Identified/Assessed process for monitoring safety/security performance of external operators that transport passengers of the Operator.\n▪ Interviewed responsible managers.\n▪ Examined plan/methods for monitoring applicable other operators (focus: includes all operators that transport the operator's passengers under a commercial aviation agreement).\n▪ Examined selected monitoring reports of other operators (focus: monitoring process ensures the other operator is fulfilling applicable safety/security requirements).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of ACMI Lease Agreement, Capacity Purchase Agreement (CPA), Code Share Agreement, Damp Lease Agreement, IOSA Registration Period and Wet Lease Agreement.\nThe intent of this provision is for an operator to have a process that provides for the auditing of any other operator with which it has entered or will enter into a commercial aviation agreement to transport its passengers on flights conducted by the other operator(s). Such audit verifies that the other operator(s) meet(s) applicable ICAO standards and may be conducted either by the operator or by a third party that is acceptable to the operator.\nAnother operator that is on the IOSA Registry has already been audited and found to meet applicable ICAO safety standards. Therefore, conformity with this standard does not require an operator to provide for an additional audit of another operator that is on the IOSA Registry as long as such registration is maintained by the other operator and any registration annotations have been taken into consideration by the operator.\nApplicable ICAO standards as specified in item (i) are those standards contained in Annexes 1, 6, 8, 17, 18 and 19 that would be applicable to the other operator being audited.\nA complete cross-reference list of ICAO-IOSA standards may be found at https://ic.iata.org.", zh: "运营人应制定流程，对其他运营人进行审计。该流程应确保对其他运营人的审计满足以下要求：\n(i) 审计按照适用ICAO标准进行并要求符合这些标准；\n(ii) 在上述旅客运输运行开始前进行初始审计；\n(iii) 在上述旅客运输运行开始后每24个月期间进行一次后续审计。(GM)\n\n注：本标准中规定的商业航空协议包括以下类型：\n• ACMI租赁（湿租）协议\n• 运力购买协议（CPA）\n• 代码共享协议\n• 干租协议\n\n注：如果在最近的IOSA注册期内，运营人根据任何规定的商业航空协议将其旅客运输到另一运营人，则本标准的规范应适用于该运营人。\n\n注：IOSA注册表明运营人符合所有适用ICAO标准，因此，只要运营人通过官方项目渠道获取最新适用审计报告并考虑此类报告的内容，IOSA注册可作为本条款规定的对其他运营人审计的可接受方式。\n\n注：对于涉及最大起飞质量低于5700公斤飞机的运行，只要运营人通过官方项目渠道获取最新适用审计报告并考虑此类报告的内容，ISSA注册可作为本条款规定的对其他运营人审计的可接受方式。\n\n审计员行动：\n▪ 识别/评估监控运输运营人旅客的外部运营人安全/安保绩效的流程\n▪ 访谈负责经理\n▪ 检查监控适用其他运营人的计划/方法（重点：包括根据商业航空协议运输运营人旅客的所有运营人）\n▪ 检查选定的其他运营人监控报告（重点：监控流程确保其他运营人履行适用的安全/安保要求）\n▪ 其他行动（请说明）\n\n指导材料：\nACMI租赁协议、运力购买协议（CPA）、代码共享协议、干租协议、IOSA注册期和湿租协议的定义请参阅IRM。\n本条款的意图是让运营人有一个流程，对与其已经或将要签订商业航空协议、由另一运营人执行航班运输其旅客的任何其他运营人进行审计。此类审计验证其他运营人是否符合适用ICAO标准，可由运营人或运营人可接受的第三方进行。\n已在IOSA登记册上的其他运营人已经过审计并被认定符合适用ICAO安全标准。因此，只要其他运营人维持此类注册并且运营人已考虑任何注册注释，符合本标准不要求运营人对已在IOSA登记册上的其他运营人进行额外审计。\n第(i)项中规定的适用ICAO标准是附件1、6、8、17、18和19中包含的、适用于被审计的其他运营人的那些标准。\nICAO-IOSA标准的完整交叉引用列表可在https://ic.iata.org找到。" },
            { subtitle: "ORG 2.2.4 货运商业航空协议监控", eng: "If the Operator transports cargo with other operators under a commercial aviation agreement, the Operator should have a process to monitor the performance of those other operators that transport its cargo. Such monitoring process should ensure the operational safety and security needs of the Operator are being fulfilled.\n\nNote: A commercial aviation agreement as specified in this recommendation includes the following:\n• ACMI Lease (wet lease) Agreement\n• Capacity Purchase Agreement (CPA)\n• Damp Lease Agreement\n\nNote: IOSA or ISSA registration is acceptable as part of the Operator's monitoring process, when such registration is included in or combined with a risk assessment of the other operator(s).\n\nAuditor Actions:\n▪ Identified/Assessed process for monitoring safety/security performance of external operators that transport cargo of the Operator.\n▪ Interviewed responsible manager(s).\n▪ Examined plan/methods for monitoring applicable other operators (focus: includes all operators that transport the operator's cargo under a commercial aviation agreement).\n▪ Examined selected monitoring reports of other operators (focus: monitoring process ensures the other operator is fulfilling applicable safety/security requirements).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of ACMI Lease Agreement, Capacity Purchase Agreement (CPA), Damp Lease Agreement, and Wet Lease Agreement.\nThe intent of this provision is for an operator to have a process that provides for the monitoring of any other operator with which it has entered or will enter into a commercial aviation agreement to transport its cargo on flights conducted by the other operator.\nAnother operator that is on the IOSA or ISSA Registry has already been audited and found to meet applicable safety standards. Therefore, the monitoring of another operator could consist of verifying IOSA/ISSA Registry and monitoring any registration annotations.", zh: "如果运营人根据商业航空协议与其他运营人一起运输货物，运营人应制定流程监控运输其货物的其他运营人的绩效。该监控流程应确保运营人的运行安全和安保需求得到满足。（推荐实践）\n\n注：本推荐实践中规定的商业航空协议包括以下类型：\n• ACMI租赁（湿租）协议\n• 运力购买协议（CPA）\n• 干租协议\n\n注：当IOSA或ISSA注册与其他运营人的风险评估相结合或包含在其中时，可作为运营人监控流程的一部分被接受。\n\n审计员行动：\n▪ 识别/评估监控运输运营人货物的外部运营人安全/安保绩效的流程\n▪ 访谈负责经理\n▪ 检查监控适用其他运营人的计划/方法（重点：包括根据商业航空协议运输运营人货物的所有运营人）\n▪ 检查选定的其他运营人监控报告（重点：监控流程确保其他运营人履行适用的安全/安保要求）\n▪ 其他行动（请说明）\n\n指导材料：\nACMI租赁协议、运力购买协议（CPA）、干租协议和湿租协议的定义请参阅IRM。\n本条款的意图是让运营人有一个流程，对与其已经或将要签订商业航空协议、由另一运营人执行航班运输其货物的任何其他运营人进行监控。\n已在IOSA或ISSA登记册上的其他运营人已经过审计并被认定符合适用安全标准。因此，对其他运营人的监控可以包括验证IOSA/ISSA注册和监控任何注册注释。" }
        ]
    },
    
        product_control: {
        title: "2.3 产品控制 - Product Control",
        sections: [
            { subtitle: "ORG 2.3.1 产品验收", eng: "The Operator should have processes to ensure equipment or other operational products relevant to the safety or security of aircraft operations that are purchased or otherwise acquired from an external vendor or supplier meet the product technical requirements specified by the Operator prior to being used in the conduct of operations or aircraft maintenance. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed processes for ensuring acquired operational products meet technical requirements.\n▪ Interviewed responsible manager(s).\n▪ Examined selected product acceptance records (focus: acquired products meet applicable technical requirements).\n▪ Coordinated to verify product acceptance processes implemented in applicable operational areas).\n▪ Other Actions (Specify)\n\nGuidance:\nThis provision applies only to products that are purchased or otherwise acquired from an external supplier or vendor. Whereas purchasing might be the most typical means of acquiring such products, other means might be also be used (e.g. lease, barter).\nThis provision does not apply to outsourced operational functions or services that are provided by an external organization or service provider (this is addressed in ORG 1.6.1 and 1.6.2).\nThis provision does not apply to electronic navigation data products used in flight (e.g. FMS database) or for operational control (e.g. flight planning database). The acquisition of such navigation data products requires control procedures, as specified in Sections 2 (FLT) and 3 (DSP).\nFollowing are some examples of products that could have a negative effect on operations if put into service with substandard quality (i.e. the operator's technical standards are not met).\n• Training devices (e.g. simulators, door mock-ups);\n• Cabin safety cards or videos;\n• Cabin service carts or trolleys;\n• Onboard safety equipment (e.g. PBE, life jackets);\n• Ground support equipment;\n• Operational software, databases (non-navigation);\n• Security screening equipment;\n• Unit load devices (ULDs).\nPart of the process is a method for identifying products that have a direct effect on the safety or security of operations.\nTo ensure technical specifications are met, a process may focus on the supplier, the product or a combination of both.\nThe process may include an evaluation of suppliers, with the selection of suppliers based on their ability to supply products in accordance with the operator's requirements and technical specifications.\nThe use of formal industry supplier audit or evaluation programs is one means for assessing the abilities of suppliers to deliver quality products, such as the Coordinating Agency for Supplier Evaluation (CASE).\nImplementation of a rigorous receiving inspection process (or equivalent activity) provides another means of verifying that operationally critical products meet specified technical requirements prior to such products being put into service.", zh: "运营人应制定流程，确保从外部供应商或销售商购买或以其他方式获得的与航空器运行安全或安保相关的设备或其他运行产品，在用于运行或飞机维修之前满足运营人规定的产品技术要求。（推荐实践）(GM) ►\n\n审计员行动：\n▪ 识别/评估确保获得的运行产品满足技术要求的流程\n▪ 访谈负责经理\n▪ 检查选定的产品验收记录（重点：获得的产品满足适用技术要求）\n▪ 协调验证适用运行领域产品验收流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n本条款仅适用于从外部供应商或销售商购买或以其他方式获得的产品。虽然购买可能是获得此类产品的最典型方式，但也可能使用其他方式（例如租赁、易货）。\n本条款不适用于由外部组织或服务提供商提供的外委运行职能或服务（这由ORG 1.6.1和1.6.2处理）。\n本条款不适用于飞行中使用的电子导航数据产品（例如FMS数据库）或用于运行控制的产品（例如飞行计划数据库）。此类导航数据产品的获取需要控制程序，如第2部分（FLT）和第3部分（DSP）所述。\n以下是一些如果以不合格质量（即不满足运营人的技术标准）投入使用可能对运行产生负面影响的产品的示例：\n• 训练设备（例如模拟器、舱门模型）；\n• 客舱安全卡或视频；\n• 客舱服务车或手推车；\n• 机上安全设备（例如PBE、救生衣）；\n• 地面支持设备；\n• 运行软件、数据库（非导航）；\n• 安保检查设备；\n• 集装设备（ULD）。\n流程的一部分是识别对运行安全或安保有直接影响的产品的方法。\n为确保满足技术规范，流程可以侧重于供应商、产品或两者的结合。\n流程可能包括对供应商的评估，根据其按照运营人要求和技术规范供应产品的能力选择供应商。\n使用正式的行业供应商审计或评估计划是评估供应商交付优质产品能力的一种手段，例如供应商评估协调机构（CASE）。\n实施严格的收货检查流程（或等效活动）提供了另一种验证运行关键产品在投入使用前满足指定技术要求的方法。" }
        ]
    },
        data_management: {
        title: "2.4 数据管理 - Data Management",
        sections: [
            { subtitle: "ORG 2.4.1 质量保证审计数据库", eng: "The Operator shall have an electronic database to ensure the effective management of information and data associated with audits conducted under the quality assurance program as specified in ORG 2.1.1 and ORG 2.1.4. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed electronic database for management of quality assurance audit data.\n▪ Interviewed quality assurance program manager.\n▪ Examined selected database records (focus: content includes information/data specified in ORG 2.1.4 and Table 1.2).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Database.\nA database would typically include, as a minimum, the following information associated with each audit:\n• Details of each planned and conducted audit\n  – Area/entity audited;\n  – Status of the audit (planned, conducted, re-scheduled, completed);\n  – Date of audit;\n  – Objective, scope and criteria;\n  – Auditor name.\n• Non-conformity details:\n  – Root cause(s);\n  – Corrective action(s) implemented;\n  – Assignment of responsibility;\n  – Closure and acceptance details.", zh: "运营人应建立电子数据库，以确保有效管理与根据ORG 2.1.1和ORG 2.1.4在质量保证方案下进行的审计相关的信息和数据。(GM)\n\n审计员行动：\n▪ 识别/评估用于管理质量保证审计数据的电子数据库\n▪ 访谈质量保证方案经理\n▪ 检查选定的数据库记录（重点：内容包含ORG 2.1.4和表1.2中规定的信息/数据）\n▪ 其他行动（请说明）\n\n指导材料：\n数据库的定义请参阅IRM。\n数据库通常至少包括与每次审计相关的以下信息：\n• 每次计划和已执行审计的详细信息\n  – 被审计区域/实体；\n  – 审计状态（已计划、已执行、已重新排程、已完成）；\n  – 审计日期；\n  – 目标、范围和标准；\n  – 审计员姓名。\n• 不符合项详情：\n  – 根本原因；\n  – 已实施的纠正措施；\n  – 责任分配；\n  – 关闭和验收详情。" },
            { subtitle: "ORG 2.4.2 危险识别与风险管理数据库", eng: "The Operator shall have an electronic database to ensure effective management of data derived from the hazard identification and risk assessment and mitigation programs. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed hazard identification and risk management program database.\n▪ Interviewed safety manager.\n▪ Observed demonstration of hazard identification and risk management program database functionality.\n▪ Other Actions (Specify)\n\nGuidance:\nThe intent of this provision is for an operator to have an electronic database that permits an operator to manage information and data associated with aircraft operations in a manner that results in the identification of hazards and the provision of information to operational managers as specified in ORG 3.1.1.\nThe type and complexity of such database will vary according to the size and scope of the organization.", zh: "运营人应建立电子数据库，以确保有效管理来自危险识别以及风险评估和缓解方案的数据。(GM)\n\n审计员行动：\n▪ 识别/评估危险识别和风险管理方案数据库\n▪ 访谈安全经理\n▪ 观察危险识别和风险管理方案数据库功能演示\n▪ 其他行动（请说明）\n\n指导材料：\n本条款的意图是让运营人拥有一个电子数据库，允许运营人以识别危险并向运行经理提供信息的方式管理与航空器运行相关的信息和数据，如ORG 3.1.1所述。\n此类数据库的类型和复杂性将根据组织的规模和范围而变化。" },
            { subtitle: "ORG 2.4.3 IATA事件数据交换", eng: "The Operator should have a process to ensure reports of safety and security occurrences are submitted to IATA for inclusion in the Incident Data Exchange (IDX). Such reports should be submitted in accordance with the formal IDX reporting process and include incidents and reports from:\n(i) Flight operations;\n(ii) Cabin operations;\n(iii) Ground handling operations;\n(iv) Engineering and Maintenance. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed process for reporting incidents to IATA for inclusion in IDX.\n▪ Interviewed responsible manager(s).\n▪ Examined the agreement between the Operator and IATA for participation in IDX.\n▪ Examined selected reports submitted to IATA.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of IATA Incident Data Exchange (IDX).\nThe IATA IDX is a quality source of defensible data to support analyses and production of performance and benchmarking indicators for use in the management of all operations, to include flight operations, cabin operations, and ground handling operations.\nReports submitted to IDX will be assembled and integrated in a manner that permits, through statistical analysis, the identification of trends and contributing factors associated with safety and security events.\nIDX participants that regularly submit reports benefit by gaining access to the aforementioned analytical results. Failure to submit reports will result in participants being excluded from the program.\nThe assurance of data quality and overall database integrity requires data to be submitted by participants in a uniform and consistent manner. Therefore, IDX will require a strict reporting taxonomy, including associated definitions and assumptions.\nReporting guidelines and other information can be found online at the IATA Global Aviation Data Management page (https://www.iata.org/en/services/statistics/gadm/).", zh: "运营人应制定流程，确保将安全和安保事件的报告提交给IATA，以纳入事件数据交换（IDX）。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估向IATA报告事件以纳入IDX的流程\n▪ 访谈负责经理\n▪ 检查运营人与IATA之间参与IDX的协议\n▪ 检查选定的提交给IATA的报告\n▪ 其他行动（请说明）\n\n指导材料：\nIATA事件数据交换（IDX）的定义请参阅IRM。\nIATA IDX是支持分析和生成绩效与基准指标的可辩护数据的优质来源，用于管理所有运行，包括飞行运行、客舱运行和地面操作运行。\n提交给IDX的报告将以允许通过统计分析识别与安全和安保事件相关的趋势和促成因素的方式进行汇总和整合。\n定期提交报告的IDX参与者通过访问上述分析结果而受益。未能提交报告将导致参与者被排除在该项目之外。\n数据质量和整体数据库完整性的保证要求参与者以统一一致的方式提交数据。因此，IDX将要求严格的报告分类法，包括相关的定义和假设。\n报告指南和其他信息可在IATA全球航空数据管理页面在线找到（https://www.iata.org/en/services/statistics/gadm/）。" },
            { subtitle: "ORG 2.4.4 飞行数据共享项目", eng: "The Operator should participate in and supply data to an aggregated Flight Data Sharing Program that is applied to aircraft in its fleet with a certified take-off mass in excess of 20,000 kg (44,092 lbs). As a minimum, such program should:\n(i) Have a signed agreement with the program participants (member airlines) on how their data will be utilized;\n(ii) Provide a means for participants to securely transfer their flight data;\n(iii) Be non-punitive and offer adequate safeguards for the de-identification of all data received from participants;\n(iv) Disseminate de-identified information to participants on emerging trends and areas of interest to global aviation safety;\n(v) Not use data for the purposes of investigation of the performance of individual participants.\n\nAuditor Actions:\n▪ Identified/Assessed process for the secure transfer of data.\n▪ Interviewed responsible manager(s).\n▪ Examined the agreement between the Operator and participating operators on how the data would be utilized.\n▪ Examined selected de-identified reports.\n▪ Other Actions (Specify)\n\nGuidance:\nAcceptable flight data sharing programs include, but are not limited to the IATA Flight Data Exchange (FDX) or any State-run, aggregated data sharing programs such as ASIAS, Data 4 Safety etc.\nAn aggregated flight data sharing program is a de-identified database of flight data collected from multiple participants and processed for the purposes of improvement of aviation safety through the identification of areas of safety concern and risk. Such programs also enable participants undertake comparative analysis on global or regional specific performance.\nA state-run aggregated flight data sharing program is one undertaken by a competent aviation state body in a specific country e.g. The Federal Aviation Administration (FAA), European Aviation Safety Agency (EASA).", zh: "运营人应参与并向聚合飞行数据共享项目提供数据，该项目适用于其机队中认证起飞质量超过20,000公斤（44,092磅）的飞机。至少，此类项目应：\n(i) 与项目参与者（成员航空公司）就如何使用其数据签订协议；\n(ii) 为参与者提供安全传输其飞行数据的手段；\n(iii) 非惩罚性，并为对从参与者收到的所有数据进行去标识化提供充分保障；\n(iv) 向参与者传播关于新兴趋势和全球航空安全关注领域的去标识化信息；\n(v) 不将数据用于调查个别参与者绩效的目的。（推荐实践）\n\n审计员行动：\n▪ 识别/评估安全传输数据的流程\n▪ 访谈负责经理\n▪ 检查运营人与参与运营商之间关于如何使用数据的协议\n▪ 检查选定的去标识化报告\n▪ 其他行动（请说明）\n\n指导材料：\n可接受的飞行数据共享项目包括但不限于IATA飞行数据交换（FDX）或任何国家运营的聚合数据共享项目，例如ASIAS、Data 4 Safety等。\n聚合飞行数据共享项目是一个从多个参与者收集的飞行数据的去标识化数据库，并通过识别安全关注领域和风险进行处理，以改善航空安全。此类项目还使参与者能够对全球或区域特定绩效进行比较分析。\n国家运营的聚合飞行数据共享项目是由特定国家的主管航空机构（例如美国联邦航空管理局（FAA）、欧洲航空安全局（EASA））进行的项目。" }
        ]
    },
    
        doc_system: {
        title: "2.5 文件体系 - Documentation System",
        sections: [
            { subtitle: "ORG 2.5.1 文件管理与控制", eng: "The Operator shall have a system for the management and control of documentation and/or data used directly in the conduct or support of operations. Such system shall ensure documentation:\n(i) Meets all required elements specified in Table 1.1;\n(ii) Contains legible and accurate information;\n(iii) Is presented in a format appropriate for use in operations. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed system(s) for management/control of content/format of operational documentation/data used in operational control system.\n▪ Interviewed responsible operational control manager(s).\n▪ Examined selected parts of the OM (focus: legibility/accuracy/format; approval as applicable).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Documentation, Electronic Documentation and Paper Documentation.\nThe primary purpose of document control is to ensure necessary, accurate and up-to-date documents are available to those personnel required to use them, to include, in the case of outsourced operational functions, employees of external service providers.\nExamples of documents that are controlled include, but are not limited to, operations manuals, checklists, quality manuals, training manuals, process standards, policy manuals, and standard operating procedures.\nDocumentation received from external sources would include manuals and other types of relevant documents that contain material that is pertinent to the safety of operations conducted by the operator (e.g. regulations, operating standards, technical information and data).\nAn electronic system of document management and control is an acceptable means of conformance. Within such a system, document files are typically created, maintained, identified, revised, distributed, accessed, presented, retained and/or deleted using computer systems (e.g. a web-based system). Some systems specify immediate obsolescence for any information or data that is downloaded or otherwise extracted (e.g. printed on paper) from the electronic files.\nDocument control might include:\n• Retention of a master copy;\n• Examination and approval prior to issue;\n• Review and update, to include an approval process;\n• Version control (electronic documents);\n• Identification of revision status;\n• Identification and retention of revisions as history;\n• Identification and retention of background or source references as history;\n• Distribution to ensure appropriate availability at points of use;\n• Checking of documents to verify they remain legible and readily identifiable;\n• As required, identification, update, distribution and retention of documents of external origin;\n• As applicable, identification and retention of obsolete documents;\n• As applicable, disposal of documents.\nAdditionally, control of operational manuals might include:\n• Assignment of an individual with responsibility for approval for contents;\n• A title page that generally identifies the operational applicability and functionality;\n• A table of contents that identifies parts and sub-parts;\n• A preface or introduction outlining the general contents of the manual;\n• Reference numbers for the content of the manual;\n• A defined distribution method and identification of recipients;\n• Identification of responsibility for authorizing the manual;\n• A record of revisions, both temporary and permanent;\n• A list of effective pages within the manual;\n• Identification of revised content.\nEach \"loose\" documented procedure that is not held within a manual typically includes:\n• A title page that identifies the operational applicability and functionality;\n• Identification of the date(s) of issue and date of effectiveness;\n• Reference numbers for the content;\n• A distribution list;\n• Identification of responsibility for authorizing the document.", zh: "运营人应建立用于管理和控制直接用于运行开展或支持的文件和/或数据的系统。此类系统应确保文件：\n(i) 满足表1.1中规定的所有要求要素；\n(ii) 包含清晰准确的信息；\n(iii) 以便于运行使用的格式呈现。(GM) ►\n\n审计员行动：\n▪ 识别/评估用于管理/控制运行控制系统中使用的运行文件/数据的内容/格式的系统\n▪ 访谈负责的运行控制经理\n▪ 检查OM中选定的部分（重点：清晰度/准确性/格式；如适用，批准情况）\n▪ 其他行动（请说明）\n\n指导材料：\n文件、电子文件和纸质文件的定义请参阅IRM。\n文件控制的主要目的是确保需要使用的相关人员能够获得必要、准确和最新的文件，在外委运行职能的情况下，包括外部服务提供商的员工。\n受控文件的示例包括但不限于运行手册、检查单、质量手册、培训手册、流程标准、政策手册和标准操作程序。\n从外部来源收到的文件将包括手册和其他类型的相关文件，其中包含与运营人运行安全相关的材料（例如法规、运行标准、技术信息和数据）。\n电子文件管理和控制系统是可接受的符合性方式。在此类系统中，通常使用计算机系统（例如基于Web的系统）创建、维护、标识、修订、分发、访问、呈现、保留和/或删除文件。某些系统规定从电子文件下载或以其他方式提取（例如打印在纸上）的任何信息或数据立即作废。\n文件控制可能包括：\n• 保留主副本；\n• 发布前检查和批准；\n• 审查和更新，包括批准流程；\n• 版本控制（电子文件）；\n• 修订状态标识；\n• 修订的标识和保留作为历史记录；\n• 背景或来源参考的标识和保留作为历史记录；\n• 分发以确保在使用点适当可用；\n• 检查文件以验证其保持清晰和易于识别；\n• 根据需要，识别、更新、分发和保留外部来源的文件；\n• 如适用，识别和保留作废文件；\n• 如适用，处理文件。\n此外，运行手册的控制可能包括：\n• 指定负责批准内容的个人；\n• 标题页，一般标识运行适用性和功能；\n• 标识部分和子部分的目录；\n• 概述手册一般内容的序言或引言；\n• 手册内容的参考编号；\n• 定义的分发方法和接收者标识；\n• 授权手册的责任标识；\n• 修订记录，包括临时和永久修订；\n• 手册内有效页面列表；\n• 修订内容的标识。\n每个不在手册中的\"散装\"文件化程序通常包括：\n• 标题页，标识运行适用性和功能；\n• 发行日期和生效日期的标识；\n• 内容的参考编号；\n• 分发列表；\n• 授权文件的责任标识。" },
            { subtitle: "ORG 2.5.2", eng: "(Intentionally open)", zh: "（有意留空）" },
            { subtitle: "ORG 2.5.3 集中化文件体系", eng: "The Operator should have a documentation system that ensures operations, maintenance and security manuals are centrally managed or coordinated under a corporate scheme of document hierarchy. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed central system for management/control of content/format of operational documentation/data (focus: common standards for documentation/data control in all areas of operations).\n▪ Interviewed responsible management representative(s).\n▪ Examined/Compared selected operational documents (focus: standardized documents consistent with central system standards).\n▪ Other Actions (Specify)\n\nGuidance:\nA centrally controlled or coordinated system ensures a standardized documentation product throughout the organization. Ideally, all documents conform to a corporate standard, thus ensuring an organization-wide consistency in documentation philosophy, format and presentation of content.", zh: "运营人应建立一个文件体系，确保运行、维修和安保手册在公司文件层级方案下集中管理或协调。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估用于管理/控制运行文件/数据的内容/格式的中央系统（重点：所有运行领域文件/数据控制的通用标准）\n▪ 访谈负责的管理代表\n▪ 检查/比较选定的运行文件（重点：与中央系统标准一致的标准文件）\n▪ 其他行动（请说明）\n\n指导材料：\n集中控制或协调的系统确保整个组织的标准化文件产品。理想情况下，所有文件都符合公司标准，从而确保整个组织在文件理念、格式和内容呈现上的一致性。" },
            { subtitle: "ORG 2.5.4 SMS文件", eng: "The Operator shall have SMS documentation, including a manual, that describes:\n(i) The safety policy and objectives;\n(ii) SMS requirements;\n(iii) SMS processes and procedures;\n(iv) Accountability, authorities and responsibilities for SMS processes and procedures. [SMS] (GM)\n\nNote: An SMS manual may be in the form of a stand-alone document or may be integrated with other organizational documents (or documentation) maintained by the Operator.\n\nAuditor Actions:\n▪ Identified/Assessed SMS documentation (focus: description of overall organizational management of safety).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected parts of SMS documentation (focus: content includes safety policy/objectives; describes/defines accountability/responsibilities for safety processes/procedures in all areas of operations).\n▪ Coordinated to verify SMS documentation in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nSMS documentation is an element of the Safety Policy and Objectives component of the SMS framework.\nSMS documentation is typically scaled to the size and complexity of the organization and describes both the corporate and operational areas of safety management to show continuity of the SMS throughout the organization. Typical documentation would include a description of management positions and associated accountability, authorities, and responsibilities within the SMS.\nTo ensure personnel throughout the organization are informed, SMS documentation includes a description of the operator's approach to safety management. Such descriptive information would be contained in a manual and presented in a manner that ensures the SMS information is clearly identifiable. The exact title and structure of such manual may vary with each operator.\nDepending on the size, structure and scope of an operator's organization, as well as the complexity of its operations, SMS documentation may be in the form of stand-alone documents or may be integrated into other organizational documents.\nRequirements for SMS documentation will vary according to the individual state safety program (SSP).\nSMS documentation typically addresses:\n• Scope of the SMS;\n• Safety policy and objectives;\n• Safety accountability;\n• Key safety personnel;\n• Documentation control procedures;\n• Coordination of emergency response planning;\n• Hazard identification and risk management schemes;\n• Safety assurance;\n• Safety performance monitoring;\n• Safety auditing (safety and quality auditing may be combined);\n• Management of change;\n• Safety promotion;\n• Outsourced services.\nExpanded guidance may be found in the ICAO SMM, Document 9859.", zh: "运营人应制定SMS文件，包括一本手册，描述：\n(i) 安全政策和目标；\n(ii) SMS要求；\n(iii) SMS流程和程序；\n(iv) SMS流程和程序的问责制、权限和职责。[SMS] (GM)\n\n注：SMS手册可以是独立文件的形式，也可以与运营人维护的其他组织文件（或文件）整合。\n\n审计员行动：\n▪ 识别/评估SMS文件（重点：描述安全的整体组织管理）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查SMS文件的选定部分（重点：内容包括安全政策/目标；描述/定义所有运行领域安全流程/程序的问责制/职责）\n▪ 协调验证所有运行领域的SMS文件\n▪ 其他行动（请说明）\n\n指导材料：\nSMS文件是SMS框架中安全政策和目标组成部分的一个要素。\nSMS文件通常根据组织的规模和复杂性进行缩放，并描述安全管理的公司和运行领域，以显示SMS在整个组织中的连续性。典型文件将包括管理职位以及SMS内相关问责制、权限和职责的描述。\n为确保整个组织的人员知情，SMS文件包括对运营人安全管理方法的描述。此类描述性信息将包含在一本手册中，并以确保SMS信息清晰可识别的方式呈现。此类手册的确切标题和结构可能因运营人而异。\n根据运营人组织的规模、结构和范围以及其运行的复杂性，SMS文件可以是独立文件的形式，也可以整合到其他组织文件中。\nSMS文件的要求将根据各个国家安全计划（SSP）而有所不同。\nSMS文件通常涉及：\n• SMS的范围；\n• 安全政策和目标；\n• 安全问责制；\n• 关键安全人员；\n• 文件控制程序；\n• 应急响应规划的协调；\n• 危险识别和风险管理方案；\n• 安全保证；\n• 安全绩效监控；\n• 安全审计（安全和质量审计可以合并）；\n• 变更管理；\n• 安全促进；\n• 外委服务。\n扩展指导可参见ICAO SMM，文件9859。" }
        ]
    },    
        records_system: {
        title: "2.6 记录体系 - Records System",
        sections: [
            { subtitle: "ORG 2.6.1 运行记录管理与控制", eng: "The Operator shall have a system for the management and control of operational records to ensure the content and retention of such records is in accordance with requirements of the Authority, as applicable, and to ensure operational records are subjected to standardized processes for:\n(i) Identification;\n(ii) Legibility;\n(iii) Maintenance;\n(iv) Retrieval;\n(v) Protection, integrity and security;\n(vi) Disposal, deletion (electronic records) and archiving. (GM) ►\n\nNote: The operational records system specified in this standard shall also include the management and control of SMS operational records.\n\nAuditor Actions:\n▪ Identified/Assessed system for management/control of operational records (focus: system includes standardized processes as specified in standard).\n▪ Interviewed responsible management representative(s).\n▪ Examined selected examples of operational records.\n▪ Coordinated to verify implementation of records management/control processes in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nThe system addresses the management and control of all records associated with operations, which includes personnel training records, and also includes any other records that document the fulfillment of operational requirements (e.g. aircraft maintenance, operational control, operational security).\nSMS operational records substantiate the ongoing operation of the operator's SMS and may be managed and controlled within either a centralized or standalone records system. SMS operational records typically include or provide a record of the following:\n• Hazards register and hazard/safety reports;\n• SPIs, SPTs and related charts;\n• Completed safety risk assessments;\n• SMS internal reviews or audits;\n• SMS/safety training;\n• SMS/safety committee meeting minutes.", zh: "运营人应建立运行记录管理和控制系统，以确保此类记录的内容和保留符合适用当局的要求，并确保运行记录受到标准化流程的约束，用于：\n(i) 标识；\n(ii) 清晰度；\n(iii) 维护；\n(iv) 检索；\n(v) 保护、完整性和安全性；\n(vi) 处置、删除（电子记录）和存档。(GM) ►\n\n注：本标准中规定的运行记录系统还应包括SMS运行记录的管理和控制。\n\n审计员行动：\n▪ 识别/评估运行记录的管理/控制系统（重点：系统包括标准中规定的标准化流程）\n▪ 访谈负责的管理代表\n▪ 检查选定的运行记录示例\n▪ 协调验证所有运行领域记录管理/控制流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n该系统处理与运行相关的所有记录的管理和控制，包括人员培训记录，也包括记录运行要求履行的任何其他记录（例如飞机维修、运行控制、运行安保）。\nSMS运行记录证实运营人SMS的持续运行，可以在集中式或独立记录系统中进行管理和控制。SMS运行记录通常包括或提供以下内容的记录：\n• 危险登记册和危险/安全报告；\n• SPI、SPT和相关图表；\n• 已完成的安全风险评估；\n• SMS内部审查或审计；\n• SMS/安全培训；\n• SMS/安全委员会会议记录。" },
            { subtitle: "ORG 2.6.2 电子记录备份", eng: "If the Operator uses an electronic system for the management and control of records, the Operator shall ensure the system provides for a scheduled generation of backup record files. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed process for scheduled backup of electronic operational records (focus: system defines schedule for periodic file backup).\n▪ Interviewed responsible management representative(s).\n▪ Coordinated to verify applicable backup process is implemented in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nMaintaining records in electronic files is a reliable and efficient means of short and long-term storage. The integrity of this type of record-keeping system is ensured through secure, safe storage and backup systems.\nIn an electronic records system, record files are managed and controlled (i.e. created, maintained, identified, updated, accessed, retained and deleted) using computer systems, programs and displays (e.g. a web-based system).\nTo preclude the loss of records due to hardware or software failures, an electronic system is programmed to create backup files on a schedule that ensures records are never lost. Typically, an electronic system provides for file backup on a daily basis.\nWhere necessary, the look and feel of electronic records is similar to that of a paper record.\nThe retention period for records is defined by the operator and, if applicable, will always be in accordance with requirements of the Authority.\nHardware and software, when updated or replaced, is retained to enable retrieval of old records.", zh: "如果运营人使用电子系统进行记录的管理和控制，运营人应确保该系统按计划生成备份记录文件。(GM) ►\n\n审计员行动：\n▪ 识别/评估电子运行记录定期备份的流程（重点：系统定义定期文件备份的时间表）\n▪ 访谈负责的管理代表\n▪ 协调验证适用备份流程在所有运行领域的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n将记录保存在电子文件中是短期和长期存储的可靠且高效的手段。此类记录保存系统的完整性通过安全、可靠的存储和备份系统得以保证。\n在电子记录系统中，使用计算机系统、程序和显示器（例如基于Web的系统）管理和控制记录文件（即创建、维护、标识、更新、访问、保留和删除）。\n为了防止因硬件或软件故障导致记录丢失，电子系统被编程为按计划创建备份文件，以确保记录永远不会丢失。通常，电子系统每天进行文件备份。\n必要时，电子记录的外观和感觉与纸质记录相似。\n记录的保留期由运营人定义，并且如适用，将始终符合当局的要求。\n硬件和软件在更新或更换时被保留以支持旧记录的检索。" }
        ]
    },

    // ==================== 第三部分：风险管理 ====================
        hazard_id: {
        title: "3.1 危险识别 - Hazard Identification",
        sections: [
            { subtitle: "ORG 3.1.1 危险识别方案", eng: "The Operator shall have a hazard identification program that is implemented and integrated throughout the organization and includes a combination of reactive and proactive methods of hazard identification. [SMS] [MA] (GM) ►\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed organizational safety hazard identification program (focus: program identifies hazards to aircraft operations; describes/defines method(s) of safety data collection/analysis).\n▪ Identified/Assessed cross-discipline process for safety hazard identification (focus: all operational disciplines participate in process).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected records/documents that illustrate organizational integration (focus: coordinated involvement of all operational disciplines in hazard identification process).\n▪ Examined selected examples of hazards identified through data collection/analysis.\n▪ Coordinated to verify implementation of safety hazard identification program in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Hazard (Aircraft Operations) and Safety Risk.\nHazard identification is an element of the Safety Risk Management component of the SMS framework.\nThe methods used to identify hazards will typically depend on the resources and constraints of each particular organization. Some organizations might deploy comprehensive, technology-intensive hazard identification processes, while organizations with smaller, less complex operations might implement more modest hazard identification processes. Regardless of organizational size or complexity, to ensure all hazards are identified to the extent possible, hazard identification processes are necessarily formalized, coordinated and consistently applied on an on-going basis in all areas of the organization where there is a potential for hazards that could affect aircraft operations.\nTo be effective, reactive and proactive processes are used to acquire information and data, which are then analyzed to identify existing or predict future (i.e. potential) hazards to aircraft operations.\nExamples of processes that typically yield information or data for hazard identification are shown in the list below. The most common type of process associated with each example is shown in parentheses, although some could be used both:\n• Confidential or other reporting by personnel (proactive);\n• Investigation of accidents, incidents, irregularities and other non-normal events (reactive);\n• Flight data analysis (proactive);\n• Observation of flight crew performance in line operations and training (proactive);\n• Quality assurance and/or safety auditing (proactive);\n• Safety information gathering or exchange (external sources).\nProcesses would be designed to identify hazards that might be associated with organizational business changes (e.g. addition of new routes or destinations, acquisition of new aircraft type(s), the introduction of significant outsourcing of operational functions).\nTypically, hazards are assigned a tracking number and recorded in a log or database. Each log or database entry would normally include a description of the hazard, as well as other information necessary to track associated risk assessment and mitigation activities.\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: The Operator maintains an overview of its operational risk through hazard identification program which includes proactive and reactive risks identification. All relevant hazards are being identified for the purpose of managing relevant risks.\nSuitability Considerations: • Number of analyzed hazards based on size and complexity of operations. • Data and sources used in the hazard identification process.\nC1 (Established): Through various means to include newsletters, emails and/or messages, the Operator regularly encourages personnel to report hazards.\nC2 (Established): The Operator has effective means (e.g. forms, methods etc) to capture different types of hazards/issues, considering the needs of different working environments (user friendliness, accessibility etc.).\nC3 (Established): The Operator takes reasonable steps to identify all hazards affecting its operations to include hazards specific to the operation type, operational environment, and the region.\nC4 (Established): The Operator has a program for the systematic acquisition and analysis of data from observations of flight crew performance during normal line operations (e.g. LOSA) as per ORG 3.1.4 and identifies related hazards from the program.\nC5 (Mature): The Operator reviews and continuously improves as required its hazard identification program and associated processes.\nC6 (Mature): Operator identifies hazards through industry reports, trends provided by IATA and/or any other organizations to include Authorities.\nC7 (Mature): SMS Training as required by ORG 4.3.1 includes in-depth hazard identification section and detailed training material with practical examples.\nC8 (Mature): Operational Managers are familiar with hazards identified within their operational areas, and actively promote & encourage all operational personnel in identifying hazards to aircraft operations.\nC9 (Mature): Hazards are identified through regular safety culture surveys, such as I-ASC: IATA Aviation Safety Culture Survey.\nC10 (Leading): The Operator deploys comprehensive, technology-based hazard identification processes such as use of artificial intelligence, to facilitate the hazard identification process.\nC11 (Leading): The Operator shares and/or benchmarks its hazards with industry organizations, bodies and/or groups to facilitate the global development of hazard identification.\nC12 (Leading): There is a significantly higher ratio of hazards identified through proactive methods compared to reactive methods.", zh: "运营人应制定危险识别方案，在整个组织内实施和整合，并包括危险识别的反应式和主动式方法的组合。[SMS] [MA] (GM) ►\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估组织安全危险识别方案（重点：方案识别航空器运行危险；描述/定义安全数据收集/分析方法）\n▪ 识别/评估安全危险识别的跨学科流程（重点：所有运行学科参与流程）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查说明组织整合的选定记录/文件（重点：所有运行学科协调参与危险识别流程）\n▪ 检查通过数据收集/分析识别的选定危险示例\n▪ 协调验证所有运行领域安全危险识别方案的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n危险（航空器运行）和安全风险的定义请参阅IRM。\n危险识别是SMS框架中安全风险管理组成部分的一个要素。\n用于识别危险的方法通常取决于每个特定组织的资源和限制。一些组织可能部署全面、技术密集型的危险识别流程，而运行规模较小、复杂性较低的组织可能实施较简单的危险识别流程。无论组织规模或复杂性如何，为了确保尽可能识别所有危险，危险识别流程必须在组织的所有可能存在影响航空器运行危险的领域中进行正式化、协调并持续一致地应用。\n为了有效，使用反应式和主动式流程获取信息和数据，然后分析以识别现有或预测未来（即潜在）的航空器运行危险。\n通常为危险识别产生信息或数据的流程示例列示如下。每个示例相关的最常见流程类型在括号中显示，尽管有些可以同时使用：\n• 人员的保密或其他报告（主动式）；\n• 事故、征候、不规范情况和其他非正常事件的调查（反应式）；\n• 飞行数据分析（主动式）；\n• 航线运行和训练中飞行机组表现的观察（主动式）；\n• 质量保证和/或安全审计（主动式）；\n• 安全信息收集或交换（外部来源）。\n流程的设计应能识别可能与组织业务变更（例如增加新航线或目的地、购置新机型、引入运行职能的重大外委）相关的危险。\n通常，危险会被分配一个跟踪号并记录在日志或数据库中。每个日志或数据库条目通常包括对危险的描述，以及跟踪相关风险评估和缓解活动所需的其他信息。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：运营人通过危险识别方案（包括主动式和反应式风险识别）保持对其运行风险的概览。为管理相关风险的目的识别所有相关危险。\n充分性考虑：• 基于运行规模和复杂性的分析危险数量。• 危险识别过程中使用的数据和来源。\nC1（建立）：通过包括通讯、电子邮件和/或消息在内的各种方式，运营人定期鼓励人员报告危险。\nC2（建立）：运营人有有效的手段（例如表格、方法等）来捕获不同类型的危险/问题，考虑不同工作环境的需求（用户友好性、可访问性等）。\nC3（建立）：运营人采取合理措施识别影响其运行的所有危险，包括特定于运行类型、运行环境和区域的危险。\nC4（建立）：运营人制定了根据ORG 3.1.4在正常航线运行期间系统获取和分析飞行机组表现观察数据的方案（例如LOSA），并从该方案中识别相关危险。\nC5（成熟）：运营人根据需要审查并持续改进其危险识别方案及相关流程。\nC6（成熟）：运营人通过行业报告、IATA和/或任何其他组织（包括当局）提供的趋势识别危险。\nC7（成熟）：根据ORG 4.3.1要求的SMS培训包括深入的危險识别部分和带有实际示例的详细培训材料。\nC8（成熟）：运行经理熟悉其运行区域内识别的危险，并积极促进和鼓励所有运行人员识别航空器运行的危险。\nC9（成熟）：通过定期安全文化调查（例如I-ASC：IATA航空安全文化调查）识别危险。\nC10（领先）：运营人部署全面的、基于技术的危险识别流程，例如使用人工智能，以促进危险识别过程。\nC11（领先）：运营人与行业组织、机构和/或团体共享和/或基准测试其危险，以促进危险识别的全球发展。\nC12（领先）：与反应式方法相比，通过主动式方法识别的危险比例显著更高。" },
            { subtitle: "ORG 3.1.2 运行安全报告系统", eng: "The Operator shall have an operational safety reporting system that is implemented throughout the organization in a manner that:\n(i) Encourages and facilitates personnel to submit reports that identify safety hazards, expose safety deficiencies and raise safety concerns;\n(ii) Ensures mandatory reporting in accordance with applicable regulations;\n(iii) Includes analysis and management action as necessary to address safety issues identified through the reporting system. [SMS] [MA] (GM) ►\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed organizational operational safety reporting system (focus: system urges/facilitates reporting of hazards/safety concerns; includes analysis/action to validate/address reported hazards/safety concerns).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined records of selected operational/safety reports (focus: analysis/follow-up to identify/address reported hazards/safety concerns).\n▪ Coordinated to verify implementation of operational safety reporting system in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nSafety reporting is a key aspect of SMS hazard identification and risk management.\nFrontline personnel, such as flight or cabin crew members and maintenance technicians, are exposed to hazards and face challenging situations as part of their everyday activities. An operational reporting system provides such personnel with a means to report these hazards or any other safety concerns so they may be brought to the attention of relevant managers.\nAn effective system provides for a review and analysis of each report to determine whether a real safety issue exists, and if so, ensure development and implementation of appropriate action by responsible management to correct the situation.\nRefer to ORG 1.2.2, which specifies a corporate safety reporting policy and addresses the importance of having an effective reporting culture to ensure the proactive identification of potential safety deficiencies.\nRefer to the IAH for information that identifies repeats of this provision in other ISM sections.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: All relevant information and data originating from personnel within the organization is captured and channelled into the hazard identification and risk assessment programs.\nSuitability Considerations: • Number of reports based on size and complexity of the organization. • Means/tools to collect safety reports.\nC1 (Established): There is an effective confidential reporting system as per ORG 3.1.3 that encourages and facilitates the reporting of events, hazards and/or concerns resulting from or associated with human performance in operations.\nC2 (Established): Personnel that evaluate and process safety reports are appropriately trained and/or qualified.\nC3 (Established): All employees are familiar with the use of the safety reporting system.\nC4 (Mature): There is timely feedback to the reporter of any actions taken (or not taken) and, where appropriate, to the rest of the organisation.\nC5 (Mature): The reporting system is available for third parties (partners, suppliers, service providers and contractors).\nC6 (Mature): Hazards and safety issues are effectively identified through voluntary and mandatory operational safety reporting system.\nC7 (Mature): The reporting system is readily accessible by all personnel through an effective and user-friendly electronic system/database.\nC8 (Mature): Senior Management and operational managers are actively promoting voluntary reporting and continuously encourage all operational personnel.\nC9 (Leading): Reports of safety occurrences are submitted to IATA for inclusion in the Incident Data Exchange (IDX) as per ORG 2.4.3.\nC10 (Leading): The Operator provides incentives for and/or encourages individuals to report hazards and operational deficiencies.\nC11 (Leading): There is a healthy and effective voluntary reporting system based on the volume of reporting and the quality of reports received.\nC12 (Leading): All voluntary and mandatory safety reports are reliably evaluated and processed, consistently leading to meaningful actions/decisions.\nC13 (Leading): Personnel are reporting their own errors and mistakes.\nC14 (Leading): The reporting system is effectively being used by all employees throughout the organization in all operational areas.", zh: "运营人应建立一个运行安全报告系统，以以下方式在整个组织内实施：\n(i) 鼓励并便利人员提交识别安全危险、暴露安全缺陷和提出安全关切的报告；\n(ii) 确保根据适用法规进行强制报告；\n(iii) 包括必要的分析和管理行动，以处理通过报告系统识别的安全问题。[SMS] [MA] (GM) ►\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估组织运行安全报告系统（重点：系统敦促/便利报告危险/安全关切；包括分析/行动以验证/处理报告的危险/安全关切）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查选定的运行/安全报告记录（重点：分析/跟踪以识别/处理报告的危险/安全关切）\n▪ 协调验证所有运行领域运行安全报告系统的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n安全报告是SMS危险识别和风险管理的一个关键方面。\n一线人员，例如飞行或客舱机组成员以及维修技术人员，在日常活动中会暴露于危险并面临挑战性情况。运行报告系统为此类人员提供了一种报告这些危险或任何其他安全关切的手段，以便引起相关经理的注意。\n有效的系统规定对每份报告进行审查和分析，以确定是否存在真正的安全问题，如果存在，则确保负责管理层制定和实施适当的行动来纠正情况。\n参见ORG 1.2.2，其中规定了公司安全报告政策，并阐述了拥有有效报告文化以确保主动识别潜在安全缺陷的重要性。\n关于识别本条款在其他ISM部分中重复的信息，请参阅IAH。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：捕获来自组织内人员的所有相关信息和数据，并将其引导到危险识别和风险评估方案中。\n充分性考虑：• 基于组织规模和复杂性的报告数量。• 收集安全报告的手段/工具。\nC1（建立）：根据ORG 3.1.3有有效的保密报告系统，鼓励和便利报告由运行中人为表现引起或与之相关的事件、危险和/或关切。\nC2（建立）：评估和处理安全报告的人员经过适当的培训和/或资格认证。\nC3（建立）：所有员工都熟悉安全报告系统的使用。\nC4（成熟）：对报告人及时反馈所采取（或未采取）的任何行动，并酌情向组织的其他部分反馈。\nC5（成熟）：报告系统可供第三方（合作伙伴、供应商、服务提供商和承包商）使用。\nC6（成熟）：通过自愿和强制性运行安全报告系统有效识别危险和安全问题。\nC7（成熟）：所有人员通过有效且用户友好的电子系统/数据库可轻松访问报告系统。\nC8（成熟）：高级管理层和运行经理积极促进自愿报告，并持续鼓励所有运行人员。\nC9（领先）：根据ORG 2.4.3向IATA提交安全事件报告以纳入事件数据交换（IDX）。\nC10（领先）：运营人提供激励和/或鼓励个人报告危险和运行缺陷。\nC11（领先）：基于报告量和收到的报告质量，存在健康有效的自愿报告系统。\nC12（领先）：所有自愿和强制性安全报告都得到可靠评估和处理，始终导致有意义的行动/决策。\nC13（领先）：人员报告自己的错误和失误。\nC14（领先）：报告系统被整个组织所有运行领域的所有员工有效使用。" },
            { subtitle: "ORG 3.1.3 保密安全报告系统", eng: "The Operator should have a confidential safety reporting system that is implemented throughout the organization in a manner that encourages and facilitates the reporting of events, hazards and/or concerns resulting from or associated with human performance in operations. (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed organizational confidential safety reporting system (focus: system urges/facilitates reporting of events/hazards/safety concerns caused by humans; reporters are assured confidentiality; includes analysis/action to validate/address reported hazards/safety concerns).\n▪ Interviewed responsible management representative(s).\n▪ Examined records of selected confidential safety reports (focus: assurance of confidentiality, analysis/follow-up to identify/address reported hazards/safety concerns).\n▪ Crosschecked to verify implementation of confidential safety reporting system in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nThe specified confidential safety reporting system is sometimes referred to as a Confidential Human Factors (or Incident) Reporting System.\nThe success of a confidential safety reporting system depends on two fundamentals:\n• The ability of the organization to assure absolute protection of a report submitted by any individual;\n• The level to which individuals within the organization exercise their freedom to report actual or potential unsafe conditions or occurrences.\nIn certain states, information submitted under a pledge of confidentiality could be subject to laws protecting such information. Therefore, an operator would typically have procedures in place to protect report confidentiality (e.g. de-identification).\nThere is a difference between confidential reporting and anonymous reporting. Confidential reporting is the preferred system because it permits feedback to the reporter in response to the report. Not only is the reporter entitled to an explanation, but also such feedback provides excellent incentive for the submission of future reports.\nThe effectiveness of a confidential safety reporting system is determined by a basic requirement for safeguarding safety and risk information. Typically, individuals will continue to provide information only when there is confidence that such information will be used only for safety purposes and will never be compromised or used against them.\nAn effective confidential safety reporting system might typically include:\n• A process that provides absolute protection of confidentiality;\n• An articulated policy that encourages reporting of hazards and human errors in operations;\n• A shared responsibility between the individual flight and cabin crew members (or, if applicable, respective professional associations) and the organization to promote a confidential safety reporting system;\n• A tracking process of action taken in response to reports;\n• A process to provide feedback to the reporter;\n• A communication process for ensuring flight and cabin crew members, as well as other relevant personnel, are informed of potential operating hazards through dissemination of de-identified report information.", zh: "运营人应建立保密安全报告系统，以鼓励和便利报告由运行中的人为表现引起或与之相关的事件、危险和/或关切的方式在整个组织内实施。（推荐实践）(GM) ►\n\n审计员行动：\n▪ 识别/评估组织保密安全报告系统（重点：系统敦促/便利报告由人为引起的事件/危险/安全关切；向报告人保证保密性；包括分析/行动以验证/处理报告的危险/安全关切）\n▪ 访谈负责的管理代表\n▪ 检查选定的保密安全报告记录（重点：保密性保证、分析/跟踪以识别/处理报告的危险/安全关切）\n▪ 交叉检查以验证保密安全报告系统在所有运行领域的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n指定的保密安全报告系统有时称为保密人为因素（或事件）报告系统。\n保密安全报告系统的成功取决于两个基本要素：\n• 组织确保对任何个人提交的报告进行绝对保护的能力；\n• 组织内个人行使其报告实际或潜在不安全条件或事件的自由的程度。\n在某些国家，根据保密承诺提交的信息可能受到保护此类信息的法律的约束。因此，运营人通常会制定程序来保护报告机密性（例如去标识化）。\n保密报告和匿名报告之间存在差异。保密报告是首选系统，因为它允许向报告人提供对报告的反馈。报告人不仅有权获得解释，而且此类反馈为提交未来报告提供了极好的激励。\n保密安全报告系统的有效性取决于保护安全和风险信息的基本要求。通常，只有当个人确信此类信息将仅用于安全目的且永远不会被泄露或被用来对付他们时，他们才会继续提供信息。\n有效的保密安全报告系统通常包括：\n• 提供绝对保密保护的流程；\n• 鼓励报告运行中危险和人为错误的明确政策；\n• 个人飞行和客舱机组成员（或如适用，各自的专业协会）与组织之间促进保密安全报告系统的共同责任；\n• 对报告采取行动的跟踪流程；\n• 向报告人提供反馈的流程；\n• 通过传播去标识化的报告信息，确保飞行和客舱机组成员以及其他相关人员了解潜在运行危险的沟通流程。" },
            { subtitle: "ORG 3.1.4 航线运行监控方案", eng: "The Operator should have a program for the systematic acquisition and analysis of data from observations of flight crew performance during normal line operations. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed line operations monitoring program (focus: observations of flight crew performance on routine line flights; trained/qualified non-evaluation observers; acquisition/analysis of data from observations of identification of operational threats/errors/risk; production of data/recommendations used to mitigate risk).\n▪ Interviewed responsible manager(s).\n▪ Interviewed line operations observer(s) and data analyst(s).\n▪ Examined selected line monitoring program reports (focus: analysis of observation data; identification of flight safety hazards; recommendations to mitigate risk).\n▪ Other Actions (Specify)\n\nGuidance:\nIf implemented, line monitoring would be considered a proactive hazard identification activity in an SMS.\nA line operations monitoring program is a completely different activity from line evaluation (or line checking) of the flight crew. Line operations monitoring cannot be accomplished in conjunction with any type of operational evaluation of the flight crew.\nUnder this program, flight crew performance in a normal line environment is observed from the flight deck jump seat by individuals who have been specially selected and trained. Observers, with the cooperation of the flight crew, systematically gather operational data that can be analyzed and used to make real improvements to certain areas of the operation. Observers are particularly aware of, and record, threats and errors that occur in the operating environment.\nThe Line Operations Safety Audit (LOSA) is a well-known and successful example of a normal line operations monitoring program.\nAn acceptable program would have the following characteristics:\n• A planned and organized series of observations of flight crew performance during normal line flights is typically conducted a minimum of once during every four-year period.\n• Observations are conducted on regular and routine line flights, and the flight crew is advised and clearly understands that normal line monitoring is not an evaluating, training or checking activity. The flight crew would be expected to operate as if the observer were not there.\n• There is mutual support and cooperation from both the management of the operator and flight crew members (through their professional association, if applicable).\n• Participation from the flight crew is voluntary; observations are not conducted unless permission is received from the flight crew.\n• Data collected from observations are confidential, de-identified and used for safety enhancement purposes only. Data from an observation are never permitted to be used for disciplinary action unless there is evidence of willful misconduct or illegal activity.\n• Procedures are in place to ensure data from observations are retained in a way that ensures effective security.\n• Objectives of observations are clearly defined, and collected data are always used to address specific issues that affect flight safety.\n• Observers are specifically selected and trained (calibrated) to ensure a high level of consistency and standardization in the data being collected. Observers are objective, impartial and have a high level of integrity.\n• There is a process in place to ensure data collected from observations are subjected to analysis from appropriately diverse subject matter experts to ensure consistency and accuracy.\n• Data derived from observations are analyzed and presented in a manner that identifies potential weakness and permits the operator to develop appropriate action(s) that will enhance specific aspects of the operation.\n• Results from the monitoring program, including the corrective action plan, are communicated to flight crew members.\nExpanded guidance may be found in the ICAO SMM, Document 9859.", zh: "运营人应制定方案，用于系统性地获取和分析正常航线运行期间飞行机组表现的观察数据。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估航线运行监控方案（重点：常规航线航班上飞行机组表现的观察；经过培训/合格的、非评估目的的观察员；获取/分析观察数据以识别运行威胁/错误/风险；生成用于缓解风险的数据/建议）\n▪ 访谈负责经理\n▪ 访谈航线运行观察员和数据分析员\n▪ 检查选定的航线监控方案报告（重点：观察数据分析；飞行安全危险识别；缓解风险的建议）\n▪ 其他行动（请说明）\n\n指导材料：\n如果实施，航线监控将被视为SMS中的主动式危险识别活动。\n航线运行监控方案与飞行机组的航线评估（或航线检查）是完全不同的活动。航线运行监控不能与任何类型的飞行机组运行评估同时进行。\n在该方案下，由经过特别选拔和培训的个人从驾驶舱折叠座椅观察正常航线环境中的飞行机组表现。观察员在飞行机组的配合下，系统地收集运行数据，这些数据可以被分析并用于对运行的某些领域进行实际改进。观察员特别关注并记录运行环境中发生的威胁和错误。\n航线运行安全审计（LOSA）是正常航线运行监控方案的一个著名且成功的示例。\n可接受的方案应具有以下特征：\n• 通常每四年期间至少进行一次计划和组织良好的正常航线航班飞行机组表现观察系列。\n• 观察在常规和例行航线航班上进行，飞行机组被告知并清楚理解正常航线监控不是评估、培训或检查活动。期望飞行机组像观察员不在场一样操作。\n• 运营人管理层与飞行机组成员（通过其专业协会，如适用）之间相互支持与合作。\n• 飞行机组的参与是自愿的；除非获得飞行机组的许可，否则不进行观察。\n• 从观察中收集的数据是保密的、去标识化的，仅用于安全改进目的。绝不允许将观察数据用于纪律处分，除非有故意不当行为或非法活动的证据。\n• 制定程序以确保观察数据以有效安全的方式保留。\n• 观察目标明确定义，收集的数据始终用于解决影响飞行安全的具体问题。\n• 观察员经过特别选拔和培训（校准），以确保所收集数据的高度一致性和标准化。观察员客观、公正并具有高度的诚信。\n• 制定流程以确保从观察中收集的数据由适当多样的主题专家进行分析，以确保一致性和准确性。\n• 从观察中获得的数据以识别潜在弱点并允许运营人制定适当的行动来增强运行特定方面的方式进行分析和呈现。\n• 监控方案的结果，包括纠正措施计划，传达给飞行机组成员。\n扩展指导可参见ICAO SMM，文件9859。" },
            { subtitle: "ORG 3.1.5 变更管理", eng: "The Operator shall have a process to identify changes within or external to the organization that have the potential to affect the level of safety risks associated with aircraft operations, and to manage risks that may arise from or are affected by such changes in accordance with ORG 3.1.1 and ORG 3.2.1. [SMS] [MA] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed organizational change management process (focus: process identifies/assesses internal/external changes to determine operational safety risk).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected records/documents that show processing of internal/external changes (focus: assessment of changes to determine safety risk; actions taken to implement/revise new/existing risk controls).\n▪ Coordinated to verify implementation of change management process in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Change Management.\nChange management is an element of the Safety Assurance component of the SMS framework and is considered a proactive hazard identification activity in an SMS.\nSafety risk management requires an operator to have a formal process to identify hazards that may affect aircraft operations. Hazards may exist in ongoing aircraft operations or be inadvertently introduced whenever internal or external changes occur that could affect aircraft operations. In such cases, hazard identification as specified in ORG 3.1.1 and safety risk assessment and mitigation as specified in ORG 3.1.2 (both are repeated in other ISM sections) are integral elements of an operator's change management process.\nA change management process is normally designed to ensure risk management is applied to any internal or external change that has the potential to affect an operator's established operational processes, procedures, products, equipment and services. The change management process typically takes into account the following three considerations:\n• Criticality. Criticality assessments determine the systems, equipment or activities that are essential to the safe operation of aircraft. While criticality is normally assessed during the system design process, it is also relevant during a situation of change. Systems, equipment and activities that have higher safety criticality are reviewed following change to make sure that corrective actions can be taken to control potentially emerging safety risks.\n• Stability of systems and operational environments. Changes might be planned and under the direct control of the operator. Examples of such changes include organizational growth or contraction, the expansion of products or services delivered, or the introduction of new technologies. Changes might also be unplanned and external to the operator, such as changing economic cycles, labor unrest and changes to the political, regulatory or operating environments.\n• Past performance. Past performance of critical systems and trend analyses in the safety assurance process is typically employed to anticipate and monitor safety performance under situations of change. The monitoring of past performance will also assure the effectiveness of corrective actions taken to address safety deficiencies identified as a result of audits, evaluations, investigations or reports.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: The safety risks associated with aircraft operations that may arise or are affected by external or internal changes are managed and controlled to ensure they remain at an acceptable level. (Management of Change)\nSuitability Considerations: • Number and type of analyzed changes based on size and complexity of the organization\nC1 (Established): Operational managers are aware of changes within or external to the organization that have the potential to affect the level of safety risks associated with aircraft operations pertinent to their operational areas.\nC2 (Established): Multiple data and information sources are used to identify the changes that may impact the level of safety risks associated with aircraft operations.\nC3 (Established): Clear criteria are established, that define when a formal change management process must be applied.\nC4 (Established): The change management process considers interfaces with all affected departments to include as applicable external service providers.\nC5 (Mature): There is a clear change plan describing how it will be implemented and who will be responsible for which actions, and the sequencing and scheduling of each task.\nC6 (Mature): All relevant personnel involved in the change management process and associated activities are adequately trained in change management principles and the execution of the internal processes.\nC7 (Mature): The hazard identification process related to a change involves personnel with the right operational experience and expertise from all relevant areas within the organization in alignment with the complexity and nature of the change.\nC8 (Mature): The change management process is executed in a planned, timely, and consistent manner and includes regular updates and follow up action that ensures the change was implemented effectively.\nC9 (Mature): The change management process considers human factor issues.\nC10 (Leading): The change management process considers the accumulative effect of multiple changes.\nC11 (Leading): Any change managed by the Operator is proactively, timely and effectively communicated to all applicable stakeholders.\nC12 (Leading): The impact on existing safety risk controls that may be affected by a change is reviewed and all relevant necessary adjustments are made.\nC13 (Leading): All non-operational, business-related changes are considered for their potential to affect the level of safety risks associated with aircraft operations.\nC14 (Leading): All operational managers are aware of and involved with the change management process and use the methodology effectively for all changes.\nC15 (Leading): Risk control and mitigation strategies associated with changes are continuously monitored by the Operator for achievement of the planned effect for each change.\nC16 (Leading): The Operator involves external interfaces/organisations in the change management activities such as external service providers, ATCs, airport authorities, regulators, etc.", zh: "运营人应制定流程，识别组织内部或外部可能影响与航空器运行相关的安全风险水平的变更，并根据ORG 3.1.1和ORG 3.2.1管理可能由这些变更引起或受其影响的风险。[SMS] [MA] (GM)\n\n审计员行动：\n▪ 识别/评估组织变更管理流程（重点：流程识别/评估内部/外部变更以确定运行安全风险）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查显示内部/外部变更处理的选定记录/文件（重点：评估变更以确定安全风险；采取行动实施/修订新的/现有的风险控制）\n▪ 协调验证所有运行领域变更管理流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n变更管理的定义请参阅IRM。\n变更管理是SMS框架中安全保证组成部分的一个要素，被视为SMS中的主动式危险识别活动。\n安全风险管理要求运营人建立正式流程，以识别可能影响航空器运行的危险。危险可能存在于正在进行的航空器运行中，也可能在发生可能影响航空器运行的内部或外部变更时无意中被引入。在这种情况下，ORG 3.1.1中规定的危险识别和ORG 3.1.2中规定的安全风险评估与缓解（两者都在其他ISM部分中重复）是运营人变更管理流程的组成部分。\n变更管理流程通常设计为确保风险管理应用于任何可能影响运营人既定的运行流程、程序、产品、设备和服务的内部或外部变更。变更管理流程通常考虑以下三个因素：\n• 关键性。关键性评估确定对航空器安全运行至关重要的系统、设备或活动。虽然关键性通常在系统设计过程中评估，但它在变更情况下也相关。具有较高安全关键性的系统、设备和活动在变更后进行审查，以确保可以采取纠正措施来控制可能出现的新的安全风险。\n• 系统和运行环境的稳定性。变更可能是有计划的且在运营人的直接控制下。此类变更的示例包括组织增长或收缩、所交付产品或服务的扩展，或新技术的引入。变更也可能是计划外的且外部于运营人的，例如经济周期的变化、劳工动荡以及政治、监管或运行环境的变化。\n• 过去的表现。安全保证过程中关键系统的过去表现和趋势分析通常用于预测和监控变更情况下的安全绩效。对过去表现的监控也将确保为解决因审计、评估、调查或报告而识别的安全缺陷所采取的纠正措施的有效性。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：可能由外部或内部变更引起或受其影响的与航空器运行相关的安全风险得到管理和控制，以确保其保持在可接受水平。（变更管理）\n充分性考虑：• 基于组织规模和复杂性的分析变更数量和类型\nC1（建立）：运行经理意识到组织内部或外部可能影响其运行领域相关航空器运行安全风险水平的变更。\nC2（建立）：使用多个数据和信息来源来识别可能影响与航空器运行相关的安全风险水平的变更。\nC3（建立）：建立明确的标准，定义何时必须应用正式的变更管理流程。\nC4（建立）：变更管理流程考虑与所有受影响部门的接口，包括适用时的外部服务提供商。\nC5（成熟）：有清晰的变更计划，描述如何实施、谁负责哪些行动，以及每个任务的顺序和时间安排。\nC6（成熟）：参与变更管理流程和相关活动的所有相关人员都接受了变更管理原则和内部流程执行的充分培训。\nC7（成熟）：与变更相关的危险识别流程涉及来自组织内所有相关领域、具有适当运行经验和专业知识的人员，与变更的复杂性和性质相一致。\nC8（成熟）：变更管理流程以计划、及时和一致的方式执行，并包括定期更新和跟踪行动，以确保变更有效实施。\nC9（成熟）：变更管理流程考虑人为因素问题。\nC10（领先）：变更管理流程考虑多个变更的累积效应。\nC11（领先）：运营人管理的任何变更都主动、及时和有效地传达给所有适用的利益相关者。\nC12（领先）：审查可能受变更影响的现有安全风险控制的影响，并进行所有相关必要调整。\nC13（领先）：考虑所有非运行的、与业务相关的变更对与航空器运行相关的安全风险水平的潜在影响。\nC14（领先）：所有运行经理都了解并参与变更管理流程，并有效地对所有变更使用该方法。\nC15（领先）：运营人持续监控与变更相关的风险控制和缓解策略，以实现每个变更的计划效果。\nC16（领先）：运营人让外部接口/组织参与变更管理活动，例如外部服务提供商、ATC、机场当局、监管机构等。" }
        ]
    },
        risk_assessment: {
        title: "3.2 风险评估与缓解 - Risk Assessment and Mitigation",
        sections: [
            { subtitle: "ORG 3.2.1 安全风险评估与缓解方案", eng: "The Operator shall have a safety risk assessment and mitigation program that includes processes implemented and integrated throughout the organization to ensure:\n(i) Hazards are analyzed to determine corresponding safety risks to aircraft operations;\n(ii) Safety risks are assessed to determine the requirement for risk mitigation action(s);\n(iii) When required, risk mitigation actions are developed and implemented in operations. [SMS] [MA] (GM) ►\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed organizational safety risk assessment/mitigation program (focus: hazards analyzed to identify/define risk; risk assessed to determine appropriate action; action implemented/monitored to mitigate risk).\n▪ Identified/Assessed cross-discipline process for risk assessment/mitigation (focus: all operational disciplines participate in process).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected records/documents that illustrate organizational integration (focus: coordinated involvement of all operational disciplines in risk assessment/mitigation program).\n▪ Examined selected examples of risk assessment/risk mitigation action(s).\n▪ Coordinated to verify implementation of safety risk assessment/mitigation in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Risk Register, Safety Risk, Safety Risk Assessment (SRA), Safety Risk Management and Safety Risk Mitigation.\nRisk assessment and mitigation is an element of the Safety Risk Management component of the SMS framework.\nTo be completely effective, a risk assessment and mitigation program would typically be implemented in a manner that:\n• Is active in all areas of the organization where there is a potential for hazards that could affect aircraft operations;\n• Has some form of central coordination to ensure all existing or potential hazards that have been identified are subjected to risk assessment and, if applicable, mitigation.\nThe safety risks associated with an identified existing or potential hazard are assessed in the context of the potentially damaging consequences related to the hazard. Safety risks are generally expressed in two components:\n• Likelihood of an occurrence;\n• Severity of the consequence of an occurrence.\nTypically, matrices that quantify safety risk acceptance levels are developed to ensure standardization and consistency in the risk assessment process. Separate matrices with different risk acceptance criteria are sometimes used to address long-term versus short-term operations.\nA risk register is often employed for the purpose of documenting risk assessment information and monitoring risk mitigation (control) actions.\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: The Operator maintains an overview of its operational risks and through implementation of mitigation actions where required, and ensures risks are at an acceptable level.\nSuitability Considerations: • Software tools used for the program. • Number of individuals involved in the program. • Quantity and relevance of hazards and safety risks. • Adequacy/balance of risk assessments in light of nature/size/complexity of operations.\nC1 (Established): Risk register(s) comprehensively include(s) risk assessment information, risk mitigation (control) and monitoring actions across the entire organization.\nC2 (Established): The organisation takes reasonable steps to manage all applicable risks affecting its operations (considering aspects such as operation type, operational environment, and the region etc.).\nC3 (Established): Matrices which define safety risk tolerability are based on clear criteria, suitable to the operator's size and complexity, to ensure consistency and standardization in the risk assessment process.\nC4 (Established): The Operator defines and adheres to timelines for analyzing hazards, to determine corresponding safety risks.\nC5 (Established): The risk assessment and mitigation program is centrally coordinated to ensure existing or potential interdisciplinary hazards, correlated risks and mitigations are harmonized.\nC6 (Mature): The Operator has an electronic database to ensure effective management of data derived from the hazard identification, risk assessment and mitigation programs as per ORG 2.4.2.\nC7 (Mature): Risk mitigation (control) actions include timelines, allocation of responsibilities and risk control strategies (e.g. hazard elimination, risk avoidance, risk acceptance, risk mitigation) to reduce the risk to a level as defined by the operator.\nC8 (Mature): The risk assessment process involves relevant operational personnel and/or subject matter experts in determining appropriate mitigating actions.\nC9 (Mature): Significant global and/or regional industry high priority risks (e.g. identified by the IATA Safety Issue Hub or equivalent), as applicable, are monitored through the Operator's safety risk assessment/mitigation program and managed effectively.\nC10 (Mature): All mitigating actions are practical, sustainable and consider human factors limitations where applicable.\nC11 (Mature): Methods used for risk assessment such as Classic Risk Matrix (Likelihood vs. Severity) and/or Event Risk Classification (ERC)/Safety Issue Risk Assessment (SIRA) are customized to the Operator's complexity and operational environment and effectively used.\nC12 (Leading): All personnel performing risk assessments are specifically trained and/or qualified in risk assessment techniques.\nC13 (Leading): The Operator has a good understanding of interface management and interface hazards/risks related to external organizations such as service providers, ATCs, airport authorities, regulators are effectively identified and acted upon.\nC14 (Leading): The Operator shares its issues, hazards and/or associated risks regularly with the industry through the IATA Safety Issue Hub or other industry issue/hazard/risk benchmarking initiatives.\nC15 (Leading): Operational Managers and Senior Management throughout the organisation are aware and understand the risks related to their responsibilities and are continuously looking for and identifying new hazards and associated risks.\nC16 (Leading): The Operator has an effectively implemented process for safety data analysis with the purpose of predicting future risks associated with hazards to aircraft operations as per ORG 3.2.2.\nC17 (Leading): The risk assessment process and historical risk assessments are reviewed regularly for consistency and to identify improvements in the processes.", zh: "运营人应制定安全风险评估与缓解方案，包括在整个组织内实施和整合的流程，以确保：\n(i) 分析危险以确定对航空器运行的相应安全风险；\n(ii) 评估安全风险以确定是否需要采取风险缓解行动；\n(iii) 在需要时，制定风险缓解措施并在运行中实施。[SMS] [MA] (GM) ►\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估组织安全风险评估/缓解方案（重点：分析危险以识别/定义风险；评估风险以确定适当行动；实施/监控行动以缓解风险）\n▪ 识别/评估风险评估/缓解的跨学科流程（重点：所有运行学科参与流程）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查说明组织整合的选定记录/文件（重点：所有运行学科协调参与风险评估/缓解方案）\n▪ 检查风险评估/风险缓解行动的选定示例\n▪ 协调验证所有运行领域安全风险评估/缓解的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n风险登记册、安全风险、安全风险评估、安全风险管理和安全风险缓解的定义请参阅IRM。\n风险评估与缓解是SMS框架中安全风险管理组成部分的一个要素。\n为了完全有效，风险评估和缓解方案通常以以下方式实施：\n• 在组织内所有可能存在影响航空器运行危险的领域活跃；\n• 具有某种形式的中央协调，以确保所有已识别的现有或潜在危险都接受风险评估，并在适用的情况下进行缓解。\n与已识别的现有或潜在危险相关的安全风险在与危险相关的潜在破坏性后果的背景下进行评估。安全风险通常由两个组成部分表达：\n• 事件发生的可能性；\n• 事件后果的严重性。\n通常，制定量化安全风险可接受水平的矩阵以确保风险评估过程的标准化和一致性。有时使用具有不同风险接受标准的单独矩阵来处理长期与短期运行。\n通常使用风险登记册来记录风险评估信息和监控风险缓解（控制）行动。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：运营人保持对其运行风险的概览，并在需要时通过实施缓解措施，确保风险处于可接受水平。\n充分性考虑：• 方案使用的软件工具。• 参与方案的人员数量。• 危险和安全风险的数量和相关性。• 根据运行的性质/规模/复杂性，风险评估的充分性/平衡性。\nC1（建立）：风险登记册全面包括整个组织的风险评估信息、风险缓解（控制）和监控行动。\nC2（建立）：组织采取合理措施管理影响其运行的所有适用风险（考虑运行类型、运行环境和区域等方面）。\nC3（建立）：定义安全风险可容忍性的矩阵基于明确的标准，适合运营人的规模和复杂性，以确保风险评估过程的一致性和标准化。\nC4（建立）：运营人定义并遵守分析危险以确定相应安全风险的时间表。\nC5（建立）：风险评估和缓解方案集中协调，以确保现有或潜在的跨学科危险、相关风险和缓解措施得到协调统一。\nC6（成熟）：运营人拥有电子数据库，以确保根据ORG 2.4.2有效管理来自危险识别、风险评估和缓解方案的数据。\nC7（成熟）：风险缓解（控制）行动包括时间表、责任分配和风险控制策略（例如危险消除、风险规避、风险接受、风险缓解），以将风险降低到运营人定义的水平。\nC8（成熟）：风险评估过程涉及相关运行人员和/或主题专家确定适当的缓解措施。\nC9（成熟）：重大的全球和/或区域行业高优先级风险（例如由IATA安全问题中心或等效机构识别的），如适用，通过运营人的安全风险评估/缓解方案进行监控并有效管理。\nC10（成熟）：所有缓解措施都是实用的、可持续的，并在适用时考虑人为因素限制。\nC11（成熟）：用于风险评估的方法，如经典风险矩阵（可能性与严重性）和/或事件风险分类（ERC）/安全问题风险评估（SIRA），根据运营人的复杂性和运行环境进行定制并有效使用。\nC12（领先）：所有执行风险评估的人员都接受了风险评估技术的专门培训和/或资格认证。\nC13（领先）：运营人对外部组织（如服务提供商、ATC、机场当局、监管机构）相关的接口管理和接口危险/风险有很好的理解，并有效识别和采取行动。\nC14（领先）：运营人通过IATA安全问题中心或其他行业问题/危险/风险基准测试计划定期与行业分享其问题、危险和/或相关风险。\nC15（领先）：整个组织的运行经理和高级管理层了解并理解与其职责相关的风险，并持续寻找和识别新的危险和相关风险。\nC16（领先）：运营人根据ORG 3.2.2有效实施了安全数据分析流程，以预测与航空器运行危险相关的未来风险。\nC17（领先）：定期审查风险评估过程和历史风险评估的一致性，并识别流程中的改进。" },
            { subtitle: "ORG 3.2.2 安全数据分析预测", eng: "The Operator should have a process for safety data analysis with the purpose of predicting future risks associated with hazards to aircraft operations. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed organizational safety risk assessment/mitigation program (focus: process for analysis of safety data to predict future risks).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected results of data analysis performed to predict future risks.\n▪ Examined examples of action(s) taken to address future risks identified from safety data analysis.\n▪ Other Actions (Specify)\n\nGuidance:\nThe analysis of safety data could include probability or predictive analytical methods whereby information is extracted from historical and current data and then used to predict trends and behaviour patterns. Patterns found in historical data can help identify emerging risks and opportunities. Whereas the unknown event of interest is in the future, predictive analysis can be applied to any type of unknown in the past, present or future. The core of predictive analysis relies on capturing relationships between variables from past occurrences and exploiting them to predict the unknown outcome. If electronic systems are used, they may allow users to model different scenarios of risks or opportunities with different outcomes. This enables decision makers to assess the decisions they can make in the face of different unknown circumstances and to evaluate how they can effectively allocate limited resources to areas where the highest risks or best opportunities exist.", zh: "运营人应建立安全数据分析流程，目的是预测与航空器运行危险相关的未来风险。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估组织安全风险评估/缓解方案（重点：分析安全数据以预测未来风险的流程）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查为预测未来风险而进行的数据分析的选定结果\n▪ 检查为解决从安全数据分析中识别的未来风险而采取的行动示例\n▪ 其他行动（请说明）\n\n指导材料：\n安全数据分析可以包括概率或预测性分析方法，从历史和当前数据中提取信息，然后用于预测趋势和行为模式。历史数据中发现的模式可以帮助识别新兴风险和机会。由于感兴趣的未知事件在未来，预测性分析可以应用于过去、现在或未来的任何类型的未知。预测性分析的核心依赖于从过去事件中捕获变量之间的关系，并利用它们来预测未知结果。如果使用电子系统，它们可能允许用户对不同结果的風險或机会情景进行建模。这使得决策者能够评估他们在不同的未知情况下可以做出的决策，并评估如何有效地将有限资源分配到存在最高风险或最佳机会的领域。" }
        ]
    },

        fda: {
        title: "3.3 飞行数据分析 - Flight Data Analysis (FDA)",
        sections: [
            { subtitle: "ORG 3.3.1 FDA方案要求", eng: "The Operator shall have a flight data analysis (FDA) program. The FDA program shall be non-punitive, be integrated in the Operator's SMS, and shall be applicable to aircraft as follows:\n(i) All aircraft with a maximum certificated take-off mass in excess of 27000 kg;\n(ii) All aircraft with a maximum certificated take-off mass in excess of 15000 kg, a passenger capacity greater than 19, and with a certificate of airworthiness first issued on or after 1 January 2027. [SMS] [MA] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed FDA program (focus: program is non-punitive and is applied to aircraft in the fleet with a MCTOM greater than 27 000 kg or 15 000 kg if applicable).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Interviewed FDA program manager.\n▪ Assessed processes/systems for download of electronically recorded flight data (focus: usable program data is downloaded from all applicable aircraft types in the operator's fleet).\n▪ Observed FDA program resources and activities.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Flight Data Analysis (FDA) Program.\nThe FDA program fits into the Safety Assurance (safety performance monitoring/measuring) and Safety Risk Management (hazard identification) components of the SMS framework.\nA systematic download and analysis of electronically recorded aircraft flight data would typically include:\n• Systems on applicable aircraft that:\n  – Capture flight data and permit rapid download through use of an optical disc/PC or equivalent, or\n  – Capture and automatically transmit encrypted aircraft data through a ground link to a ground station.\n• A ground system that transforms raw digital flight data into a usable form of information that can then be verified, processed and categorized for analysis;\n• One or more ground stations (usually a desk top computer loaded with the appropriate software) to permit the analysis of flight data to identify deviations from expected performance;\n• A secure database that protects and permits retention, retrieval and use of program data (e.g. data mining, research, event development).\nIn addition to the above, an FDA program might include optional flight animation software that provides a visual simulation of actual flight events.\nThe practice of analyzing recorded data from routine flight operations is a cornerstone in support of an operator's accident prevention programs. Rather than reacting to serious incidents, an effective FDA program enables a proactive identification of safety hazards associated with flight operations.\nAn FDA program is also used for:\n• Routine flight operational measurements;\n• Incident investigations;\n• As applicable, continuing airworthiness.\nA key element in developing an FDA program is gaining the support of flight crew members. Such support is typically achieved through a policy and/or procedures and a formal agreement that lays out the conditions for ensuring the program is non-punitive and downloaded flight data is de-identified and secure. If applicable, such policy and/or procedures would typically be set forth in a formal agreement with the association that represents flight crew members.\nIt is important that the FDA program clearly defines the meaning of a non-punitive environment and that relevant program participants, particularly flight crew members:\n• Have a clear understanding of the types of operational behaviors that are unacceptable, and the conditions under which disciplinary action would or would not apply.\n• Are provided with enough information about the process to ensure a perception of fair treatment in accordance with program policy and procedures.\n• Have confidence that non-punitive principles will be applied in the treatment of events identified under the FDA program.\nAn effective FDA program typically includes assurance that:\n• Flight data and other relevant information are analyzed thoroughly such that, as far as reasonably practicable, all relevant factors associated with an event are identified, not just the action or inaction of specific individuals.\n• Investigation of FDA events focuses on systemic issues that might influence behaviors, rather than on individual actions.\n• Individuals involved in the investigation of an event will be treated fairly based on the quality of their behavioral choices.\n• Factual details of an event are provided to relevant operational managers for an objective review of all factors involved.\nAll or certain specific elements of the FDA program might be outsourced to an external service provider; however, the operator would retain overall responsibility for the maintenance of the program.\nThe most comprehensive approach to flight data analysis would include not only the systematic download and analysis of recorded aircraft flight data, but also acquisition, correlation and analysis of other information derived from operational safety reports, regulatory authorities, investigative bodies, OEMs and other operators.\nFurther guidance may be found in the following source documents:\n• ICAO Doc 9859, Safety Management Manual, and ICAO Doc 10000, Manual on Flight Data Analysis Programmes (FDAP).\n• CASA CAAP SMS-4(0), Guidance on the establishment of a Flight Data Analysis Program (FDAP)–Safety Management Systems (SMS).\n• FAA Advisory Circular AC No: 120-82, Flight Operational Quality Assurance.\n• UK CAA CAP 739, Flight Data Monitoring.\nRefer to ORG 3.3.5, which addresses the integration of the FDA program in an operator's SMS.\n\nAssessment Tool\nDesired Outcome: To obtain an objective source of hazard identification through the routine collection and analysis of flight data.\nSuitability Considerations: • Software used for the program. • Number of individuals involved in the program. • Quantity and relevance of hazards and safety risks identified through the program.\nC1 (Established): A formal agreement lays out the program conditions to ensure it is non-punitive and downloaded flight data is de-identified and secure.\nC2 (Established): Personnel that provide interpretation and analysis of technical flight data have flight operations background that have an in-depth understanding of the Operator's aircraft types, operating procedures, routes and airports.\nC3 (Mature): Flight crew training material and/or scenarios are updated sporadically with inputs identified from the trend analysis of the FDA program.\nC4 (Mature): Investigation of FDA events focuses on systemic issues that might influence behaviours, rather than on individual actions.\nC5 (Mature): Flight crew has confidence in the FDA program and its non-punitive principles.\nC6 (Leading): Design and review of the FDA program consider information derived from operational safety reports, regulatory authorities, investigative bodies, OEMs and other operators as applicable.\nC7 (Leading): The Operator participates in and supplies data to an aggregated Flight Data Sharing Program, such as the IATA Flight Data Exchange (FDX).\nC8 (Leading): Flight crew training material and/or scenarios are continuously and effectively updated with the inputs identified from the trend analysis of the FDA Program.", zh: "运营人应制定飞行数据分析（FDA）方案。FDA方案应是非惩罚性的，应整合到运营人的SMS中，并应适用于以下飞机：\n(i) 所有最大认证起飞质量超过27,000公斤的飞机；\n(ii) 所有最大认证起飞质量超过15,000公斤、旅客座位数大于19且适航证首次签发日期为2027年1月1日或之后的飞机。[SMS] [MA] (GM)\n\n审计员行动：\n▪ 识别/评估FDA方案（重点：方案非惩罚性，适用于机队中MCTOM大于27,000公斤或15,000公斤（如适用）的飞机）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 访谈FDA方案经理\n▪ 评估下载电子记录飞行数据的流程/系统（重点：从运营人机队中所有适用机型下载可用的方案数据）\n▪ 观察FDA方案资源和活动\n▪ 其他行动（请说明）\n\n指导材料：\n飞行数据分析（FDA）方案的定义请参阅IRM。\nFDA方案适用于SMS框架中的安全保证（安全绩效监控/测量）和安全风险管理（危险识别）组成部分。\n系统性地下载和分析电子记录的飞机飞行数据通常包括：\n• 适用飞机上的系统：\n  – 捕获飞行数据并允许通过光盘/PC或等效设备快速下载，或\n  – 通过地面链路捕获并自动传输加密的飞机数据到地面站。\n• 将原始数字飞行数据转换为可用信息形式的地面系统，然后可以验证、处理和分类以进行分析；\n• 一个或多个地面站（通常是装有适当软件的台式计算机），用于分析飞行数据以识别与预期性能的偏差；\n• 保护并允许保留、检索和使用方案数据（例如数据挖掘、研究、事件开发）的安全数据库。\n除上述外，FDA方案可能包括可选的飞行动画软件，提供实际飞行事件的视觉模拟。\n分析常规飞行运行中记录的数据的做法是支持运营人事故预防计划的基石。有效的FDA方案不是对严重事件做出反应，而是能够主动识别与飞行运行相关的安全危险。\nFDA方案还用于：\n• 常规飞行运行测量；\n• 事件调查；\n• 如适用，持续适航。\n制定FDA方案的一个关键要素是获得飞行机组成员的支持。此类支持通常通过政策和/或程序以及规定确保方案非惩罚性、下载的飞行数据被去标识化和安全的条件的正式协议来实现。如适用，此类政策和/或程序通常在与代表飞行机组成员的协会签订的正式协议中规定。\n重要的是，FDA方案明确定义非惩罚性环境的含义，并且相关方案参与者，特别是飞行机组成员：\n• 清楚了解不可接受的运行行为类型，以及适用或不适用纪律处分的条件。\n• 获得关于流程的足够信息，以确保根据方案政策和程序获得公平对待的感受。\n• 相信非惩罚性原则将适用于处理FDA方案下识别的事件。\n有效的FDA方案通常包括以下保证：\n• 彻底分析飞行数据和其他相关信息，以便在合理可行的范围内，识别与事件相关的所有相关因素，而不仅仅是特定个人的作为或不作为。\n• 对FDA事件的调查侧重于可能影响行为的系统性问题，而不是个人行为。\n• 参与事件调查的个人将根据其行为选择的质量受到公平对待。\n• 向相关运行经理提供事件的事实细节，以便客观审查所有相关因素。\nFDA方案的全部或某些特定要素可能外包给外部服务提供商；然而，运营人将保留维护方案的总体责任。\n最全面的飞行数据分析方法不仅包括系统性地下载和分析记录的飞机飞行数据，还包括获取、关联和分析来自运行安全报告、监管当局、调查机构、OEM和其他运营人的其他信息。\n更多指导可在以下源文件中找到：\n• ICAO Doc 9859，安全管理手册，以及ICAO Doc 10000，飞行数据分析方案手册（FDAP）\n• CASA CAAP SMS-4(0)，飞行数据分析方案（FDAP）建立指南–安全管理体系（SMS）\n• FAA咨询通告AC No：120-82，飞行运行质量保证\n• UK CAA CAP 739，飞行数据监控\n参见ORG 3.3.5，该条款涉及FDA方案在运营人SMS中的整合。\n\n评估工具\n预期结果：通过常规收集和分析飞行数据获得危险的客观来源。\n充分性考虑：• 方案使用的软件。• 参与方案的人员数量。• 通过方案识别的危险和安全风险的数量和相关性。\nC1（建立）：正式协议规定了方案条件，以确保其非惩罚性，并且下载的飞行数据被去标识化且安全。\nC2（建立）：提供飞行技术数据解释和分析的人员具有飞行运行背景，对运营人的机型、操作程序、航线和机场有深入的了解。\nC3（成熟）：飞行机组培训材料和/或场景不定期更新，纳入从FDA方案趋势分析中识别的输入。\nC4（成熟）：对FDA事件的调查侧重于可能影响行为的系统性问题，而不是个人行为。\nC5（成熟）：飞行机组对FDA方案及其非惩罚性原则有信心。\nC6（领先）：FDA方案的设计和审查考虑来自运行安全报告、监管当局、调查机构、OEM和其他运营人（如适用）的信息。\nC7（领先）：运营人参与并向聚合飞行数据共享项目提供数据，例如IATA飞行数据交换（FDX）。\nC8（领先）：飞行机组培训材料和/或场景持续有效地更新，纳入从FDA方案趋势分析中识别的输入。" },
            { subtitle: "ORG 3.3.2 较低门槛FDA方案", eng: "The Operator should have a flight data analysis (FDA) program in accordance with ORG 3.3.1 that is applied to aircraft in its fleet with a certified takeoff mass in excess of 15 000 kg (33 069 lb). (GM)\n\nAuditor Actions:\n▪ Identified/Assessed FDA program (focus: program is non-punitive and is applied to aircraft in fleet with MCTOM greater than 15 000 kg).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Interviewed FDA program manager.\n▪ Assessed processes/systems for download of electronically recorded flight data (focus: usable data are downloaded from all applicable aircraft types in the operator's fleet).\n▪ Other Actions (Specify)\n\nGuidance:\nAn FDA program for aircraft with a certified takeoff mass in excess of 15 000 kg (33,069 lb) but less than 27,000 kg (59,525 lb), will typically contain processes and procedures as specified in ORG 3.3.3, 3.3.4 and 3.3.5.", zh: "运营人应根据ORG 3.3.1制定飞行数据分析（FDA）方案，适用于其机队中认证起飞质量超过15,000公斤（33,069磅）的飞机。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估FDA方案（重点：方案非惩罚性，适用于机队中MCTOM大于15,000公斤的飞机）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 访谈FDA方案经理\n▪ 评估下载电子记录飞行数据的流程/系统（重点：从运营人机队中所有适用机型下载可用数据）\n▪ 其他行动（请说明）\n\n指导材料：\n对于认证起飞质量超过15,000公斤（33,069磅）但低于27,000公斤（59,525磅）的飞机的FDA方案，通常将包含ORG 3.3.3、3.3.4和3.3.5中规定的流程和程序。" },
            { subtitle: "ORG 3.3.3 FDA方案流程", eng: "If the Operator has an FDA program in accordance with ORG 3.3.1, the Operator shall ensure such program has processes for:\n(i) Interpretation and analysis of flight and aircraft technical data;\n(ii) Flight crew liaison, including permission and responsibility for confidential discussions with flight crew members involved in events highlighted by FDA;\n(iii) Data collection that comprises data that are representative of all aircraft operations for each applicable fleet type;\n(iv) Dissemination of de-identified information to relevant operational personnel;\n(v) Training and qualification of personnel as appropriate to perform assigned program functions. (GM)\n\nAuditor Actions:\n▪ Identified FDA program processes (focus: program includes all required processes).\n▪ Interviewed FDA program manager.\n▪ Examined FDA program job descriptions (focus: tasks/qualifications appropriate for program functions performed).\n▪ Assessed processes for interpretation/analysis of flight/aircraft technical data (focus: data format and qualifications of personnel appropriate for interpretation/analysis of FDA data).\n▪ Identified flight crew liaison process.\n▪ Assessed data collection process(es) (focus: data collected is representative of all applicable aircraft operations).\n▪ Examined selected records that reflect FDA data dissemination.\n▪ Assessed training and qualification processes (focus: personnel are appropriately trained and qualified for program functions performed).\n▪ Other Actions (Specify)\n\nGuidance:\nResponsibilities within FDA program processes may be shared among individuals based on the size and complexity of an operator's organization.\nFDA program processes may be outsourced to external service providers, but the operator is always responsible for the performance of the program.\nThe intent of items (i) and (ii) is that functions in program processes are performed by personnel that have experience, skills and/or capabilities appropriate for the function(s) performed:\nPersonnel that provide interpretation and analysis of flight technical data are typically flight crew members that have an in-depth understanding of the operator's aircraft types, operating procedures, routes and airports.\nPersonnel that provide interpretation and analysis of aircraft technical data typically have maintenance engineering and/or appropriated maintenance technical experience and are familiar with the operator's power plant/structures/systems departments, information sources/requirements and engineering monitoring programs.\nPersonnel that perform flight crew liaison (i.e. the \"gatekeeper\" function) would typically have integrity, good judgement and the trust of both flight crew members and company management.\nThe intent of item (v) is a training and qualification program that ensures personnel are competent to perform assigned duties and functions within the FDA program. Personnel would typically complete initial training prior to the performance of any program functions and subsequent recurrent training to ensure continued competency.\nRefer to ORG 3.3.4, which addresses the management and protection of program data and information.", zh: "如果运营人有符合ORG 3.3.1的FDA方案，运营人应确保该方案具有以下流程：\n(i) 解释和分析飞行及飞机技术数据；\n(ii) 飞行机组联络，包括与FDA突出事件相关的飞行机组成员进行保密讨论的许可和责任；\n(iii) 数据收集，包括代表每个适用机型所有飞机运行的数据；\n(iv) 向相关运行人员传播去标识化信息；\n(v) 对人员进行适当培训并授予资格以执行分配的方案职能。(GM)\n\n审计员行动：\n▪ 识别FDA方案流程（重点：方案包括所有必需流程）\n▪ 访谈FDA方案经理\n▪ 检查FDA方案职位描述（重点：适合所执行方案职能的任务/资格）\n▪ 评估解释/分析飞行/飞机技术数据的流程（重点：数据格式和人员资格适合FDA数据的解释/分析）\n▪ 识别飞行机组联络流程\n▪ 评估数据收集流程（重点：收集的数据代表所有适用飞机运行）\n▪ 检查反映FDA数据传播的选定记录\n▪ 评估培训和资格流程（重点：人员经过适当培训并具备执行所执行方案职能的资格）\n▪ 其他行动（请说明）\n\n指导材料：\nFDA方案流程中的责任可以根据运营人组织的规模和复杂性在个人之间分担。\nFDA方案流程可能外包给外部服务提供商，但运营人始终对方案的执行负责。\n第(i)和(ii)项的意图是方案流程中的职能由具有适合所执行职能的经验、技能和/或能力的人员执行：\n提供飞行技术数据解释和分析的人员通常是飞行机组成员，他们对运营人的机型、操作程序、航线和机场有深入的了解。\n提供飞机技术数据解释和分析的人员通常具有维修工程和/或适当的维修技术经验，并熟悉运营人的动力装置/结构/系统部门、信息来源/要求和工程监控方案。\n执行飞行机组联络（即\"看门人\"职能）的人员通常具有诚信、良好的判断力以及飞行机组成员和公司管理层的信任。\n第(v)项的意图是培训和资格方案，确保人员有能力在FDA方案内执行分配的职责和职能。人员通常在执行任何方案职能之前完成初始培训，并随后进行复训以确保持续能力。\n参见ORG 3.3.4，该条款涉及方案数据和信息的管理和保护。" },
            { subtitle: "ORG 3.3.4 FDA数据管理标准", eng: "If the Operator has an FDA program in accordance with ORG 3.3.1, the Operator shall have standards for the management and protection of program data and information that define:\n(i) Methods for ensuring the integrity and validity of downloaded flight data;\n(ii) Policies and procedures for data de-identification and confidentiality;\n(iii) Methods for maintaining and presenting event and exceedance information for trend analysis;\n(iv) Policies and procedures for data retention, retrieval and archiving;\n(v) Processes for assessing and improving data management policies, methods and procedures. (GM).\n\nAuditor Actions:\n▪ Assessed FDA program data management/protection (focus: program standards define all aspects of management and protection of data).\n▪ Interviewed FDA program manager.\n▪ Examined selected records/examples of data management/protection (focus: policies/methods/procedures consistent with program standards for ensuring effective data management/protection).\n▪ Other Actions (Specify)\n\nGuidance:\nEffective management and protection of FDA program data and information is needed to ensure the success, and perhaps even the survival, of an FDA program.\nFDA data de-identification is a critical aspect of protection and therefore is normally well defined in program standards. The operator will typically provide a clear statement that assures the nondisclosure of flight crew individuals associated with or linked to FDA events, except when it can be determined there is an unacceptable safety risk if specific action regarding the flight crew is not taken.\nIn general, a successful FDA program requires the establishment of an acceptable level of trust between management and its flight crews. Therefore, the safety intent of the FDA program will be clearly documented so it is understood by all participants, and the conditions of use and protection of program data and information will be explicitly defined in a formal agreement involving the operator's management, representatives of its flight crews and the participating regulatory authority.\nMore detailed information regarding FDA program data management and protection may be found in the source documents referenced in the guidance associated with ORG 3.3.1.", zh: "如果运营人有符合ORG 3.3.1的FDA方案，运营人应制定方案数据和信息的管理和保护标准，定义：\n(i) 确保下载飞行数据完整性和有效性的方法；\n(ii) 数据去标识化和保密性的政策和程序；\n(iii) 维护和呈现事件及超限信息以进行趋势分析的方法；\n(iv) 数据保留、检索和存档的政策和程序；\n(v) 评估和改进数据管理政策、方法和程序的流程。(GM)\n\n审计员行动：\n▪ 评估FDA方案数据管理/保护（重点：方案标准定义数据管理和保护的各个方面）\n▪ 访谈FDA方案经理\n▪ 检查选定的数据管理/保护记录/示例（重点：政策/方法/程序与方案标准一致，确保有效的数据管理/保护）\n▪ 其他行动（请说明）\n\n指导材料：\n需要有效管理和保护FDA方案数据和信息，以确保FDA方案的成功甚至生存。\nFDA数据去标识化是保护的一个关键方面，因此通常在方案标准中有明确定义。运营人通常会提供明确的声明，保证不披露与FDA事件相关或关联的飞行机组成员身份，除非可以确定如果不针对飞行机组采取特定行动将存在不可接受的安全风险。\n总体而言，成功的FDA方案需要在管理层与其飞行机组之间建立可接受的信任水平。因此，FDA方案的安全意图将被清楚地记录，以便所有参与者理解，并且方案数据和信息的使用和保护条件将在涉及运营人管理层、其飞行机组代表和参与监管当局的正式协议中明确定义。\n关于FDA方案数据管理和保护的更详细信息可在ORG 3.3.1相关指导中引用的源文件中找到。" },
            { subtitle: "ORG 3.3.5 FDA与SMS整合", eng: "If the Operator has an FDA program in accordance with ORG 3.3.1, the Operator shall have processes to ensure program findings (e.g. hazards, adverse events and trends, airworthiness issues) are coordinated with relevant operational areas of the organization for further validation and assessment, and for a determination of appropriate follow-up action. Such coordination and follow-up action shall be accomplished within the SMS as follows:\n(i) Hazard identification and safety risk assessment and mitigation in accordance with ORG 3.1.1 and ORG 3.2.1.\n(ii) Event investigation in accordance with ORG 3.5.1 and ORG 3.5.2.\n(iii) Continuing airworthiness assessment in accordance with Maintenance Management Manual (MMM) procedures as specified in MNT 1.7.1 and Table 4.3. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed organizational safety risk assessment/mitigation program (focus: process for analysis of safety data to predict future risks).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected results of data analysis performed to predict future risks.\n▪ Examined examples of action(s) taken to address future risks identified from safety data analysis.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to standards in ICAO Annex 6, which specify an FDA program as part of an operator's SMS.\nThe primary aim of an FDA program is the continuous improvement of the operator's overall safety performance. Therefore, the FDA program, which functions to monitor and measure flight safety performance, is integrated in the Safety Assurance component of the operator's SMS.\nThe FDA program is also used for safety hazard identification and, as such, is integrated in the Risk Management component of the operator's SMS. Within an SMS there are typically multiple systems used as sources for hazard identification (e.g. accident/incident investigation, operational safety reporting, change management). Therefore, risk management processes are integrated in the operator's SMS to ensure an efficient use of resources and processes, and, where possible, to eliminate or reduce duplicated processes.\nRefer to ICAO Doc 9859, Safety Management Manual, and ICAO Doc 10000, Manual on Flight Data Analysis Programmes (FDAP), for more detailed information regarding integration of the FDA program into the operator's SMS.", zh: "如果运营人有符合ORG 3.3.1的FDA方案，运营人应制定流程，确保方案发现项（例如危险、不利事件和趋势、适航问题）与组织的相关运行领域协调，以进行进一步验证和评估，并确定适当的后续行动。此类协调和后续行动应在SMS内按以下方式完成：\n(i) 根据ORG 3.1.1和ORG 3.2.1进行危险识别和安全风险评估与缓解。\n(ii) 根据ORG 3.5.1和ORG 3.5.2进行事件调查。\n(iii) 根据MNT 1.7.1和表4.3中规定的维修管理手册（MMM）程序进行持续适航评估。(GM)\n\n审计员行动：\n▪ 识别/评估组织安全风险评估/缓解方案（重点：分析安全数据以预测未来风险的流程）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查为预测未来风险而进行的数据分析的选定结果\n▪ 检查为解决从安全数据分析中识别的未来风险而采取的行动示例\n▪ 其他行动（请说明）\n\n指导材料：\n参见ICAO附件6中的标准，该标准规定FDA方案作为运营人SMS的一部分。\nFDA方案的主要目标是持续改进运营人的整体安全绩效。因此，用于监控和测量飞行安全绩效的FDA方案被整合到运营人SMS的安全保证组成部分中。\nFDA方案也用于安全危险识别，因此被整合到运营人SMS的风险管理组成部分中。在SMS内，通常有多个系统用作危险识别的来源（例如事故/征候调查、运行安全报告、变更管理）。因此，风险管理流程被整合到运营人的SMS中，以确保资源和流程的有效利用，并在可能的情况下消除或减少重复流程。\n有关将FDA方案整合到运营人SMS中的更详细信息，请参见ICAO Doc 9859《安全管理手册》和ICAO Doc 10000《飞行数据分析方案手册》（FDAP）。" }
        ]
    },

        specific_risk: {
        title: "3.4 特定风险评估 - Specific Risk Assessments",
        sections: [
            { subtitle: "ORG 3.4.1 货舱物品运输风险评估", eng: "The Operator shall have a policy and procedures for the transport of items in the cargo compartment, which include the conduct of a specific safety risk assessment. Such risk assessment shall, as a minimum, include consideration of the following factors:\n(i) Hazards associated with the properties of the items to be transported;\n(ii) Capabilities of the operator;\n(iii) Operational considerations (e.g. area of operations, diversion time);\n(iv) Capabilities of the aircraft and its systems (e.g. cargo compartment fire suppression capabilities);\n(v) Containment characteristics of unit load devices;\n(vi) Packing and packaging;\n(vii) Safety of the supply chain for items to be transported;\n(viii) Quantity and distribution of dangerous goods items to be transported. (GM)\n\nNote: Mitigation resulting from the safety risk assessment shall ensure, to an acceptable level of risk, that in the event of a fire involving items in the cargo compartment, such fire will be detected and sufficiently suppressed or contained by the aircraft cargo compartment fire protection system until a safe landing can be made.\n\nAuditor Actions:\n▪ Identified/Assessed policy and procedures for the transport of items in the cargo compartment: (focus: policy and procedures include safety risk assessment for all items).\n▪ Identified/Assessed process for risk assessment/mitigation (focus: includes involvement of applicable operational disciplines; assessment considers all specified factors; mitigation measures are developed).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined records/documents that illustrate the safety risk assessment process for selected cargo compartment items (focus: all applicable disciplines involved; all specified factors considered; risk mitigation measures developed and integrated in the appropriate operational disciplines).\n▪ Coordinated to verify safety risk mitigation measures for items are implemented in the appropriate operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of COMAT (Company Material).\nThe intent of this provision is the management of risks associated with the transport of items that, either individually or collectively, might produce a fire that could exceed the cargo compartment fire suppression capabilities demonstrated during aircraft certification (e.g. lithium batteries).\nThe term 'items' as specified in this provision includes all of the following:\n• Cargo (including COMAT and stores);\n• Passenger and crew checked baggage;\n• Mail;\n• Onboard equipment used in the transport of cargo, baggage, or mail (e.g. unit load devices).\nThe safety risk assessment specified in this provision is not intended to be conducted by the operator on a flight-by-flight basis, but rather conducted initially to establish a baseline risk rating for all types of items that might be transported in the cargo compartment of aircraft during normal operations.\nItems as defined in this standard can be grouped based on the identified risk of a fire. Based on such a grouping, one item could be considered to be \"General Cargo\", or \"Passenger Baggage\", rather than an individual assessment of each item that could be part of a general cargo shipment. Items subject to prescriptive packing standards, such as dangerous goods, would not need to be individually assessed as long as transported in accordance with all required standards. An assessment would ideally be made if a defined baseline quantity or combination of dangerous goods will be surpassed.\nIf an operator deviates from the operations that defined the initial risk assessment, then such assessment would be revisited or updated to ensure new hazards have not been introduced by the change in operations. And, even if there are no changes to operations, the risk assessment would be revisited periodically as part of the operator's overall safety management activities to proactively mitigate safety risks before they result in an accident or serious incident.\nThe type of goods that an operator routinely accepts for transport can directly affect the considerations for hazard identification. For example, an operator that primarily transports live animals and perishables (e.g. flowers, fresh food) could reasonably conclude that the risk of a fire, which is a possible consequence of some hazards, is lower than the transport of general cargo. Likewise, the transport of cargo that is itself a potential ignition source would pose a higher risk of fire than the transport of general cargo.\nOperators carrying COMAT would have procedures that control the type, quantity, and packaging of such items to be transported. Special procedures, similar to those required for special cargo, would be needed to transport some items of COMAT.\nAs specified in item (vii), a safety risk assessment would consider the possibility of hazards that might result from or be associated with the supply chain of items that will be transported in the cargo compartment of the operator's aircraft. The process of moving items from origin to destination (i.e. the supply chain) is often very complex. Items might be handled by different entities with varying responsibilities (e.g. shippers, postal operators, freight forwarders, ground handlers, air operators) and could include different modes of transport (e.g. sea, road, rail) as well as different flights. In addition, there could be regional variances in performance that raise the hazard probability. Therefore, to identify the probability of hazards associated with the supply chain process, an operator might consider an analysis of data that can indicate the possibility of any of the following:\n• Damage to items through any part of the supply chain;\n• Shippers deliberately or unintentionally offering dangerous goods for transport without declaring them;\n• Shippers improperly classifying, packing, marking or labelling dangerous goods;\n• Freight forwarders accepting undeclared dangerous goods from shippers;\n• Dangerous goods prohibited in the mail;\n• Passengers carrying prohibited dangerous goods in baggage.\nIt is the responsibility of the aircraft design approval holders to provide core technical information to operators regarding the technical capabilities of the elements of the aircraft related to fire detection and suppression/extinguishing as required by the applicable certification requirements. The operator can conduct an effective safety risk assessment on the transport of items in a cargo compartment only if there is a full understanding of the performance capability of the cargo compartment systems, as well as the overall aircraft systems, to handle any identified hazard associated with a particular item.\nMore detailed information may be found in ICAO Doc 10102, Guidance for Safe Operations Involving Aeroplane Cargo Compartments.", zh: "运营人应制定货舱物品运输的政策和程序，包括进行特定的安全风险评估。该风险评估至少应考虑以下因素：\n(i) 与待运输物品特性相关的危险；\n(ii) 运营人的能力；\n(iii) 运行考虑因素（例如运行区域、备降时间）；\n(iv) 飞机及其系统的能力（例如货舱灭火能力）；\n(v) 集装设备的包容特性；\n(vi) 包装；\n(vii) 待运输物品供应链的安全性；\n(viii) 待运输危险品的数量和分布。(GM)\n\n注：安全风险评估产生的缓解措施应确保在可接受的风险水平下，如果货舱内物品发生火灾，该火灾将被探测到，并由飞机货舱防火系统充分抑制或控制，直到能够安全着陆。\n\n审计员行动：\n▪ 识别/评估货舱物品运输的政策和程序（重点：政策和程序包括对所有物品的安全风险评估）\n▪ 识别/评估风险评估/缓解流程（重点：包括适用运行学科的参与；评估考虑所有指定因素；制定缓解措施）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查说明选定货舱物品安全风险评估过程的记录/文件（重点：所有适用学科参与；考虑所有指定因素；制定风险缓解措施并整合到适当的运行学科中）\n▪ 协调验证物品的安全风险缓解措施在适当的运行领域实施\n▪ 其他行动（请说明）\n\n指导材料：\n公司物料（COMAT）的定义请参阅IRM。\n本条款的意图是管理与运输物品相关的风险，这些物品单独或 collectively 可能产生超出飞机认证期间展示的货舱灭火能力的火灾（例如锂电池）。\n本条款中规定的\"物品\"一词包括以下所有内容：\n• 货物（包括COMAT和航材）；\n• 旅客和机组托运行李；\n• 邮件；\n• 用于运输货物、行李或邮件的机上设备（例如集装设备）。\n本条款规定的安全风险评估并非要求运营人逐班进行，而是初步进行以建立正常运行期间可能在飞机货舱中运输的所有类型物品的基准风险评级。\n本标准中定义的物品可以根据已识别的火灾风险进行分组。基于这样的分组，一个物品可以被视为\"普通货物\"或\"旅客行李\"，而不是对可能是普通货物运输一部分的每个物品进行单独评估。受规定包装标准约束的物品（例如危险品）只要按照所有要求标准运输，就不需要单独评估。如果超过规定的基准数量或危险品组合，理想情况下应进行评估。\n如果运营人偏离定义了初始风险评估的运行，则应重新审视或更新该评估，以确保运行变更没有引入新的危险。并且，即使运行没有变化，也应定期重新审视风险评估，作为运营人整体安全管理活动的一部分，以在安全风险导致事故或严重事件之前主动缓解。\n运营人常规接受运输的货物类型可能直接影响危险识别的考虑因素。例如，主要运输活体动物和易腐物品（例如鲜花、新鲜食品）的运营人可以合理得出结论，火灾风险（某些危险的可能后果）低于普通货物运输。同样，运输本身就是潜在点火源的货物将比普通货物运输带来更高的火灾风险。\n运输COMAT的运营人将制定控制待运输此类物品的类型、数量和包装的程序。运输某些COMAT物品需要特殊的程序，类似于特殊货物所需的程序。\n如第(vii)项所述，安全风险评估将考虑可能由运营人飞机货舱中运输的物品供应链引起或与之相关的危险的可能性。将物品从原产地运送到目的地的过程（即供应链）通常非常复杂。物品可能由具有不同职责的不同实体处理（例如托运人、邮政运营商、货运代理、地面操作商、航空运营人），并可能包括不同的运输方式（例如海运、公路、铁路）以及不同的航班。此外，绩效可能存在区域差异，从而增加危险概率。因此，为了识别与供应链过程相关的危险概率，运营人可以考虑分析数据，这些数据可以指示以下任何情况的可能性：\n• 通过供应链任何部分对物品的损坏；\n• 托运人故意或无意地提供未申报的危险品进行运输；\n• 托运人不正确地分类、包装、标记或 labeling 危险品；\n• 货运代理接受托运人未申报的危险品；\n• 邮件中禁止的危险品；\n• 旅客在行李中携带禁止的危险品。\n飞机设计批准持有人有责任向运营人提供有关飞机元素在火灾探测和抑制/灭火方面的技术能力的核心技术信息，如适用认证要求所规定。只有全面了解货舱系统以及整个飞机系统处理与特定物品相关的任何已识别危险的性能能力，运营人才能对货舱中物品的运输进行有效的安全风险评估。\n更详细的信息可在ICAO Doc 10102《涉及飞机货舱的安全运行指南》中找到。" }
        ]
    },

        occurrence_handling: {
        title: "3.5 事件处理 - Occurrence Handling",
        sections: [
            { subtitle: "ORG 3.5.1 事故与征候调查", eng: "The Operator shall have a process for the investigation of aircraft accidents and incidents, to include reporting of events in accordance with requirements of the State. [SMS] [MA] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed accident investigation process (focus: process includes compliance with regulatory accident/incident reporting requirements; output includes final report with recommendations).\n▪ Interviewed responsible manager(s).\n▪ Examined selected accident and incident reports (focus: investigation identifies operational safety hazards, produces recommendations to prevent recurrence/mitigate risk).\n▪ Other Actions (Specify)\n\nGuidance:\nAccident and incident investigation is considered a reactive hazard identification activity in an SMS.\nA primary purpose of accident and incident investigation is hazard identification, which is an element of the Safety Risk Management component of the SMS framework.\nInvestigations typically result in a report that describes the factors that contributed to the event, which is then made available to responsible senior operational managers to permit them to evaluate and implement appropriate corrective or preventive action.\nAn effective investigation process typically includes:\n• Qualified personnel to conduct investigations (commensurate with operation size);\n• Procedures for the conduct of investigations;\n• A process for reporting investigative results;\n• A system for implementing any corrective or preventive action;\n• An interface with relevant external investigative authorities (when applicable);\n• A process for the dissemination of information derived from investigations.\nTo ensure awareness among operational personnel, information derived from investigations is disseminated to relevant areas throughout the organization.\nIn the event of a major accident, an operator responds to and possibly participates in an investigation in accordance with provisions contained in ICAO Annex 13. Such capability requires an operator to maintain an ongoing interface with relevant investigative authorities to ensure preparedness in the event a major accident occurs.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: Root cause(s) and new hazards and risks associated with the accident or incident are identified and a recurrence of the same or similar event is prevented.\nSuitability Considerations: • Scope and complexity of the process based on complexity of operation.\nC1 (Established): Investigations of aircraft accidents and incidents are carried out by adequate number of appropriately qualified and trained personnel as per clearly defined experience, skill, expertise and training requirements.\nC2 (Established): The Operator uses a structured decision-making approach with defined trigger points to identify what to investigate and the scope of the investigation.\nC3 (Established): The Operator has a comprehensive and effective process for the investigation of aircraft accidents and incident that includes: – a process for reporting investigative results, – a system for implementing and corrective or preventive action and – process for the dissemination of information derived from investigations.\nC4 (Mature): The Operator provides regular formal feedback to all relevant staff about the outcome of investigations of aircraft accidents and incidents.\nC5 (Mature): Investigations of aircraft accidents and incidents effectively identify human and organisational contributing factors.\nC6 (Mature): Lessons learned and contributing factors associated with accidents and serious incidents are regularly included in the safety training for all relevant operational personnel.\nC7 (Mature): New hazards and associated risks are identified through the analysis and/or investigation of Operator's accidents.\nC8 (Mature): Lead accident & incident investigators are independent from the area associated with the occurrence or identified hazard.\nC9 (Mature): Each investigation report has specific and meaningful findings, contributing factors and/or recommendations that intend to eliminate or mitigate safety deficiencies.\nC10 (Leading): New hazards and associated risks are identified through the analysis and/or investigation of Operator's accidents, serious incidents and near misses.\nC11 (Leading): Effective mitigating actions are applied with reference to the recommendations identified through internal safety investigations.\nC12 (Leading): Investigation reports are written in a manner to enhance/improve (non-blaming, constructive etc.) the safety culture of the organization, and the effectiveness of future safety initiatives.\nC13 (Leading): Operator uses Human Factor Analysis and Classification System (HFACS), Maintenance Error Decision Aid (MEDA) or similar Human Factors approach to effectively investigate accidents, serious incidents and errors in all operational areas.", zh: "运营人应制定航空器事故和征候调查流程，包括按照国家要求报告事件。[SMS] [MA] (GM)\n\n审计员行动：\n▪ 识别/评估事故调查流程（重点：流程包括遵守监管事故/征候报告要求；输出包括带有建议的最终报告）\n▪ 访谈负责经理\n▪ 检查选定的航空器事故和征候报告（重点：调查识别运行安全危险，提出防止再次发生/缓解风险的建议）\n▪ 其他行动（请说明）\n\n指导材料：\n事故和征候调查被视为SMS中的反应式危险识别活动。\n事故和征候调查的主要目的是危险识别，这是SMS框架中安全风险管理组成部分的一个要素。\n调查通常会形成一份描述导致事件的因素的报告，然后提供给负责的高级运行经理，以允许他们评估和实施适当的纠正或预防措施。\n有效的调查过程通常包括：\n• 有资格的人员进行调查（与运行规模相称）；\n• 进行调查的程序；\n• 报告调查结果的过程；\n• 实施任何纠正或预防措施的系统；\n• 与相关外部调查机构的接口（如适用）；\n• 传播从调查中获得的信息的过程。\n为了确保运行人员的意识，从调查中获得的信息会传播到整个组织的相关领域。\n在发生重大事故时，运营人根据ICAO附件13中的规定响应并可能参与调查。这种能力要求运营人与相关调查机构保持持续接口，以确保在发生重大事故时做好准备。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：识别与事故或征候相关的根本原因以及新的危险和风险，并防止相同或类似事件再次发生。\n充分性考虑：• 基于运行复杂性的流程范围和复杂性。\nC1（建立）：航空器事故和征候的调查由足够数量的、具有适当资格和培训的人员进行，符合明确定义的经验、技能、专业知识和培训要求。\nC2（建立）：运营人使用结构化的决策方法，具有定义的触发点来确定调查内容和范围。\nC3（建立）：运营人拥有全面有效的航空器事故和征候调查流程，包括：报告调查结果的流程、实施纠正或预防措施的系统、以及传播从调查中获得的信息的流程。\nC4（成熟）：运营人就航空器事故和征候调查的结果向所有相关人员提供定期正式反馈。\nC5（成熟）：航空器事故和征候的调查有效识别人为和组织促成因素。\nC6（成熟）：与事故和严重征候相关的经验教训和促成因素定期纳入所有相关运行人员的安全培训。\nC7（成熟）：通过分析和/或调查运营人的事故识别新的危险和相关风险。\nC8（成熟）：主要事故和征候调查员独立于与事件或已识别危险相关的领域。\nC9（成熟）：每份调查报告都有具体且有意义的发现、促成因素和/或建议，旨在消除或缓解安全缺陷。\nC10（领先）：通过分析和/或调查运营人的事故、严重征候和未遂事件识别新的危险和相关风险。\nC11（领先）：根据内部安全调查识别的建议采取有效的缓解措施。\nC12（领先）：调查报告的编写方式有助于增强/改善（非指责、建设性等）组织的安全文化以及未来安全倡议的有效性。\nC13（领先）：运营人使用人为因素分析和分类系统（HFACS）、维修错误决策辅助工具（MEDA）或类似的人为因素方法，有效调查所有运行领域的事故、严重征候和错误。" },
            { subtitle: "ORG 3.5.2 非正常事件调查", eng: "The Operator shall have a process for identifying and investigating irregularities and other non-routine operational occurrences that might be precursors to an aircraft accident or incident. [SMS] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed process for identification/investigation of irregularities/non-routine occurrences (focus: process output includes final report with recommendations).\n▪ Interviewed responsible manager(s).\n▪ Examined selected irregularity/non-routine occurrence reports (focus: process identifies operational safety hazards, produces recommendations to mitigate risk).\n▪ Other Actions (Specify)\n\nGuidance:\nInvestigation of operational irregularities is considered a reactive hazard identification activity in an SMS.\nA primary purpose of investigating non-routine operational occurrences is hazard identification, which is an element of the Safety Risk Management component of the SMS framework.\nThe investigation of irregularities or non-routine occurrences is a hazard identification activity. Minor events, irregularities and occurrences occur often during normal operations, many times without noticeable consequences. Identifying and investigating certain irregular operational occurrences can reveal system weaknesses or deficiencies that, if left un-checked, could eventually lead to an accident or serious incident. These types of events are referred to as accident precursors.\nA process to monitor operations on a regular basis permits the identification and capture of information associated with internal activities and events that could be considered precursors. Such events are then investigated to identify undesirable trends and determine contributory factors.\nThe monitoring process is typically not limited to occurrences, but also includes a regular review of operational threats and errors that have manifested during normal operations. Monitoring of normal operations can produce data that further serve to identify operational weaknesses and, in turn, assist the organization in developing system solutions.\nAs with the investigation of accidents and serious incidents, the investigation of minor internal occurrences results in a report that is communicated to relevant operational managers for analysis and the possible development of corrective or preventive action.\nExpanded guidance may be found in the ICAO SMM, Document 9859.", zh: "运营人应制定识别和调查可能成为航空器事故或征候前兆的不规范情况和其他非常规运行事件的流程。[SMS] (GM)\n\n审计员行动：\n▪ 识别/评估识别/调查不规范情况/非常规事件的流程（重点：流程输出包括带有建议的最终报告）\n▪ 访谈负责经理\n▪ 检查选定的不规范情况/非常规事件报告（重点：流程识别运行安全危险，提出缓解风险的建议）\n▪ 其他行动（请说明）\n\n指导材料：\n运行不规范情况的调查被视为SMS中的反应式危险识别活动。\n调查非常规运行事件的主要目的是危险识别，这是SMS框架中安全风险管理组成部分的一个要素。\n对不规范情况或非常规事件的调查是一种危险识别活动。在正常运行期间，小事件、不规范情况和事件经常发生，很多时候没有明显的后果。识别和调查某些不规范的运行事件可以揭示系统弱点或缺陷，如果不加检查，最终可能导致事故或严重事件。这些类型的事件被称为事故前兆。\n定期监控运行的过程允许识别和捕获与可能被视为前兆的内部活动和事件相关的信息。然后调查这些事件以识别不良趋势并确定促成因素。\n监控过程通常不限于事件，还包括定期审查正常运行中已显现的运行威胁和错误。对正常运行的监控可以产生数据，进一步用于识别运行弱点，进而帮助组织开发系统解决方案。\n与事故和严重事件的调查一样，对轻微内部事件的调查会产生一份报告，传达给相关运行经理进行分析，并可能制定纠正或预防措施。\n扩展指导可参见ICAO SMM，文件9859。" }
        ]
    },

        cybersecurity: {
        title: "3.6 网络安全风险管理 - Cybersecurity Risk Management",
        sections: [
            { subtitle: "ORG 3.6.1 关键系统网络安全保护", eng: "The Operator should ensure critical information and communications technology systems and data used in operations and maintenance functions are identified and, in accordance with risk management principles, appropriate measures are developed and implemented to protect them from unlawful interference. (GM)\n\nNote: Effective 1 January 2027, this Recommended Practice will be upgraded to a Standard; IOSA registration will require conformance by the Operator.\n\nAuditor Actions:\n▪ Identified/Assessed definition of critical information and communications technology systems and data.\n▪ Interviewed manager and/or designated management representative(s).\n▪ Examined selected records/documents that demonstrate application of the process.\n▪ Coordinated to verify implementation of process in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nThe protection of critical technology systems and data from unlawful interference will typically include a risk management process to ensure:\n• Critical information and communications technology systems and data used in operations and maintenance functions are identified;\n• Threats relevant to the identified assets are analyzed to determine corresponding risks to operations and maintenance functions;\n• Risks are assessed to determine, develop and implement the required risk mitigation measures or actions.\nExamples of communications technology systems and data used in operations and maintenance functions could include the following:\n• Flight planning/dispatch systems and data used to support it\n• Load control systems and data\n• Aircraft performance calculation systems and data\n• Reservation/DCS systems\n• Baggage reconciliation systems\n• EFB (Electronic Flight Bag)\n• Aircraft maintenance systems/MCS\n• Training and scheduling/rostering systems\n• Communication systems/ACARS\n• Navigation systems\nThe process of risk assessment, which is established at the operations life cycle and maintenance level, would include the following steps:\n• Define how to identify the risks that could cause the loss of confidentiality, integrity, and/or availability of your critical information and/or data.\n• Define how to identify the risk owners for each risk.\n• Define criteria for assessing consequences and assessing the likelihood of the occurrence.\n• Define how the risk will be calculated.\n• Define criteria for accepting risks.\n• Risk owners accept the residual risks and approve the risk treatment plan.\nThe identification and categorization of critical information and communications technology systems and data would be based on an impact analysis. Once this step is completed, each identified asset would go through the evaluation of threats against it, the development of security requirements and the selection of security controls that will protect it.\nThe selection of security controls, which support technical, operational and management security performance requirements and are within the confidentiality, integrity, and availability (CIA) context, would ideally follow relevant guidance where available.\nAfter implementation of the selected security controls, the operator would continue to assess cyber threats relative to the identified assets, determine any residual risks to aircraft operations and determine the need for additional mitigating actions to supplement or replace existing security controls.\nRefer to SEC 4.1.1 for expanded information related to cybersecurity and cybersecurity threats to civil aviation.", zh: "运营人应确保识别运行和维修职能中使用的关键信息和通信技术系统及数据，并根据风险管理原则，制定和实施适当的措施以保护它们免受非法干扰。(GM)（推荐实践）\n\n注：自2027年1月1日起，本推荐实践将升级为标准；IOSA注册将要求运营人符合。\n\n审计员行动：\n▪ 识别/评估关键信息和通信技术系统及数据的定义\n▪ 访谈经理和/或指定管理代表\n▪ 检查选定的证明流程应用的记录/文件\n▪ 协调验证所有运行领域流程的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n保护关键技术系统及数据免受非法干扰通常包括一个风险管理流程，以确保：\n• 识别运行和维修职能中使用的关键信息和通信技术系统及数据；\n• 分析与已识别资产相关的威胁，以确定对运行和维修职能的相应风险；\n• 评估风险以确定、制定和实施所需的风险缓解措施或行动。\n运行和维修职能中使用的通信技术系统和数据的示例可能包括以下内容：\n• 飞行计划/签派系统及支持其的数据\n• 载荷控制系统及数据\n• 飞机性能计算系统及数据\n• 预订/DCS系统\n• 行李核对系统\n• EFB（电子飞行包）\n• 飞机维修系统/MCS\n• 培训和排班/排班系统\n• 通信系统/ACARS\n• 导航系统\n风险评估过程建立在运行生命周期和维修层面，将包括以下步骤：\n• 定义如何识别可能导致您的关键信息和/或数据丢失机密性、完整性和/或可用性的风险。\n• 定义如何识别每个风险的风险所有者。\n• 定义评估后果和评估发生可能性的标准。\n• 定义如何计算风险。\n• 定义接受风险的标准。\n• 风险所有者接受残余风险并批准风险处理计划。\n关键信息和通信技术系统和数据的识别和分类将基于影响分析。完成此步骤后，每个已识别的资产将经历对其的威胁评估、安全要求的制定以及保护它的安全控制的选择。\n安全控制的选择支持技术、运行和管理安全绩效要求，并在机密性、完整性和可用性（CIA）范围内，理想情况下应遵循可用的相关指导。\n在实施选定的安全控制后，运营人将继续评估与已识别资产相关的网络威胁，确定对航空器运行的任何残余风险，并确定是否需要额外的缓解措施来补充或替换现有的安全控制。\n有关网络安全和民用航空网络安全威胁的扩展信息，请参阅SEC 4.1.1。" }
        ]
    },
    
    // ==================== 第四部分：改进与促进、培训 ====================
        mgmt_review: {
        title: "4.1 管理评审 - Management Review",
        sections: [
            { subtitle: "ORG 4.1.1 管理评审流程", eng: "The Operator shall ensure the management system is reviewed at intervals not exceeding one year to ensure its continuing suitability, adequacy and effectiveness in the management and control of operations and associated risks. The review shall include assessing opportunities for improvement and the need for changes to the system, including, but not limited to:\n(i) Organizational structure;\n(ii) Defined safety objectives;\n(iii) Reporting lines, authorities, responsibilities;\n(iv) Policies, processes and procedures;\n(v) Allocation of resources;\n(vi) Identification of training needs. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed corporate management review process (focus: process identifies organizational opportunities for changes/improvement to management system).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Examined selected records of management review meetings.\n▪ Examined selected examples of output from management review process (focus: changes implemented to improve organizational performance).\n▪ Other Actions (Specify)\n\nGuidance:\nManagement review is a necessary element of a well-managed company that provides a medium through which organizational control and continual improvement can be delivered. To be effective, a formal management review takes place on a regular basis, typically once or more per year. The management review would focus on the entire management system, including the assessment of the effectiveness of the SMS processes.\nThe management review would typically be conducted by a strategic committee of senior management officials that are familiar with the workings and objectives of the management system. If the review of the SMS is conducted separately, such committee is typically referred to as a Safety Review Board (SRB), which is a very high level, strategic committee chaired by the AE and composed of senior managers, including senior line managers responsible for functional areas in operations (e.g. flight operations, engineering and maintenance, cabin operations).\nTo ensure frontline input as part of the review process, an operator would form multiple units of specially selected operational personnel (e.g. managers, supervisors, frontline personnel) that function to oversee safety in areas where operations are conducted. Such units are typically referred to as Safety Action Groups (SAGs), which are tactical committees that function to address implementation issues in frontline operations to satisfy the strategic directives of the SRB.\nAn appropriate method to satisfy this requirement is a periodic formal meeting of senior executives. The agenda of the meeting would typically include a general assessment of the management system to ensure all defined elements are functioning effectively and producing the desired operational safety outcomes consistent with defined safety objectives.\nSenior management ensures deficiencies identified during the management review are addressed through the implementation of organizational changes that will result in improvements to the management system.\nInput to the management review process would typically include:\n• Results of audits;\n• Findings from operational inspections and investigations;\n• Operational feedback;\n• Incidents and near-miss reports;\n• Changes in regulatory policy or civil aviation legislation;\n• Process performance and organizational conformance;\n• Status of corrective and preventative actions;\n• Results from implementation or rehearsal of the emergency response plan (ERP);\n• Follow-up actions from previous management reviews;\n• Feedback and recommendations for management system improvement;\n• Regulatory violations.\nOutput from the management review process would typically include decisions and actions related to:\n• Improvement of the processes throughout the management system;\n• Safety and security requirements;\n• Resource needs.\nThe management review is a formal process, which means documentation in the form of meeting schedules, agendas and minutes are produced and retained. Additionally, the output of the management review process would normally include action plans for changes to be implemented within the system where deemed appropriate.\nExamples of strategies that might improve the overall effectiveness of the management review process include:\n• Integrating the management review meeting into other performance review meetings;\n• Scheduling management review meetings frequently enough to ensure any action that might be required is timely;\n• Ensuring senior managers understand their responsibilities as part of the review process;\n• Ensuring action items resulting from meetings are documented and progress is tracked;\n• Ensuring there is always a responsible name associated with action items.\nExpanded guidance related to review of the SMS may be found in the ICAO SMM, Document 9859.", zh: "运营人应确保以不超过一年的间隔对管理系统进行评审，以确保其在管理和控制运行及相关风险方面的持续适宜性、充分性和有效性。评审应包括评估改进机会和系统变更需求，包括但不限于：\n(i) 组织结构；\n(ii) 定义的安全目标；\n(iii) 报告线、权限、职责；\n(iv) 政策、流程和程序；\n(v) 资源分配；\n(vi) 识别培训需求。(GM)\n\n审计员行动：\n▪ 识别/评估公司管理评审流程（重点：流程识别组织对管理系统进行变更/改进的机会）\n▪ 访谈AE和/或指定管理代表\n▪ 检查选定的管理评审会议记录\n▪ 检查管理评审流程输出的选定示例（重点：为改进组织绩效而实施的变更）\n▪ 其他行动（请说明）\n\n指导材料：\n管理评审是管理良好的公司的必要元素，它提供了一个可以实现组织控制和持续改进的媒介。为了有效，正式的管理评审定期进行，通常每年一次或多次。管理评审将关注整个管理系统，包括评估SMS流程的有效性。\n管理评审通常由熟悉管理系统运作和目标的高级管理人员战略委员会进行。如果SMS的评审是单独进行的，该委员会通常称为安全审查委员会（SRB），这是一个非常高层的战略委员会，由AE担任主席，由高级经理组成，包括负责运行职能领域（例如飞行运行、工程与维修、客舱运行）的高级直线经理。\n为了确保一线输入作为评审过程的一部分，运营人将组建多个由特别挑选的运行人员（例如经理、主管、一线人员）组成的单位，其职能是监督运行区域的安全。这些单位通常称为安全行动组（SAG），是战术委员会，其职能是解决一线运行中的实施问题，以满足SRB的战略指令。\n满足此要求的适当方法是高级管理人员的定期正式会议。会议议程通常包括对管理系统的总体评估，以确保所有定义的元素有效运行，并产生与定义的安全目标一致所需的运行安全结果。\n高级管理层确保通过实施组织变革来解决管理评审期间发现的缺陷，从而改进管理系统。\n管理评审流程的输入通常包括：\n• 审计结果；\n• 运行检查和调查的发现；\n• 运行反馈；\n• 事件和未遂事件报告；\n• 监管政策或民用航空立法的变化；\n• 流程绩效和组织符合性；\n• 纠正和预防措施的状态；\n• 应急响应计划（ERP）实施或演练的结果；\n• 以前管理评审的后续行动；\n• 对管理系统改进的反馈和建议；\n• 违规行为。\n管理评审流程的输出通常包括与以下相关的决策和行动：\n• 改进整个管理系统的流程；\n• 安全和安保要求；\n• 资源需求。\n管理评审是一个正式流程，这意味着以会议时间表、议程和会议纪要形式的文件被制作和保留。此外，管理评审流程的输出通常包括在认为适当的情况下在系统内实施变更的行动计划。\n可能提高管理评审流程整体有效性的策略示例包括：\n• 将管理评审会议整合到其他绩效评审会议中；\n• 足够频繁地安排管理评审会议，以确保任何可能需要的行动都能及时进行；\n• 确保高级经理理解他们作为评审过程一部分的责任；\n• 确保会议产生的行动项目被记录并跟踪进度；\n• 确保每个行动项目始终有一个负责人。\n有关SMS评审的扩展指导可在ICAO SMM，文件9859中找到。" },
            { subtitle: "ORG 4.1.2 QA与风险管理事项评审", eng: "The Operator shall have a process to ensure significant issues arising from quality assurance and risk management are subject to management review in accordance with ORG 4.1.1. [SMS] (GM) ►\n\nNote: Conformity with this provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed corporate management review process (focus: quality assurance and risk management issues are included in the management review process).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Interviewed quality assurance program manager.\n▪ Examined selected records/documents of management review (focus: specific issues/changes identified/implemented to improve quality assurance and risk management programs).\n▪ Coordinated to verify management review of significant quality assurance issues in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nManagement review supports safety performance monitoring and continuous improvement of the SMS, which are elements of the Safety Assurance component of the SMS Framework.\nSuch review permits senior management to consider quality assurance and risk management issues that have the potential to affect the safety of operations and then ensure appropriate corrective or preventive actions are implemented and are being monitored for effectiveness in preventing accidents and incidents.\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.", zh: "运营人应制定流程，确保质量保证和风险管理产生的重大问题根据ORG 4.1.1接受管理评审。[SMS] (GM) ►\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估公司管理评审流程（重点：质量保证和风险管理问题包含在管理评审流程中）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 访谈质量保证方案经理\n▪ 检查选定的管理评审记录/文件（重点：为改进质量保证和风险管理方案而识别/实施的特定问题/变更）\n▪ 协调验证所有运行领域重大质量保证问题的管理评审\n▪ 其他行动（请说明）\n\n指导材料：\n管理评审支持安全绩效监控和SMS的持续改进，这是SMS框架中安全保证组成部分的要素。\n此类评审允许高级管理层考虑可能影响运行安全的质量保证和风险管理问题，然后确保实施适当的纠正或预防措施，并监控其在预防事故和事件方面的有效性。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。" },
            { subtitle: "ORG 4.1.3 SMS有效性监控", eng: "The Operator shall have processes to monitor and assess its SMS processes in order to maintain or continually improve the overall effectiveness of the SMS. [SMS] [MA] (GM)\n\nAuditor Actions:\n▪ Identified/Assessed SMS review process (focus: processes for monitoring and assessing SMS to maintain/improve safety performance).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Examined selected examples of output from SMS review process (focus: changes implemented to maintain/improve organizational safety performance).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definitions of Safety Assurance, Safety Action Group (SAG) and Safety Review Board (SRB).\nSafety performance monitoring and measurement is an element of the Safety Assurance component of the SMS framework.\nMonitoring and assessing the effectiveness of SMS processes would normally be the function of a strategic committee of senior management officials that are familiar with the workings and objectives of the SMS. Such committee is typically referred to as a Safety Review Board (SRB), which is a very high-level, strategic committee chaired by the AE and composed of senior managers, including senior line managers responsible for functional areas in operations (e.g. flight operations, engineering and maintenance, cabin operations).\nTo ensure frontline input as part of the SMS review process, an operator would form multiple units of specially selected operational personnel (e.g. managers, supervisors, frontline personnel) that function to oversee safety in areas where operations are conducted. Such units are typically referred to as Safety Action Groups (SAGs), which are tactical committees that function to address implementation issues in frontline operations to satisfy the strategic directives of the SRB.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: Effectiveness of the SMS is improved through actions taken as a result of monitoring and assessment activities conducted by the Operator.\nSuitability Considerations: • Data sources and inputs used for monitoring and assessment of SMS processes.\nC1 (Established): Significant risks are presented, and mitigations are discussed during the Management and/or Safety Review. Status on progress for resulting actions is included in the follow-up agendas of the meeting.\nC2 (Established): Management and/or Safety Review are supported with detailed input as per ORG 4.1.1 GM from all operational areas and or detailed information related to safety issues (SRAs).\nC3 (Established): There is active and regular participation to Management and/or Safety Review by Accountable Executive and all Senior Management.\nC4 (Mature): Aggregated safety performance information to include relevant SPIs are reviewed during the Management and/or Safety Review to monitor and assess the effectiveness of SMS processes.\nC5 (Mature): Management and/or Safety Review actions are effectively implemented and followed-up.\nC6 (Mature): The assessment of the effectiveness of SMS processes is conducted through clearly identified performance indicators at least every six months.\nC7 (Mature): The organisation cooperates with industry and/or academic partners to develop, identify and implement safety best practices.\nC8 (Leading): Detailed actions and/or action plans to improve safety culture are periodically defined and implemented effectively.\nC9 (Leading): Internal and external lessons learnt are continuously incorporated into SMS and operational processes.\nC10 (Leading): Safety improvements are planned and implemented as a result of analysis of external industry best practices during Safety Review Board or similar.\nC11 (Leading): Safety improvements are planned and implemented as a result of analysis of internal and external safety investigations during Safety Review Board or similar.", zh: "运营人应制定监控和评估其SMS流程的流程，以维持或持续改进SMS的整体有效性。[SMS] [MA] (GM)\n\n审计员行动：\n▪ 识别/评估SMS评审流程（重点：监控和评估SMS以维持/改进安全绩效的流程）\n▪ 访谈AE和/或指定管理代表\n▪ 检查SMS评审流程输出的选定示例（重点：为维持/改进组织安全绩效而实施的变更）\n▪ 其他行动（请说明）\n\n指导材料：\n安全保证、安全行动组（SAG）和安全审查委员会（SRB）的定义请参阅IRM。\n安全绩效监控和测量是SMS框架中安全保证组成部分的一个要素。\n监控和评估SMS流程的有效性通常是熟悉SMS运作和目标的高级管理人员战略委员会的职能。该委员会通常称为安全审查委员会（SRB），是一个非常高层的战略委员会，由AE担任主席，由高级经理组成，包括负责运行职能领域（例如飞行运行、工程与维修、客舱运行）的高级直线经理。\n为了确保一线输入作为SMS评审过程的一部分，运营人将组建多个由特别挑选的运行人员（例如经理、主管、一线人员）组成的单位，其职能是监督运行区域的安全。这些单位通常称为安全行动组（SAG），是战术委员会，其职能是解决一线运行中的实施问题，以满足SRB的战略指令。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：通过运营人进行的监控和评估活动所采取的行动，改进SMS的有效性。\n充分性考虑：• 用于监控和评估SMS流程的数据源和输入。\nC1（建立）：在管理和/或安全评审期间呈现重大风险并讨论缓解措施。由此产生的行动进展情况包含在会议的后续议程中。\nC2（建立）：管理和/或安全评审得到来自所有运行领域的详细输入（根据ORG 4.1.1 GM）和/或与安全问题相关的详细信息（SRA）的支持。\nC3（建立）：责任人和所有高级管理层积极定期参与管理和/或安全评审。\nC4（成熟）：在管理和/或安全评审期间审查汇总的安全绩效信息（包括相关SPI），以监控和评估SMS流程的有效性。\nC5（成熟）：管理和/或安全评审行动得到有效实施和跟踪。\nC6（成熟）：至少每六个月通过明确定义的绩效指标对SMS流程的有效性进行评估。\nC7（成熟）：组织与行业和/或学术合作伙伴合作，制定、识别和实施安全最佳实践。\nC8（领先）：定期定义并有效实施改善安全文化的详细行动和/或行动计划。\nC9（领先）：内部和外部的经验教训持续纳入SMS和运行流程。\nC10（领先）：在安全审查委员会或类似机构分析外部行业最佳实践的结果，规划和实施安全改进。\nC11（领先）：在安全审查委员会或类似机构分析内部和外部安全调查的结果，规划和实施安全改进。" }
        ]
    },

        safety_comm: {
        title: "4.2 安全沟通 - Safety Communication",
        sections: [
            { subtitle: "ORG 4.2.1 安全信息沟通系统", eng: "The Operator shall have a system that enables effective communication of safety and operational information throughout the management system and in all areas where operations are conducted. Such system shall ensure:\n(i) Personnel maintain an awareness of the SMS;\n(ii) Safety-critical information is conveyed;\n(iii) External service providers are provided with information relevant to operations conducted. [SMS] [MA] (GM) ►\n\nAuditor Actions:\n▪ Identified/Assessed organizational communication system (focus: safety and operational information is communicated throughout the organization and to relevant external service providers).\n▪ Interviewed AE and/or designated management representative(s).\n▪ Examined examples or records of information communication.\n▪ Interviewed selected management system personnel.\n▪ Coordinated to verify implementation of communication system in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nSafety communication is an element of the Safety Promotion component of the SMS framework.\nAn effective communication system ensures the exchange of operational and safety-related information throughout all areas of the organization and includes senior managers, operational managers and front-line personnel.\nTo be totally effective, the communication system would also include external organizations that conduct outsourced operational functions. Communication with external service providers would typically be limited to information that is pertinent and relevant to the provider's services delivered to the operator. It would be at the operator's discretion to define the extent and content of such communication and the delivery method(s) to be used.\nMethods of internal communication will vary according to the size and scope of the organization. However, to be effective, methods are as uncomplicated and easy to use as is possible and facilitate the reporting of operational deficiencies, hazards or concerns by operational personnel.\nSpecific methods of communication between management and operational personnel could include:\n• Email, Internet;\n• Safety or operational reporting system;\n• Communiqués (e.g. letters, memos, bulletins);\n• Publications (e.g. newsletters, magazines).\nIf email is used as an official medium for communication with operational personnel, the process is typically formalized by the operator to ensure control and effectiveness.\nThe general intent of safety communication is to foster a positive safety culture in which all employees receive ongoing information on safety issues, safety metrics, specific hazards existing in the workplace and initiatives to address known safety issues. Such communication typically conveys safety-critical information, explains why particular actions are taken to improve safety and why safety procedures are introduced or changed.\nInformation and issues relevant to safety performance are typically derived from various sources such as, but not limited to, the quality assurance/flight safety analysis programs, operational safety reporting and accident/incident investigations.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: All personnel as well as external service providers to the extent feasible, are aware of the current state of the management system and its performance. They are also aware of any relevant new risks or trends that may negatively influence the safety performance. There is a general awareness of the role and the outputs of the management system and what it intends to achieve.\nSuitability Considerations: • Extent of information provided. • Scope of information provided. • Frequency of updates. • Means used to communicate.\nC1 (Established): The Operator communicates safety and operationally critical information through variety of effective methods as appropriate to the size and complexity of the organization.\nC2 (Established): Safety critical information is communicated in a timely manner.\nC3 (Established): The means of communication are adapted to the audience and the significance of what is being communicated.\nC4 (Established): The Operator has a clearly described process to determine what, when, and how safety information needs to be communicated.\nC5 (Mature): The Operator provides regular information to all operational personnel on emerging safety issues, safety metrics, specific hazards/risks of the Operator and initiatives to address known safety issues.\nC6 (Mature): All relevant findings, contributing factors, recommendations and hazards identified from internal and/or external audits and/or investigations are shared internally within the organization.\nC7 (Mature): Periodic safety promotion sessions are organised both internally and with applicable external organisations.\nC8 (Mature): All operational personnel are aware of recently communicated safety and operationally critical information.\nC9 (Mature): All internal and external safety lessons learned are systematically communicated throughout the organisation at all appropriate levels.\nC10 (Leading): Safety-related best practices are shared to a wide extent with industry stakeholders.\nC11 (Leading): Human factors and human performance related content are shared through safety internal communications to increase awareness within the Operator.\nC12 (Leading): Operator conducts regular safety culture surveys such as I-ASC (IATA Aviation Safety Culture Survey) for at least some operational areas and implements related improvement program to measure and continuously improve the safety culture.\nC13 (Leading): Operator conducts regular safety culture surveys such as I-ASC: IATA Aviation Safety Culture Survey for all operational areas and implements related improvement program to measure and continuously improve the safety culture.\nC14 (Leading): Safety communication content and methods are regularly assessed to identify level of understanding for continual improvement.\nC15 (Leading): Safety data and information are shared externally with industry peers and/or recognized entities.\nC16 (Leading): The results of the safety culture surveys and/or assessments are communicated throughout the organisation.", zh: "运营人应建立能够在整个管理系统和所有运行区域有效沟通安全和运行信息的系统。该系统应确保：\n(i) 人员保持对SMS的认识；\n(ii) 传达安全关键信息；\n(iii) 向外部服务提供商提供与运行相关的信息。[SMS] [MA] (GM) ►\n\n审计员行动：\n▪ 识别/评估组织沟通系统（重点：安全和运行信息在整个组织内和向相关外部服务提供商传达）\n▪ 访谈AE和/或指定管理代表\n▪ 检查信息沟通的示例或记录\n▪ 访谈选定的管理系统人员\n▪ 协调验证所有运行领域沟通系统的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\n安全沟通是SMS框架中安全促进组成部分的一个要素。\n有效的沟通系统确保运行和安全相关信息在整个组织的所有区域进行交换，包括高级经理、运行经理和一线人员。\n为了完全有效，沟通系统还应包括执行外委运行职能的外部组织。与外部服务提供商的沟通通常限于与提供商向运营人交付的服务相关和关联的信息。定义此类沟通的范围、内容以及要使用的交付方法由运营人自行决定。\n内部沟通的方法将根据组织的规模和范围而有所不同。然而，为了有效，方法应尽可能简单易用，并便利运行人员报告运行缺陷、危险或关切。\n管理层与运行人员之间的具体沟通方法可包括：\n• 电子邮件、互联网；\n• 安全或运行报告系统；\n• 公报（例如信件、备忘录、公告）；\n• 出版物（例如时事通讯、杂志）。\n如果使用电子邮件作为与运行人员沟通的官方媒介，则运营人通常会正式化该流程以确保控制和有效性。\n安全沟通的总体意图是培养积极的安全文化，在这种文化中，所有员工持续接收关于安全问题、安全指标、工作场所中存在的特定危险以及解决已知安全问题的措施的信息。此类沟通通常传达安全关键信息，解释为什么采取特定行动来改善安全，以及为什么引入或更改安全程序。\n与安全绩效相关的信息和问题通常来自各种来源，例如但不限于质量保证/飞行安全分析方案、运行安全报告和事故/征候调查。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：所有人员以及在可行范围内的外部服务提供商，都了解管理系统的当前状态及其绩效。他们还了解任何可能对安全绩效产生负面影响的相关新风险或趋势。对管理系统的角色和输出及其预期目标有普遍认识。\n充分性考虑：• 所提供信息的范围。• 所提供信息的范围。• 更新频率。• 沟通方式。\nC1（建立）：运营人根据组织的规模和复杂性，通过多种有效方法传达安全和运行关键信息。\nC2（建立）：安全关键信息及时传达。\nC3（建立）：沟通方式根据受众和所传达信息的重要性进行调整。\nC4（建立）：运营人有清晰描述的过程来确定需要沟通什么、何时沟通以及如何沟通安全信息。\nC5（成熟）：运营人定期向所有运行人员提供关于新兴安全问题、安全指标、运营人的特定危险/风险以及解决已知安全问题的措施的信息。\nC6（成熟）：从内部和/或外部审计和/或调查中识别的所有相关发现、促成因素、建议和危险在组织内部共享。\nC7（成熟）：定期在内部以及与适用的外部组织组织安全促进会议。\nC8（成熟）：所有运行人员都了解最近传达的安全和运行关键信息。\nC9（成熟）：所有内部和外部的安全经验教训系统地在整个组织的所有适当层面传达。\nC10（领先）：与安全相关的最佳实践广泛地与行业利益相关者共享。\nC11（领先）：通过安全内部沟通共享人为因素和人为表现相关内容，以提高运营人内部的认识。\nC12（领先）：运营人对至少某些运行领域进行定期安全文化调查（例如I-ASC：IATA航空安全文化调查），并实施相关改进计划来衡量和持续改进安全文化。\nC13（领先）：运营人对所有运行领域进行定期安全文化调查（例如I-ASC：IATA航空安全文化调查），并实施相关改进计划来衡量和持续改进安全文化。\nC14（领先）：定期评估安全沟通内容和方法，以确定理解水平以持续改进。\nC15（领先）：安全数据和信息与行业同行和/或认可实体在外部共享。\nC16（领先）：安全文化调查和/或评估的结果在整个组织内传达。" }
        ]
    },

        training: {
        title: "4.3 培训 - Training",
        sections: [
            { subtitle: "ORG 4.3.1 内部人员SMS培训", eng: "The Operator shall have a program that ensures its personnel are trained to understand SMS responsibilities and competent to perform associated duties. The scope of such training shall be appropriate to each individual's involvement in the SMS. [SMS] [MA] (GM) ►\n\nNote: The specifications of this provision are applicable to personnel of the Operator.\n\nNote: Conformity with this ORG provision is possible only when the Operator is in conformity with all repeats of this provision in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed SMS training program (focus: program ensures training for the operator's personnel as appropriate to individual SMS involvement).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected SMS training curricula/syllabi (focus: personnel are trained to understand SMS responsibilities and to perform associated SMS duties).\n▪ Examined selected management/non-management personnel training records (focus: completion of SMS training relevant to individual involvement in the SMS).\n▪ Coordinated to verify SMS training is implemented in all operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nSMS training is an element of the Safety Promotion component of the SMS framework.\nWithin an operator's organization there are personnel that perform duties that are directly or indirectly related to the safety of aircraft operations. All such personnel thus have an involvement in the operator's SMS. This applies to management and non-management personnel in frontline operational positions and could also include others that perform certain administrative functions. The intent of this provision is for the operator to have a program that ensures personnel are trained and competent to perform their SMS duties. Such program would include training for support staff, operational personnel, managers and supervisors, senior managers and the accountable executive.\nThe content of safety training is appropriate to each individual's involvement in the SMS and typically includes or addresses some or all of the following subject areas:\n• Organizational safety policies, goals and objectives;\n• Organizational safety roles and responsibilities related to safety;\n• Organizational SMS processes and procedures;\n• Basic safety risk management principles;\n• Safety reporting systems;\n• Human factors.\nRecurrent training would be offered at the option of the operator to ensure personnel maintain continuing competency in SMS duties. If offered, such training would typically focus on changes to SMS policies, processes and procedures as well as any specific safety issues relevant to the organization.\nAn operator may use various methods to verify if personnel are competent to perform their duties at the conclusion of the training. The methods used would be solely at the discretion of the operator and would typically be based on the depth and detail of the training provided. Such methods may include a combination of the following:\n• Including knowledge checks during the training modules;\n• Performing Q&A sessions at the conclusion of a module or training session;\n• Including practical exercises with feedback;\n• Observing the staff member during the performance of SMS duties;\n• Administering an oral or written test.\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.\nExpanded guidance may be found in the ICAO SMM, Document 9859.\n\nAssessment Tool\nDesired Outcome: All personnel within the organization are appropriately qualified for their role and have pertinent knowledge and skills to participate effectively within the SMS.\nSuitability Considerations: • Scope of the training and content based on individual's role. • Methods and materials used for the delivery of the training.\nC1 (Established): All operational personnel understand their role in the Operator's SMS and safety duties & responsibilities.\nC2 (Established): Safety training material includes human and organisational factors and non-technical skills with the intent of reducing human error.\nC3 (Established): SMS training program is effectively customized for each operational function's involvement in the SMS.\nC4 (Established): The Operator identifies, assesses and maintains the qualification and competence requirements of the SMS trainers/instructors.\nC5 (Mature): SMS training is regularly reviewed for all aspects to include learning objectives, training material, teaching methods and test/exams and updated accordingly.\nC6 (Mature): The Operator measures the effectiveness of SMS training through feedback collected from trainees, internal and/or external maturity assessment of the SMS training and take appropriate actions to improve subsequent training.\nC7 (Mature): The SMS training program includes a recurrent training for each individual.\nC8 (Mature): Operator has a program that ensures personnel of external service providers are trained to understand SMS responsibilities and perform associated duties as per ORG 4.3.2.\nC9 (Mature): SMS recurrent training includes changes to the SMS policies and processes, specific safety issues relevant to the Operator or lessons learned.\nC10 (Leading): The training material (content) includes recent lessons learned from internal and external occurrences and/or investigations, Operator's significant hazards, risks and associated mitigating actions.\nC11 (Leading): The Accountable executive and senior management undergo a dedicated and comprehensive training on safety culture and promotion of the SMS.\nC12 (Leading): The Operator participates in safety related conferences, working groups etc. and/or receive external SMS training to continuously improve its safety training.\nC13 (Leading): The latest academic and scientific insights on safety management and training methodologies are considered for the development of the SMS training.\nC14 (Leading): A formal SMS training needs analysis is regularly conducted to ensure there is a clear understanding of the operation, the safety duties of the personnel and the applicable training.\nC15 (Leading): The Operator provides comprehensive and dedicated training to operational managers and all operational personnel on safety culture and its drivers.\nC16 (Leading): Operator delivers targeted or specific SMS training to personnel of all external service providers (e.g. hazard recognition, use of the operational safety reporting system).", zh: "运营人应制定方案，确保其人员接受培训以理解SMS职责，并具备执行相关职责的能力。此类培训的范围应适合每个人在SMS中的参与程度。[SMS] [MA] (GM) ►\n\n注：本条款的规范适用于运营人的人员。\n\n注：仅当运营人符合其他ISM部分中本条款的所有重复条款时，才可能符合本ORG条款。\n\n审计员行动：\n▪ 识别/评估SMS培训方案（重点：方案确保根据个人在SMS中的参与程度对运营人人员进行培训）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查选定的SMS培训课程/大纲（重点：培训人员理解SMS职责并执行相关SMS职责）\n▪ 检查选定的管理/非管理人员培训记录（重点：完成与个人在SMS中参与相关的SMS培训）\n▪ 协调验证所有运行领域SMS培训的实施情况\n▪ 其他行动（请说明）\n\n指导材料：\nSMS培训是SMS框架中安全促进组成部分的一个要素。\n在运营人的组织中，有执行与航空器运行安全直接或间接相关职责的人员。因此，所有这些人员都参与运营人的SMS。这适用于一线运行岗位的管理和非管理人员，也可能包括执行某些行政职能的其他人员。本条款的意图是让运营人有一个方案，确保人员接受培训并有能力执行其SMS职责。此类方案将包括对支持人员、运行人员、经理和主管、高级经理以及责任人的培训。\n安全培训的内容适合每个人在SMS中的参与程度，通常包括或涉及以下部分或全部主题领域：\n• 组织安全政策、目标和目的；\n• 与安全相关的组织安全角色和职责；\n• 组织SMS流程和程序；\n• 基本安全风险管理原则；\n• 安全报告系统；\n• 人为因素。\n复训将由运营人选择提供，以确保人员保持SMS职责的持续能力。如果提供，此类培训通常侧重于SMS政策、流程和程序的变更，以及与组织相关的任何特定安全问题。\n运营人可以使用各种方法来验证人员在培训结束时是否有能力履行职责。使用的方法完全由运营人自行决定，通常基于所提供培训的深度和细节。此类方法可能包括以下内容的组合：\n• 在培训模块期间包含知识检查；\n• 在模块或培训课程结束时进行问答环节；\n• 包含带有反馈的实践练习；\n• 在执行SMS职责期间观察员工；\n• 进行口试或笔试。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。\n扩展指导可参见ICAO SMM，文件9859。\n\n评估工具\n预期结果：组织内的所有人员都具备适合其角色的资格，并拥有有效参与SMS的相关知识和技能。\n充分性考虑：• 基于个人角色的培训范围和内容。• 用于提供培训的方法和材料。\nC1（建立）：所有运行人员了解他们在运营人SMS中的角色以及安全职责和责任。\nC2（建立）：安全培训材料包括人和组织因素以及非技术技能，旨在减少人为错误。\nC3（建立）：SMS培训方案针对每个运行职能在SMS中的参与进行有效定制。\nC4（建立）：运营人识别、评估和维护SMS培训师/指导员的资格和能力要求。\nC5（成熟）：定期审查SMS培训的各个方面，包括学习目标、培训材料、教学方法和测试/考试，并相应更新。\nC6（成熟）：运营人通过从学员收集的反馈、对SMS培训的内部和/或外部成熟度评估来衡量SMS培训的有效性，并采取适当行动改进后续培训。\nC7（成熟）：SMS培训方案包括对每个人的复训。\nC8（成熟）：运营人有一个方案，确保外部服务提供商的人员接受培训以理解SMS职责并根据ORG 4.3.2执行相关职责。\nC9（成熟）：SMS复训包括SMS政策和流程的变更、与运营人相关的特定安全问题或经验教训。\nC10（领先）：培训材料包括从内部和外部事件和/或调查中吸取的最新经验教训、运营人的重大危险、风险和相关缓解措施。\nC11（领先）：责任人和高级管理层接受关于安全文化和SMS推广的专门和全面培训。\nC12（领先）：运营人参与安全相关会议、工作组等和/或接受外部SMS培训，以持续改进其安全培训。\nC13（领先）：在制定SMS培训时考虑最新的安全管理和培训方法的学术和科学见解。\nC14（领先）：定期进行正式的SMS培训需求分析，以确保清楚了解运行、人员的安全职责和适用培训。\nC15（领先）：运营人为运行经理和所有运行人员提供关于安全文化及其驱动因素的全面和专门培训。\nC16（领先）：运营人向所有外部服务提供商的人员提供针对性或特定的SMS培训（例如危险识别、使用运行安全报告系统）。" },
            { subtitle: "ORG 4.3.2 外部人员SMS培训", eng: "If the Operator outsources operational functions to external service providers, the Operator should have a program that ensures personnel of external service providers are trained to understand SMS responsibilities and perform associated duties. The scope of such training should be appropriate to individual involvement in the Operator's SMS. [SMS] (GM) ►\n\nNote: The specifications of this provision are applicable to personnel of an external service provider that performs operational functions for the Operator.\n\nNote: Conformity with this ORG recommended practice is possible only when the Operator is in conformity with all repeats of this recommended practice in other ISM sections.\n\nAuditor Actions:\n▪ Identified/Assessed SMS training program (focus: program ensures training for personnel of external service providers as appropriate to individual SMS involvement).\n▪ Interviewed SMS manager and/or designated management representative(s).\n▪ Examined selected outsourcing contracts/agreements (focus: inclusion of requirement of SMS training for service provider personnel).\n▪ Examined selected records/reports resulting from monitoring of service providers (focus: monitoring process ensures personnel of service providers have completed SMS training).\n▪ Coordinated to verify SMS training for external service provider personnel is implemented in applicable operational areas.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of Operational Function.\nSMS training is an element of the Safety Promotion component of the SMS framework.\nIf an operator outsources operational functions, it would typically define initial and recurrent training standards to ensure training of service provider personnel is consistent with and meets the requirements of its own SMS.\nRecurrent training for personnel of providers, although recommended, would be specified at the option of the operator.\nTraining in accordance with this provision may be conducted by the operator, or by the service provider or other organization as long as the content and delivery of such training satisfies the SMS requirements of the operator.\nThe scope and content of such training would typically take into account the following:\n• Training required for personnel that would perform the same operational function within the operator's organization;\n• Individual personnel function(s) as related to the operator's SMS;\n• Exposure and/or involvement of the provider's personnel to the operational environment;\n• SMS elements the service provider already has in place.\nBased on a risk assessment and considering the above factors, an operator may conclude that SMS training is not required for personnel of providers that perform certain operational functions.\nAn operator might consider any of the following options as means for ensuring personnel of service providers complete training that satisfies the requirements of its own SMS:\n• If a service provider has an SMS, accept the service provider's SMS training;\n• If a service provider has an SMS, specify training in addition to that of the service provider (i.e. gap training) as applicable to ensure its own SMS requirements are satisfied;\n• Have applicable personnel of service providers complete the operator's own SMS training;\n• Deliver targeted or specific SMS training to personnel of service providers (e.g. hazard recognition, use of the operational safety reporting system).\nRefer to the IAH for information that identifies repeats of this ORG provision in other ISM sections.", zh: "如果运营人将运行职能外委给外部服务提供商，运营人应制定方案，确保外部服务提供商的人员接受培训以理解SMS职责并执行相关职责。此类培训的范围应适合个人在运营人SMS中的参与程度。[SMS] (GM) ►（推荐实践）\n\n注：本条款的规范适用于为运营人执行运行职能的外部服务提供商的人员。\n\n注：仅当运营人符合其他ISM部分中本推荐实践的所有重复条款时，才可能符合本ORG推荐实践。\n\n审计员行动：\n▪ 识别/评估SMS培训方案（重点：方案确保根据个人在SMS中的参与程度对外部服务提供商人员进行培训）\n▪ 访谈SMS经理和/或指定管理代表\n▪ 检查选定的外委合同/协议（重点：包含对服务提供商人员进行SMS培训的要求）\n▪ 检查选定的服务提供商监控产生的记录/报告（重点：监控流程确保服务提供商的人员已完成SMS培训）\n▪ 协调验证外部服务提供商人员的SMS培训在适用运行领域实施\n▪ 其他行动（请说明）\n\n指导材料：\n运行职能的定义请参阅IRM。\nSMS培训是SMS框架中安全促进组成部分的一个要素。\n如果运营人外委运行职能，通常将定义初始和复训标准，以确保服务提供商人员的培训与其自身SMS的要求一致并满足要求。\n对提供商人员的复训，虽然推荐，但由运营人选择指定。\n根据本条款进行的培训可以由运营人进行，也可以由服务提供商或其他组织进行，只要此类培训的内容和交付满足运营人的SMS要求。\n此类培训的范围和内容通常应考虑以下因素：\n• 在运营人组织内执行相同运行职能的人员所需的培训；\n• 与运营人SMS相关的个人职能；\n• 提供商人员暴露和/或参与运行环境的情况；\n• 服务提供商已经到位的SMS元素。\n基于风险评估并考虑上述因素，运营人可以得出结论，对于执行某些运行职能的提供商人员，不需要进行SMS培训。\n运营人可以考虑以下任何选项作为确保服务提供商人员完成满足其自身SMS要求的培训的手段：\n• 如果服务提供商有SMS，接受服务提供商的SMS培训；\n• 如果服务提供商有SMS，指定除服务提供商培训之外的培训（即差距培训），以确保满足其自身的SMS要求；\n• 让服务提供商的适用人员完成运营人自己的SMS培训；\n• 向服务提供商的人员提供针对性的或特定的SMS培训（例如危险识别、使用运行安全报告系统）。\n关于识别本ORG条款在其他ISM部分中重复的信息，请参阅IAH。" }
        ]
    },
    
    // ==================== 附录表格 ====================
           table_11: {
        title: "表1.1 文件体系规范 - Table 1.1 Documentation System Specifications",
        sections: [
            { 
                subtitle: "表1.1 文件体系规范 (Table 1.1 – Documentation System Specifications)", 
                eng: `<div style="overflow-x: auto;"><p style="background: #e2efe8; padding: 0.5rem 1rem; border-radius: 8px; font-weight: bold; margin: 0.5rem 0;">English Version</p><p style="font-style: italic; color: #2c6b55; margin-bottom: 0.5rem;">As specified in ORG 2.5.1, the Operator shall have a system for the management and control of documentation and/or data used directly in the conduct or support of operations. Such system shall comprise the elements specified below.</p><p style="font-size:0.8rem; margin-bottom: 0.5rem;"><strong>Note:</strong> Refer to the IRM for the definitions of Documentation, Electronic Documentation and Paper Documentation.</p><table style="width:100%; border-collapse: collapse; font-size: 0.8rem; margin: 0.5rem 0 1rem 0; background: white; border: 1px solid #d0ddd4;"><thead><tr style="background: #e2efe8;"><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: left; width: 50%;">Elements</th><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: center; width: 16%;">Type 1</th><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: center; width: 16%;">Type 2</th><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: center; width: 16%;">Type 3</th></tr></thead><tbody><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(i) Identification of the version and effective date of relevant documents and/or data.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Recommended</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Recommended</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(ii) Identification of the title and, if applicable, sub-titles of relevant documents and/or data.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Recommended</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Recommended</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(iii) Distribution and/or dissemination that ensures all users are provided relevant documents and/or data on or before the effective date: (a) Throughout appropriate areas of the organization; (b) To external service providers that conduct outsourced operational functions.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(iv) Definition of the specific media type(s) designated for presentation or display of the controlled version of relevant documents and/or data.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(v) Definition of documentation and/or data that is considered to be reproduced and/or obsolete.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(vi) Review and revision to maintain the currency of relevant documents and/or data.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(vii) Retention that ensures access to the content of relevant documents and/or data for a minimum period as defined by the Operator.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(viii) Provision for a scheduled backup by copying and archiving relevant documents and/or data, to include validation of the documents or data being backed up.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(ix) Identification and allocation of documentation access/user and modification rights.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(x) Dissemination and/or accessibility of documentation received from external sources such as regulatory authorities and original equipment manufacturers.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(xi) Identification of requirement for regulatory approval and/or acceptance.</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">Required</td></tr></tbody></table><p style="font-size:0.75rem; color:#6a8f7c;"><strong>Note:</strong> Required = conformity with ORG 2.5.1 requires this element. Recommended = optional but recommended.</p></div>`,
                zh: `<div style="overflow-x: auto;"><p style="background: #e2efe8; padding: 0.5rem 1rem; border-radius: 8px; font-weight: bold; margin: 0.5rem 0;">中文版本</p><p style="font-style: italic; color: #2c6b55; margin-bottom: 0.5rem;">根据 ORG 2.5.1 的规定，运营人应建立用于管理和控制直接用于运行开展或支持的文件和/或数据的系统。此类系统应包括以下规定的要素。</p><p style="font-size:0.8rem; margin-bottom: 0.5rem;"><strong>注：</strong>文件、电子文件和纸质文件的定义请参阅 IRM。</p><table style="width:100%; border-collapse: collapse; font-size: 0.8rem; margin: 0.5rem 0; background: white; border: 1px solid #d0ddd4;"><thead><tr style="background: #e2efe8;"><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: left; width: 50%;">要素</th><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: center; width: 16%;">类型1</th><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: center; width: 16%;">类型2</th><th style="border: 1px solid #cbd5d0; padding: 10px 8px; text-align: center; width: 16%;">类型3</th></tr></thead><tbody><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(i) 识别相关文件和/或数据的版本及生效日期</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">推荐</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">推荐</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(ii) 识别相关文件和/或数据的标题及（如适用）副标题</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">推荐</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">推荐</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(iii) 分发和/或传播，确保所有用户在生效日期或之前收到相关文件和/或数据：(a) 组织内各处；(b) 执行外委运行职能的外部服务提供商</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(iv) 指定用于展示或显示相关文件和/或数据受控版本的特定媒体类型</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(v) 定义被视为复制和/或作废的文件和/或数据</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(vi) 审查和修订以保持相关文件和/或数据的时效性</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(vii) 保留，确保在运营人定义的最短时间内可访问相关文件和/或数据的内容</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(viii) 通过复制和存档相关文件和/或数据来定期备份，包括验证被备份的文件或数据</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(ix) 识别和分配文件访问/用户和修改权限</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(x) 传播和/或提供从外部来源（如监管当局和原始设备制造商）收到的文件</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr><tr><td style="border: 1px solid #cbd5d0; padding: 8px;">(xi) 识别监管批准和/或接受的要求</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td><td style="border: 1px solid #cbd5d0; padding: 8px; text-align: center;">必须</td></tr></tbody></table><p style="font-size:0.75rem; color:#6a8f7c;"><strong>注：</strong>“必须”表示根据 ORG 2.5.1，此项是符合性所必需的。“推荐”表示可选但建议实施。</p></div>`
            }
        ]
    },
            table_12: {
        title: "表1.2 内部审计信息 - Table 1.2 Required Internal Audit Information",
        sections: [
            { 
                subtitle: "表1.2 内部审计信息 (Table 1.2 – Required Internal Audit Information)", 
                eng: `<div style="background: #f6fbf8; border-left: 4px solid #c49a6c; padding: 0.8rem 1.2rem; margin: 1rem 0; border-radius: 12px;"><p style="font-style: italic; color: #2c6b55; margin-bottom: 1rem;">As specified in ORG 2.1.4, the Operator shall ensure the following information associated with the internal audit of individual ISARPs is recorded and retained:</p><ol style="margin-left: 1.2rem; line-height: 1.8;"><li>The alpha-numeric identifier;</li><li>Appropriate documentation reference(s) (from the Operator's documentation system);</li><li>Auditor name(s);</li><li>Audit date(s);</li><li>If applicable, a description of non-conformance(s) and:<ol style="list-style-type: lower-alpha; margin-left: 1.5rem;"><li>The root cause(s) of non-conformance(s);</li><li>The corrective action(s) implemented to address non-conformance(s).</li></ol></li><li>If applicable, a description of non-applicability (N/A);</li><li>The current status of conformance (documented and implemented). <strong>GM</strong></li></ol><p style="font-size:0.8rem; color:#6a8f7c; margin-top: 0.8rem; padding-top: 0.5rem; border-top: 1px solid #d4e4dc;"><strong>Note:</strong> The above-specified audit information may be retained in the Operator's electronic database as specified in ORG 2.1.4 and ORG 2.4.1, or in controlled procedural documents.</p></div>`,
                zh: `<div style="background: #f6fbf8; border-left: 4px solid #c49a6c; padding: 0.8rem 1.2rem; margin: 1rem 0; border-radius: 12px;"><p style="font-style: italic; color: #2c6b55; margin-bottom: 1rem;">根据 ORG 2.1.4 的规定，运营人应确保记录和保留与单个 ISARPs 内部审计相关的以下信息：</p><ol style="margin-left: 1.2rem; line-height: 1.8;"><li>字母数字标识符；</li><li>适当的文件引用（来自运营人的文件系统）；</li><li>审计员姓名；</li><li>审计日期；</li><li>如适用，不符合项的描述以及：<ol style="list-style-type: lower-alpha; margin-left: 1.5rem;"><li>不符合项的根本原因；</li><li>为解决不符合项而实施的纠正措施。</li></ol></li><li>如适用，不适用（N/A）的描述；</li><li>当前的符合性状态（已文件化且已实施）。<strong>GM</strong></li></ol><p style="font-size:0.8rem; color:#6a8f7c; margin-top: 0.8rem; padding-top: 0.5rem; border-top: 1px solid #d4e4dc;"><strong>注：</strong>上述指定的审计信息可保存在 ORG 2.1.4 和 ORG 2.4.1 中规定的运营人电子数据库中，或保存在受控程序文件中。</p></div>`
            }
        ]
    },
        grh_36: {
        title: "GRH 3.6 机坪事件响应与报告 - Airside Event Response and Reporting",
        sections: [
            { subtitle: "GRH 3.6.1 地面操作应急管理计划", eng: "The Operator shall ensure an emergency management plan is in place for responding to accidents or other emergencies that may occur during aircraft ground handling operations. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed emergency management plan for ground handling operations.\n▪ Interviewed responsible manager(s) in ground handling operations.\n▪ Examined guidance/checklists used for response to emergencies in ground handling operations.\n▪ Examined selected records of emergency response exercises performed in accordance with the ERP.\n▪ Other Actions (Specify)\n\nGuidance:\nAn emergency management plan may also be known as a crisis or contingency management plan. It is a control mechanism to manage response procedures to a very serious situation (i.e. crisis) prior to that situation becoming a disaster. Control is achieved through preparation and the capability to implement emergency actions in a timely manner.\nTypical elements of an emergency management plan include ownership, crisis management team, communication and a control center.\nTo ensure continuing effectiveness, testing of an emergency management plan is typically undertaken periodically against various crisis scenarios.\nRefer to AHM 620 for guidance that addresses ground handling event response and reporting.", zh: "运营人应确保制定应急管理计划，用于应对飞机地面操作期间可能发生的事故或其他紧急情况。(GM)\n\n审计员行动：\n▪ 识别/评估地面操作应急管理计划\n▪ 访谈地面操作负责经理\n▪ 检查用于应对地面操作紧急情况的指导/检查单\n▪ 检查根据ERP进行的应急响应演练的选定记录\n▪ 其他行动（请说明）\n\n指导材料：\n应急管理计划也可称为危机或应急管理计划。它是一种控制机制，用于在非常严重的情况（即危机）变成灾难之前管理响应程序。控制通过准备和及时实施应急行动的能力来实现。\n应急管理计划的典型要素包括所有权、危机管理团队、沟通和控制中心。\n为了确保持续有效性，通常针对各种危机情景定期测试应急管理计划。\n有关地面操作事件响应和报告的指导，请参阅AHM 620。" },
            { subtitle: "GRH 3.6.2 飞机疏散应急程序", eng: "The Operator shall ensure procedures are in place for responding to emergencies that require the evacuation of an aircraft during the conduct of ground handling operations. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed procedures for responding to emergency aircraft evacuation during ground handling operations.\n▪ Interviewed responsible manager(s) in ground handling operations.\n▪ Examined guidance/checklists used for response to aircraft evacuation during ground handling operations.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to IGOM 6.5.3 for guidance that addresses aircraft evacuation. Additional guidance may be found in AHM 620.", zh: "运营人应确保制定程序，用于应对在地面操作期间需要疏散飞机的紧急情况。(GM)\n\n审计员行动：\n▪ 识别/评估地面操作期间应急飞机疏散的响应程序\n▪ 访谈地面操作负责经理\n▪ 检查用于地面操作期间飞机疏散响应的指导/检查单\n▪ 其他行动（请说明）\n\n指导材料：\n有关飞机疏散的指导，请参阅IGOM 6.5.3。更多指导可参见AHM 620。" },
            { subtitle: "GRH 3.6.3 地面操作事件响应", eng: "The Operator shall ensure procedures are in place for response to ground handling incidents. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed procedures for responding to incidents that occur in ground handling operations.\n▪ Interviewed responsible manager(s) in ground handling operations.\n▪ Examined guidance/checklists used for response to incidents in ground handling operations.\n▪ Examined selected records of responses to ground handling incidents.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to IGOM 6.5 for guidance that addresses incident notification and immediate actions. Additional guidance may be found in AHM 650 and 652.", zh: "运营人应确保制定程序，用于响应地面操作事件。(GM)\n\n审计员行动：\n▪ 识别/评估响应地面操作中发生的事件的程序\n▪ 访谈地面操作负责经理\n▪ 检查用于地面操作事件响应的指导/检查单\n▪ 检查地面操作事件响应的选定记录\n▪ 其他行动（请说明）\n\n指导材料：\n有关事件通知和即时行动的指导，请参阅IGOM 6.5。更多指导可参见AHM 650和652。" },
            { subtitle: "GRH 3.6.4 事故与事件记录保留", eng: "The Operator should ensure a process is in place for the retention of records of accidents and incidents associated with aircraft ground handling operations. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed process for retention of records of ground handling operations accidents/incidents.\n▪ Interviewed responsible manager(s) in ground handling operations.\n▪ Examined selected records of ground handling operations accidents/incidents (focus: records retained as defined by applicable process).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to AHM 650 for guidance that addresses ground handling event records retention.", zh: "运营人应确保制定流程，用于保留与飞机地面操作相关的事故和事件记录。（推荐实践）(GM)\n\n审计员行动：\n▪ 识别/评估地面操作事故/事件记录保留流程\n▪ 访谈地面操作负责经理\n▪ 检查选定的地面操作事故/事件记录（重点：按适用流程定义保留记录）\n▪ 其他行动（请说明）\n\n指导材料：\n有关地面操作事件记录保留的指导，请参阅AHM 650。" },
            { subtitle: "GRH 3.6.5 危险品事故与事件报告", eng: "The Operator shall ensure a process is in place that requires dangerous goods accidents and dangerous goods incidents to be reported to the appropriate authority of the State and the state in which the accident or incident occurred, and such reports are in accordance with the reporting requirements of the appropriate authorities. (GM)\n\nNote: The specifications of this provision are applicable to operators that transport, and also to operators that do not transport, dangerous goods as cargo.\n\nAuditor Actions:\n▪ Identified/Assessed process for reporting dangerous goods accidents/incidents.\n▪ Interviewed responsible manager(s) in ground handling operations.\n▪ Examined guidance used for reporting dangerous goods accidents/incidents.\n▪ Examined selected dangerous goods accident/incident reporting records (focus: reporting in accordance with reporting requirements of the appropriate authorities).\n▪ Examined selected dangerous goods accident/incident reports.\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of State.\nGuidance may be found in DGR 9.6.1 and 9.6.2.", zh: "运营人应确保制定流程，要求向国家当局和事故或事件发生所在国的适当当局报告危险品事故和危险品事件，并且此类报告应符合适当当局的报告要求。(GM)\n\n注：本条款的规范适用于运输危险品作为货物的运营人，也适用于不运输危险品作为货物的运营人。\n\n审计员行动：\n▪ 识别/评估报告危险品事故/事件的流程\n▪ 访谈地面操作负责经理\n▪ 检查用于报告危险品事故/事件的指导\n▪ 检查选定的危险品事故/事件报告记录（重点：按照适当当局的报告要求进行报告）\n▪ 检查选定的危险品事故/事件报告\n▪ 其他行动（请说明）\n\n指导材料：\n国家的定义请参阅IRM。\n指导可参见DGR 9.6.1和9.6.2。" },
            { subtitle: "GRH 3.6.6 危险品不符情况报告", eng: "If the Operator transports cargo, the Operator shall have a process to ensure a dangerous goods report is made to the appropriate authority of the State:\n(i) When dangerous goods are discovered to have been carried and not loaded, segregated, separated and/or secured in accordance with provisions of the DGR;\n(ii) When dangerous goods are discovered to have been carried as cargo without information as specified in GRH 3.3.4 having been provided to the PIC. (GM)\n\nAuditor Actions:\n▪ Identified/Assessed process for reporting dangerous goods discrepancies.\n▪ Interviewed responsible manager(s) in ground handling operations.\n▪ Examined dangerous goods discrepancy reports (focus: reports are submitted to the appropriate authority as specified).\n▪ Other Actions (Specify)\n\nGuidance:\nRefer to the IRM for the definition of State.\nGuidance may be found in DGR 9.6.4, GRH 1.8.3 Alignment with CGO 6.1.8.", zh: "如果运营人运输货物，运营人应制定流程，确保向国家适当当局提交危险品报告：\n(i) 当发现危险品的运输未按照DGR规定进行装载、隔离、分隔和/或固定时；\n(ii) 当发现危险品作为货物运输，但未按GRH 3.3.4规定向机长提供信息时。(GM)\n\n审计员行动：\n▪ 识别/评估报告危险品不符情况的流程\n▪ 访谈地面操作负责经理\n▪ 检查危险品不符情况报告（重点：报告按规定提交给适当当局）\n▪ 其他行动（请说明）\n\n指导材料：\n国家的定义请参阅IRM。\n指导可参见DGR 9.6.4、GRH 1.8.3与CGO 6.1.8的对齐。" }
        ]
    },
};

// 分组配置（基于 Ed 18 Rev 1 目录结构）
const groups = [
    { name: "适用性与概述", items: ["applicability", "general_guidance"] },
    { name: "1 管理与控制", items: ["mgmt_overview", "mgmt_commitment", "roles_resp", "safety_performance", "resource_mgmt", "outsourcing_mgmt", "emergency_response"] },
    { name: "2 保证、监控与文件控制", items: ["quality_assurance", "external_monitoring", "product_control", "data_management", "doc_system", "records_system"] },
    { name: "3 风险管理", items: ["hazard_id", "risk_assessment", "fda", "specific_risk", "occurrence_handling", "cybersecurity"] },
    { name: "4 改进与促进、培训", items: ["mgmt_review", "safety_comm", "training"] },
    { name: "表格附录", items: ["table_11", "table_12"] },
    { name: "GRH 3.6 机坪事件响应与报告", items: ["grh_36"] }
];

// 辅助函数
function formatText(text) {
    if (!text) return '';
    return text.replace(/\n/g, '<br>');
}

function renderChapter(chapterId) {
    const container = document.getElementById('dynamicContent');
    const chapter = chaptersData[chapterId];
    if (!chapter) return;

    let html = `<div class="chapter-card"><div class="chapter-title">${chapter.title}</div>`;
    chapter.sections.forEach(section => {
        html += `<div class="section-block">
                    <div class="section-sub">${section.subtitle}</div>
                    <div class="eng-text"><strong>English:</strong><br>${formatText(section.eng)}</div>
                    <div class="zh-text"><strong>中文参考：</strong><br>${formatText(section.zh)}</div>
                </div>`;
    });
    html += `</div>`;
    container.innerHTML = html;
}

// 构建可折叠分组导航
function buildNavigation() {
    const navMenu = document.getElementById('navMenu');
    if (!navMenu) return;
    navMenu.innerHTML = '';

    groups.forEach((group) => {
        const groupLi = document.createElement('li');
        groupLi.className = 'nav-group';
        
        const header = document.createElement('div');
        header.className = 'nav-group-header';
        header.innerHTML = `<span>${group.name}</span><span class="toggle-icon">▼</span>`;
        
        const subUl = document.createElement('ul');
        subUl.className = 'nav-group-items';
        
        group.items.forEach(itemId => {
            const item = chaptersData[itemId];
            if (!item) return;
            const li = document.createElement('li');
            li.className = 'nav-item';
            const a = document.createElement('a');
            a.href = '#';
            a.className = 'nav-link';
            a.setAttribute('data-chapter', itemId);
            a.textContent = item.title;
            a.addEventListener('click', (e) => {
                e.preventDefault();
                renderChapter(itemId);
                setActiveNav(itemId);
                window.location.hash = itemId;
            });
            li.appendChild(a);
            subUl.appendChild(li);
        });
        
        header.addEventListener('click', (e) => {
            e.stopPropagation();
            const isCollapsed = subUl.classList.contains('collapsed');
            if (isCollapsed) {
                subUl.classList.remove('collapsed');
                header.classList.remove('collapsed');
            } else {
                subUl.classList.add('collapsed');
                header.classList.add('collapsed');
            }
        });
        
        groupLi.appendChild(header);
        groupLi.appendChild(subUl);
        navMenu.appendChild(groupLi);
    });
}

function setActiveNav(activeId) {
    document.querySelectorAll('.nav-link').forEach(link => {
        const chap = link.getAttribute('data-chapter');
        if (chap === activeId) link.classList.add('active');
        else link.classList.remove('active');
    });
}

function init() {
    buildNavigation();
    let initChapter = 'applicability';
    if (window.location.hash && window.location.hash.length > 1) {
        const hashVal = window.location.hash.substring(1);
        if (chaptersData[hashVal]) initChapter = hashVal;
    }
    renderChapter(initChapter);
    setActiveNav(initChapter);
}

window.addEventListener('DOMContentLoaded', init);